import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'

// Mocks
vi.mock('inquirer', () => ({ default: { prompt: vi.fn() } }))
vi.mock('ora', () => ({ default: () => ({ start: () => ({ succeed: vi.fn(), fail: vi.fn(), info: vi.fn() }) }) }))
vi.mock('chalk', () => ({
  default: (() => {
    const color = (s: any) => String(s)
    const boldFn = Object.assign((s: any) => String(s), { blue: color, red: color })
    return { green: color, gray: color, cyan: color, white: color, red: color, blue: color, magenta: color, yellow: color, bold: boldFn }
  })()
}))

const dm = {
  init: vi.fn(),
  getTodoItems: vi.fn(),
  getTodoCategories: vi.fn(),
  addTodoItem: vi.fn(),
  updateTodoItem: vi.fn(),
  deleteTodoItem: vi.fn(),
}

vi.mock('../data.js', () => ({ dataManager: dm }))
vi.mock('../config.js', () => ({ loadConfig: vi.fn().mockResolvedValue({}) }))

describe('cli tasks command', () => {
  let logSpy: any
  beforeEach(() => {
    logSpy = vi.spyOn(console, 'log').mockImplementation(() => {})
    vi.useFakeTimers()
  })
  afterEach(() => {
    logSpy.mockRestore()
    vi.useRealTimers()
    vi.clearAllMocks()
  })

  it('lists tasks with tag filter', async () => {
    const now = new Date()
    dm.getTodoItems.mockResolvedValue([
      { id: '1', title: 'Work item', status: 'need-to-start', priority: 'medium', categoryId: 'c1', tags: ['work'], createdAt: now },
      { id: '2', title: 'Home item', status: 'done', priority: 'low', categoryId: 'c2', tags: ['home'], createdAt: now },
    ])
    dm.getTodoCategories.mockResolvedValue([
      { id: 'c1', name: 'Work', color: '#000', todos: [] },
      { id: 'c2', name: 'Home', color: '#000', todos: [] },
    ])

    const { handleListTasks } = await import('../commands/tasks')
    await handleListTasks({ tag: 'work' })

    expect(dm.getTodoItems).toHaveBeenCalled()
    // Expect output contains our filtered task title
    const printed = logSpy.mock.calls.map((c: any[]) => c.join(' ')).join('\n')
    expect(printed).toContain('Work item')
    expect(printed).not.toContain('Home item')
  })
})

import { describe, it, expect, vi, beforeEach } from 'vitest'

const dm = {
  init: vi.fn(),
  getTodoItems: vi.fn(),
  updateTodoItem: vi.fn(),
  deleteTodoItem: vi.fn(),
}

vi.mock('../data.js', () => ({ dataManager: dm }))
vi.mock('../config.js', () => ({ loadConfig: vi.fn().mockResolvedValue({}) }))
vi.mock('ora', () => ({ default: () => ({ start: () => ({ succeed: vi.fn(), fail: vi.fn(), info: vi.fn() }) }) }))
const promptMock = vi.fn()
vi.mock('inquirer', () => ({ default: { prompt: promptMock } }))
vi.mock('chalk', () => ({
  default: (() => {
    const color = (s: any) => String(s)
    const boldFn = Object.assign((s: any) => String(s), { blue: color, red: color })
    return { green: color, gray: color, cyan: color, white: color, red: color, blue: color, magenta: color, yellow: color, bold: boldFn }
  })()
}))

describe('cli task mutations (done/start/remove)', () => {
  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('marks a task as done via handleCompleteTask', async () => {
    const now = new Date()
    dm.getTodoItems.mockResolvedValue([{ id: 't1', title: 'My Task', status: 'need-to-start', priority: 'medium', categoryId: 'c1', createdAt: now, tags: [] }])
    const { handleCompleteTask } = await import('../commands/tasks')
    const res = await handleCompleteTask('My')
    expect(dm.updateTodoItem).toHaveBeenCalled()
    const [id, updates] = dm.updateTodoItem.mock.calls[0]
    expect(id).toBe('t1')
    expect((updates).status).toBe('done')
    expect(res).toEqual({ id: 't1', status: 'done' })
  })

  it('starts working on a task via handleStartTask', async () => {
    const now = new Date()
    dm.getTodoItems.mockResolvedValue([{ id: 't2', title: 'Start Me', status: 'need-to-start', priority: 'low', categoryId: 'c1', createdAt: now, tags: [] }])
    const { handleStartTask } = await import('../commands/tasks')
    const res = await handleStartTask('Start')
    expect(dm.updateTodoItem).toHaveBeenCalled()
    const [id, updates] = dm.updateTodoItem.mock.calls[0]
    expect(id).toBe('t2')
    expect((updates).status).toBe('currently-working')
    expect(res).toEqual({ id: 't2', status: 'currently-working' })
  })

  it('removes a task via handleRemoveTask with confirm', async () => {
    const now = new Date()
    dm.getTodoItems.mockResolvedValue([{ id: 't3', title: 'Remove Me', status: 'need-to-start', priority: 'low', categoryId: 'c1', createdAt: now, tags: [] }])
    promptMock.mockResolvedValue({ confirm: true })
    const { handleRemoveTask } = await import('../commands/tasks')
    const res = await handleRemoveTask('Remove')
    expect(dm.deleteTodoItem).toHaveBeenCalledWith('t3')
    expect(res).toEqual({ id: 't3' })
  })

  it('does not remove when user cancels', async () => {
    const now = new Date()
    dm.getTodoItems.mockResolvedValue([{ id: 't4', title: 'Do Not Remove', status: 'need-to-start', priority: 'low', categoryId: 'c1', createdAt: now, tags: [] }])
    promptMock.mockResolvedValue({ confirm: false })
    const { handleRemoveTask } = await import('../commands/tasks')
    const res = await handleRemoveTask('Do Not')
    expect(dm.deleteTodoItem).not.toHaveBeenCalled()
    expect(res).toBeNull()
  })

  it('returns null and no-op when task not found (status)', async () => {
    dm.getTodoItems.mockResolvedValue([])
    const { handleUpdateTaskStatus } = await import('../commands/tasks')
    const res = await handleUpdateTaskStatus('Missing', { status: 'done' })
    expect(res).toBeNull()
    expect(dm.updateTodoItem).not.toHaveBeenCalled()
  })
})

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { format } from 'date-fns'

const dm = {
  init: vi.fn(),
  getTodoItems: vi.fn(),
  getTodoCategories: vi.fn().mockResolvedValue([{ id: 'c1', name: 'Cat', color: '#000', todos: [] }]),
  updateTodoItem: vi.fn(),
}

vi.mock('../data.js', () => ({ dataManager: dm }))
vi.mock('../config.js', () => ({ loadConfig: vi.fn().mockResolvedValue({}) }))
vi.mock('inquirer', () => ({ default: { prompt: vi.fn().mockResolvedValue({ status: 'done' }) } }))
vi.mock('ora', () => ({ default: () => ({ start: () => ({ succeed: vi.fn(), fail: vi.fn(), info: vi.fn() }) }) }))
vi.mock('chalk', () => ({
  default: (() => {
    const color = (s: any) => String(s)
    const boldFn = Object.assign((s: any) => String(s), { blue: color, red: color })
    return { green: color, gray: color, cyan: color, white: color, red: color, blue: color, magenta: color, yellow: color, bold: boldFn }
  })()
}))

describe('cli tasks status & today', () => {
  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('updates task status to done', async () => {
    const now = new Date()
    dm.getTodoItems.mockResolvedValue([{ id: 't1', title: 'My Task', status: 'need-to-start', priority: 'medium', categoryId: 'c1', createdAt: now, tags: [] }])
    const { handleUpdateTaskStatus } = await import('../commands/tasks')
    await handleUpdateTaskStatus('My', {})
    expect(dm.updateTodoItem).toHaveBeenCalled()
    const [idArg, updates] = dm.updateTodoItem.mock.calls[0]
    expect(idArg).toBe('t1')
    expect((updates).status).toBeDefined()
  })

  it("prints today's overview", async () => {
    const today = new Date()
    const yesterday = new Date(today.getTime() - 24*60*60*1000)
    dm.getTodoItems.mockResolvedValue([
      { id: 't1', title: 'Due today', status: 'need-to-start', priority: 'low', categoryId: 'c1', dueDate: today, createdAt: today, tags: [] },
      { id: 't2', title: 'Overdue', status: 'need-to-start', priority: 'low', categoryId: 'c1', dueDate: yesterday, createdAt: yesterday, tags: [] },
    ])

    const logSpy = vi.spyOn(console, 'log').mockImplementation(() => {})
    const { handleTodayOverview } = await import('../commands/tasks')
    await handleTodayOverview()

    const output = logSpy.mock.calls.map((c) => c.join(' ')).join('\n')
    expect(output).toContain(format(today, 'EEEE, MMMM d, yyyy'))
    expect(output).toContain('📊 Quick Stats:')
    logSpy.mockRestore()
  })
})

import { Command } from 'commander';
import inquirer from 'inquirer';
import chalk from 'chalk';
import { loadConfig, saveConfig, updateConfig } from '../config.js';

export function createConfigCommand(): Command {
  const config = new Command('config')
    .description('Manage CLI configuration');

  // Show current config
  config
    .command('show')
    .alias('get')
    .description('Show current configuration')
    .action(async () => {
      try {
        const currentConfig = await loadConfig();

        logger.info('Config', chalk.bold.blue('Current Configuration:'));
        logger.info('Config', `  API URL: ${chalk.green(currentConfig.apiUrl)}`);
        logger.info('Config', `  Data Path: ${chalk.green(currentConfig.dataPath)}`);
        logger.info('Config', `  Username: ${chalk.green(currentConfig.username)}`);
        logger.info('Config', `  Default Store: ${chalk.green(currentConfig.defaultStore || 'Not set')}`);
        logger.info('Config', `  Default Meal Type: ${chalk.green(currentConfig.defaultMealType)}`);
        logger.info('Config', `  Default Category: ${chalk.green(currentConfig.defaultCategory)}`);

      } catch (error) {
        logger.error('Config', chalk.red('Failed to load configuration'), error);
      }
    });

  // Set config value
  config
    .command('set')
    .description('Set configuration value')
    .argument('<key>', 'Configuration key')
    .argument('[value]', 'Configuration value')
    .action(async (key, value) => {
      try {
        let newValue = value;

        // Interactive mode if no value provided
        if (!newValue) {
          const answer = await inquirer.prompt([
            {
              type: 'input',
              name: 'value',
              message: `Enter value for ${key}:`,
              validate: (input) => input.trim() !== '' || 'Value is required'
            }
          ]);
          newValue = answer.value;
        }

        await updateConfig({ [key]: newValue });
        logger.info('Config', chalk.green(`Set ${key} = ${newValue}`));

      } catch (error) {
        logger.error('Config', chalk.red('Failed to update configuration'), error);
      }
    });

  // Setup wizard
  config
    .command('setup')
    .alias('init')
    .description('Run initial setup wizard')
    .action(async () => {
      logger.info('Config', chalk.bold.blue('LifeSync CLI Setup'));
      logger.info('Config', chalk.gray('Configure your CLI preferences\n'));

      try {
        const currentConfig = await loadConfig();

        const answers = await inquirer.prompt([
          {
            type: 'input',
            name: 'username',
            message: 'Your name/username:',
            default: currentConfig.username
          },
          {
            type: 'input',
            name: 'apiUrl',
            message: 'API URL (if using web app sync):',
            default: currentConfig.apiUrl
          },
          {
            type: 'list',
            name: 'defaultMealType',
            message: 'Default meal type:',
            choices: ['breakfast', 'lunch', 'dinner', 'snack'],
            default: currentConfig.defaultMealType
          },
          {
            type: 'list',
            name: 'defaultCategory',
            message: 'Default shopping category:',
            choices: ['produce', 'dairy', 'meat', 'pantry', 'frozen', 'bakery', 'deli', 'household', 'personal', 'other'],
            default: currentConfig.defaultCategory
          }
        ]);

        await saveConfig({ ...currentConfig, ...answers });

        logger.info('Config', chalk.green('\n✓ Setup completed successfully!'));
        logger.info('Config', chalk.gray('You can now use LifeSync CLI commands.'));
        logger.info('Config', chalk.gray('Run "lifesync --help" to see available commands.'));

      } catch (error) {
        logger.error('Config', chalk.red('Setup failed'), error);
      }
    });

  // Reset config
  config
    .command('reset')
    .description('Reset configuration to defaults')
    .action(async () => {
      try {
        const confirmed = await inquirer.prompt([
          {
            type: 'confirm',
            name: 'confirm',
            message: 'Reset configuration to defaults?',
            default: false
          }
        ]);

        if (!confirmed.confirm) {
          logger.info('Config', chalk.yellow('Cancelled'));
          return;
        }

        const { DEFAULT_CONFIG } = await import('../config.js');
        await saveConfig(DEFAULT_CONFIG);

        logger.info('Config', chalk.green('Configuration reset to defaults'));

      } catch (error) {
        logger.error('Config', chalk.red('Failed to reset configuration'), error);
      }
    });

  return config;
}

