#!/usr/bin/env node

import { readFileSync, writeFileSync } from 'fs';
import { glob } from 'glob';

logger.info('FixUsestateImports', '🔧 Starting useState import fixes...');

// Get all TypeScript hook files
const files = glob.sync('src/hooks/*.{ts,tsx}', { 
  cwd: '/tmp/personalAssistant/lifesync',
  absolute: true 
});

let fixedFiles = 0;
let totalChanges = 0;

files.forEach(filePath => {
  try {
    const content = readFileSync(filePath, 'utf8');
    let newContent = content;
    let changes = 0;

    // Check if file uses useState but doesn't import it
    if (newContent.includes('useState') && !newContent.includes('import.*useState')) {
      // Check if there's already a React import line
      const reactImportMatch = newContent.match(/import\s*\{([^}]+)\}\s*from\s*['"]react['"];/);

      if (reactImportMatch) {
        // Add useState to existing import
        const currentImports = reactImportMatch[1];
        if (!currentImports.includes('useState')) {
          const newImports = currentImports.includes(',') 
            ? `useState, ${currentImports.trim()}`
            : `useState, ${currentImports.trim()}`;

          newContent = newContent.replace(
            /import\s*\{([^}]+)\}\s*from\s*['"]react['"];/,
            `import { ${newImports} } from 'react';`
          );
          changes++;
        }
      } else {
        // Add new React import at the top
        const firstImportMatch = newContent.match(/^import.*$/m);
        if (firstImportMatch) {
          newContent = newContent.replace(
            firstImportMatch[0],
            `import { useState } from 'react';\n${firstImportMatch[0]}`
          );
        } else {
          newContent = `import { useState } from 'react';\n${newContent}`;
        }
        changes++;
      }
    }

    if (changes > 0) {
      writeFileSync(filePath, newContent);
      logger.info('FixUsestateImports', `✅ Fixed useState import in ${filePath.split('/').pop()}`);
      fixedFiles++;
      totalChanges += changes;
    }

  } catch (error) {
    logger.error('FixUsestateImports', `❌ Error processing ${filePath}:`, error.message);
  }
});

logger.info('FixUsestateImports', `\n🎉 useState import fixes complete!`);
logger.info('FixUsestateImports', `📁 Fixed ${fixedFiles} files`);
logger.info('FixUsestateImports', `🔧 Made ${totalChanges} total changes`);

import { test, expect } from '@playwright/test'

test.describe('Focus Module', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/')
    await page.waitForLoadState('networkidle')

    // Navigate to focus page
    const focusNav = page.locator('[data-testid="nav-focus"]').first()
    if (await focusNav.isVisible()) {
      await focusNav.click()
      await page.waitForLoadState('networkidle')
    }
  })

  test('focus page loads correctly', async ({ page }) => {
    // Check that focus page elements are present
    await expect(page.locator('[data-testid="focus-container"]')).toBeVisible()

    // Check for key focus elements
    const focusElements = [
      '[data-testid="focus-timer"]',
      '[data-testid="focus-profile"]',
      '[data-testid="focus-sessions"]'
    ]

    for (const selector of focusElements) {
      const element = page.locator(selector).first()
      if (await element.isVisible()) {
        await expect(element).toBeVisible()
      }
    }
  })

  test('can start a focus session', async ({ page }) => {
    // Look for start session button
    const startButton = page.locator('[data-testid="start-focus-session"]').first()

    if (await startButton.isVisible()) {
      // Click start session
      await startButton.click()

      // Verify session started
      await expect(page.locator('[data-testid="active-session"]')).toBeVisible()

      // Check that timer is running
      const timer = page.locator('[data-testid="session-timer"]').first()
      if (await timer.isVisible()) {
        const initialTime = await timer.textContent()

        // Wait a moment and check if timer updated
        await page.waitForTimeout(2000)
        const updatedTime = await timer.textContent()

        // Timer should have changed (decreased)
        expect(updatedTime).not.toBe(initialTime)
      }
    }
  })

  test('can pause and resume focus session', async ({ page }) => {
    // Start a session first
    const startButton = page.locator('[data-testid="start-focus-session"]').first()
    if (await startButton.isVisible()) {
      await startButton.click()
      await page.waitForTimeout(1000)

