      await supabase.from('budgets').delete().eq('id', insertData[0].id);
      logger.info('DiscoverBudgetsSchema', 'Cleaned up test data');
    }
  }

  logger.info('DiscoverBudgetsSchema', '\n=== Schema Discovery Complete ===\n');
