type Any = any;

function readJSON(rel: string) {
  const p = path.join(process.cwd(), 'src/finance/data/seed', rel);
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

function uuid(): string {
  return crypto.randomUUID();
}

