  const userId = process.env.USER_ID || process.argv.find((a) => a.startsWith('--user='))?.split('=')[1];
  if (!url || !key) throw new Error('Missing VITE_SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY');
  if (!userId) throw new Error('Provide USER_ID env or --user=<uuid>');
  const client = createClient(url, key);

  const institutions: Any[] = readJSON('institutions.json');
  const accounts: Any[] = readJSON('accounts.json');
  const categories: Any[] = readJSON('categories.json');
  const transactions: Any[] = readJSON('transactions.json');
  const budgets: Any[] = readJSON('budgets.json');
  const networth: Any[] = readJSON('networth.json');
  const goals: Any[] = readJSON('goals.json');

  const idMap = new Map<string, string>();
  const mapId = (id?: string) => (id ? (idMap.get(id) || (idMap.set(id, uuid()), idMap.get(id)!)) : undefined);

  // Institutions
  if (institutions.length) {
    const rows = institutions.map((i) => ({ id: mapId(i.id), user_id: userId, name: i.name, logo_url: i.logoUrl ?? null }));
    const { error } = await client.from('institutions').upsert(rows, { onConflict: 'id' });
    if (error) throw error;
    logger.info('SeedFinance', `Inserted ${rows.length} institutions`);
  }

  // Categories
  if (categories.length) {
    const rows = categories.map((c) => ({ id: mapId(c.id), user_id: userId, name: c.name, parent_id: mapId(c.parentId) ?? null, icon: c.icon ?? null, color: c.color ?? null }));
    const { error } = await client.from('categories').upsert(rows, { onConflict: 'id' });
    if (error) throw error;
    logger.info('SeedFinance', `Inserted ${rows.length} categories`);
  }

  // Accounts
  if (accounts.length) {
    const rows = accounts.map((a) => ({
      id: mapId(a.id),
      user_id: userId,
      institution_id: mapId(a.institutionId) ?? null,
      name: a.name,
      type: a.type,
      balance: a.balance,
      liability: !!a.liability,
      last_updated: a.lastUpdatedISO ?? new Date().toISOString(),
    }));
    const { error } = await client.from('accounts').upsert(rows, { onConflict: 'id' });
    if (error) throw error;
    logger.info('SeedFinance', `Inserted ${rows.length} accounts`);
  }

  // Transactions
  if (transactions.length) {
    const rows = transactions.map((t) => ({
      id: mapId(t.id),
      user_id: userId,
      account_id: mapId(t.accountId),
      date: t.dateISO,
      description: t.description,
      category_id: mapId(t.categoryId) ?? null,
      amount: t.amount,
      type: t.type,
      notes: t.notes ?? null,
    }));
    const { error } = await client.from('transactions').upsert(rows, { onConflict: 'id' });
    if (error) throw error;
    logger.info('SeedFinance', `Inserted ${rows.length} transactions`);
  }

  // Budgets
  if (budgets.length) {
    const rows = budgets.map((b) => ({
      id: mapId(b.id),
      user_id: userId,
      category_id: mapId(b.categoryId),
      month: b.month,
      limit_amount: b.limit,
    }));
    const { error } = await client.from('budgets').upsert(rows, { onConflict: 'id' });
    if (error) throw error;
    logger.info('SeedFinance', `Inserted ${rows.length} budgets`);
  }

  // Net worth
  if (networth.length) {
    const rows = networth.map((n) => ({ user_id: userId, month: n.month, assets: n.assets, liabilities: n.liabilities }));
    const { error } = await client.from('networth').upsert(rows, { onConflict: 'user_id,month' });
    if (error) throw error;
    logger.info('SeedFinance', `Inserted ${rows.length} networth rows`);
  }

  // Goals
  if (goals.length) {
    const rows = goals.map((g) => ({
      id: mapId(g.id),
      user_id: userId,
      name: g.name,
      target_amount: g.targetAmount,
      current_amount: g.currentAmount,
      due_date: g.dueDateISO.slice(0, 10),
      type: g.type,
      linked_category_id: mapId(g.linkedCategoryId) ?? null,
    }));
    const { error } = await client.from('goals').upsert(rows, { onConflict: 'id' });
    if (error) throw error;
    logger.info('SeedFinance', `Inserted ${rows.length} goals`);
  }

  logger.info('SeedFinance', 'Finance seed complete for user:', userId);
}

main().catch((e) => {
  logger.error('SeedFinance', e);
  process.exit(1);
});

#!/usr/bin/env tsx
/**
 * Verification Script for Budget Templates Feature
 *
 * This script verifies that the budget templates feature is properly set up:
 * 1. Database table exists
 * 2. RLS policies are in place
 * 3. Database function exists
 * 4. Can perform CRUD operations
 */

import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.VITE_SUPABASE_URL!;
const supabaseAnonKey = process.env.VITE_SUPABASE_ANON_KEY!;

if (!supabaseUrl || !supabaseAnonKey) {
  logger.error('VerifyBudgetTemplates', '❌ Missing Supabase credentials');
  logger.error('VerifyBudgetTemplates', '   VITE_SUPABASE_URL:', supabaseUrl);
  logger.error('VerifyBudgetTemplates', '   VITE_SUPABASE_ANON_KEY:', supabaseAnonKey ? '✓' : '✗');
  process.exit(1);
}

const supabase = createClient(supabaseUrl, supabaseAnonKey);

async function verify() {
  logger.info('VerifyBudgetTemplates', '🔍 Budget Templates Feature Verification\n');
  logger.info('VerifyBudgetTemplates', '═'.repeat(70));

  let allChecks = true;

  // Check 1: User authentication
  logger.info('VerifyBudgetTemplates', '\n1️⃣  Checking user authentication...');
  const { data: userData, error: userError } = await supabase.auth.getUser();
  if (userError || !userData.user) {
    logger.info('VerifyBudgetTemplates', '   ❌ Not authenticated');
    logger.info('VerifyBudgetTemplates', '   ℹ️  Please sign in to the app first, then run this script');
    allChecks = false;
  } else {
    logger.info('VerifyBudgetTemplates', '   ✅ Authenticated as:', userData.user.email);
  }

  // Check 2: Table exists and is accessible
  logger.info('VerifyBudgetTemplates', '\n2️⃣  Checking budget_templates table...');
  const { data: templates, error: tableError } = await supabase
    .from('budget_templates')
    .select('*')
    .limit(1);

  if (tableError) {
    logger.info('VerifyBudgetTemplates', '   ❌ Table error:', tableError.message);
    if (tableError.message.includes('relation') && tableError.message.includes('does not exist')) {
      logger.info('VerifyBudgetTemplates', '   ℹ️  Migration not applied. Please run the migration SQL in Supabase dashboard.');
    }
    allChecks = false;
  } else {
    logger.info('VerifyBudgetTemplates', '   ✅ Table exists and is accessible');
    logger.info('VerifyBudgetTemplates', '   📊 Current templates:', templates?.length || 0);
  }

  // Check 3: Database function exists
  logger.info('VerifyBudgetTemplates', '\n3️⃣  Checking initialize_budgets_from_templates function...');
  const { data: userData2 } = await supabase.auth.getUser();
  if (userData2.user) {
    const { data: funcResult, error: funcError } = await supabase
      .rpc('initialize_budgets_from_templates', {
        p_user_id: userData2.user.id,
        p_month: '2099-12' // Test month that doesn't exist
      });

    if (funcError) {
      logger.info('VerifyBudgetTemplates', '   ❌ Function error:', funcError.message);
      allChecks = false;
    } else {
      logger.info('VerifyBudgetTemplates', '   ✅ Function exists and is callable');
      logger.info('VerifyBudgetTemplates', '   📊 Test returned:', funcResult);
    }
  }

  // Check 4: Categories exist (prerequisite)
  logger.info('VerifyBudgetTemplates', '\n4️⃣  Checking categories (prerequisite)...');
  const { data: categories, error: catError } = await supabase
    .from('categories')
    .select('id, name')
    .limit(5);

  if (catError) {
    logger.info('VerifyBudgetTemplates', '   ❌ Categories error:', catError.message);
    allChecks = false;
  } else {
    logger.info('VerifyBudgetTemplates', '   ✅ Categories available:', categories?.length || 0);
    if (categories && categories.length > 0) {
      logger.info('VerifyBudgetTemplates', '   📋 Sample:', categories.map(c => c.name).join(', '));
    }
  }

  // Check 5: Test CRUD operations (if authenticated and table exists)
  if (userData.user && !tableError) {
    logger.info('VerifyBudgetTemplates', '\n5️⃣  Testing CRUD operations...');

    // Get a test category
    const { data: testCategories } = await supabase
      .from('categories')
      .select('id, name')
      .limit(1);

    if (testCategories && testCategories.length > 0) {
      const testCategory = testCategories[0];
      const testAmount = 999.99;

      // CREATE/UPDATE
      logger.info('VerifyBudgetTemplates', '   Testing INSERT/UPDATE...');
      const { error: upsertError } = await supabase
        .from('budget_templates')
        .upsert({
          user_id: userData.user.id,
          category_id: testCategory.id,
          default_amount: testAmount,
        }, {
          onConflict: 'user_id,category_id'
        });

      if (upsertError) {
        logger.info('VerifyBudgetTemplates', '   ❌ Upsert failed:', upsertError.message);
        allChecks = false;
      } else {
        logger.info('VerifyBudgetTemplates', '   ✅ INSERT/UPDATE works');

        // READ
        logger.info('VerifyBudgetTemplates', '   Testing SELECT...');
        const { data: readData, error: readError } = await supabase
          .from('budget_templates')
          .select('*')
          .eq('category_id', testCategory.id)
          .single();

        if (readError) {
          logger.info('VerifyBudgetTemplates', '   ❌ Read failed:', readError.message);
          allChecks = false;
        } else if (readData.default_amount === testAmount) {
          logger.info('VerifyBudgetTemplates', '   ✅ SELECT works');
        } else {
          logger.info('VerifyBudgetTemplates', '   ⚠️  Data mismatch');
          allChecks = false;
        }

        // DELETE
        logger.info('VerifyBudgetTemplates', '   Testing DELETE...');
        const { error: deleteError } = await supabase
          .from('budget_templates')
          .delete()
          .eq('category_id', testCategory.id);

        if (deleteError) {
          logger.info('VerifyBudgetTemplates', '   ❌ Delete failed:', deleteError.message);
          allChecks = false;
        } else {
          logger.info('VerifyBudgetTemplates', '   ✅ DELETE works');
        }
      }
    } else {
      logger.info('VerifyBudgetTemplates', '   ⚠️  No categories available for testing');
    }
  }

  // Summary
  logger.info('VerifyBudgetTemplates', '\n' + '═'.repeat(70));
  if (allChecks) {
    logger.info('VerifyBudgetTemplates', '✅ All checks passed! Budget templates feature is ready to use.');
  } else {
    logger.info('VerifyBudgetTemplates', '❌ Some checks failed. Please review the errors above.');
    logger.info('VerifyBudgetTemplates', '\n📝 Next steps:');
    logger.info('VerifyBudgetTemplates', '   1. Ensure you are signed in to the app');
    logger.info('VerifyBudgetTemplates', '   2. Apply the migration SQL in Supabase dashboard');
    logger.info('VerifyBudgetTemplates', '   3. Run this script again to verify');
  }
  logger.info('VerifyBudgetTemplates', '═'.repeat(70) + '\n');
}

verify().catch((error) => {
  logger.error('VerifyBudgetTemplates', '\n💥 Unexpected error:', error);
  process.exit(1);
});

import type { VercelRequest, VercelResponse } from '@vercel/node';

type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };

const baseCorsHeaders = {
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
};

function resolveAllowedOrigin(requestOrigin: string | undefined | null): string {
  const configured = process.env.ALLOWED_ORIGINS
    ?.split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);

  if (!configured || configured.length === 0 || configured.includes('*')) {
    return '*';
  }
  if (requestOrigin && configured.includes(requestOrigin)) {
    return requestOrigin;
  }
  return configured[0];
}

function buildCorsHeaders(requestOrigin: string | undefined | null) {
  return {
    ...baseCorsHeaders,
    'Access-Control-Allow-Origin': resolveAllowedOrigin(requestOrigin),
  } as Record<string, string>;
}

function sendJson(res: VercelResponse, status: number, body: JsonValue | { [key: string]: JsonValue }, headers: Record<string, string>) {
  res.setHeader('Content-Type', 'application/json');
  for (const [key, value] of Object.entries(headers)) {
    res.setHeader(key, value);
  }
  res.status(status).send(JSON.stringify(body));
}

export default async function handler(req: VercelRequest, res: VercelResponse) {
  const origin = req.headers.origin;
  const corsHeaders = buildCorsHeaders(origin);

  if (req.method === 'OPTIONS') {
    res.setHeader('Content-Type', 'text/plain');
    for (const [key, value] of Object.entries(corsHeaders)) {
      res.setHeader(key, value);
    }
    res.status(200).send('ok');
    return;
  }

  if (req.method !== 'GET' && req.method !== 'POST') {
    sendJson(res, 405, { error: 'Method not allowed' }, corsHeaders);
    return;
  }

  const apiKey = process.env.YOUTUBE_API_KEY;
  const apiBaseUrl = process.env.YOUTUBE_API_BASE_URL ?? 'https://www.googleapis.com/youtube/v3/videos';

  let videoId: string | undefined;

  try {
    if (req.method === 'GET') {
      videoId = typeof req.query.videoId === 'string' ? req.query.videoId : Array.isArray(req.query.videoId) ? req.query.videoId[0] : undefined;
    } else {
      videoId = typeof req.body?.videoId === 'string' ? req.body.videoId : undefined;
    }
  } catch (error) {
    sendJson(res, 400, { error: 'Invalid request payload', details: String(error) }, corsHeaders);
    return;
  }

  if (!videoId) {
    sendJson(res, 400, { error: 'Missing videoId' }, corsHeaders);
    return;
  }

  const upstreamUrl = new URL(apiBaseUrl);
  if (!upstreamUrl.searchParams.has('part')) {
    upstreamUrl.searchParams.set('part', 'snippet');
  }
  upstreamUrl.searchParams.set('id', videoId);

  const isYoutubeDataApi = upstreamUrl.host.endsWith('googleapis.com');
  if (isYoutubeDataApi) {
    if (!apiKey) {
      sendJson(res, 500, { error: 'Server misconfiguration: missing YOUTUBE_API_KEY' }, corsHeaders);
      return;
    }
    upstreamUrl.searchParams.set('key', apiKey);
  }

  let upstreamResponse: globalThis.Response;
  try {
    upstreamResponse = await fetch(upstreamUrl.toString(), {
      headers: { Accept: 'application/json' },
    });
  } catch (error) {
    sendJson(res, 502, { error: 'Upstream request failed', details: String(error) }, corsHeaders);
    return;
  }

  const textPayload = await upstreamResponse.text();
  const contentType = upstreamResponse.headers.get('content-type') ?? 'application/json';

  for (const [key, value] of Object.entries(corsHeaders)) {
    res.setHeader(key, value);
  }
  res.setHeader('Content-Type', contentType);

  res.status(upstreamResponse.status).send(textPayload);
}

import { useEffect, useRef, lazy, Suspense } from 'react';
import { useRealAppStore } from './stores/useRealAppStore';
import Layout from './components/Layout';
import { ErrorBoundary } from './components/ErrorBoundary';
import LoadingSpinner from './components/LoadingSpinner';
import { AuthGate } from './components/AuthGate';
import { useAuth } from './hooks/useAuth';
import { isSupabaseConfigured } from './lib/supabase';
import { loadSFHChallenge } from './seventyFiveHard/actions';
import { cleanup75HardDuplicates } from './utils/cleanup75HardDuplicates';
import { logger } from './services/logger';

// Lazy load all page components for route-based code splitting
const Dashboard = lazy(() => import('./pages/Dashboard'));
const Calendar = lazy(() => import('./pages/Calendar'));
const Focus = lazy(() => import('./pages/Focus'));
const Habits = lazy(() => import('./pages/Habits'));
const Todos = lazy(() => import('./pages/Todos'));
const Notes = lazy(() => import('./pages/Notes'));
const Journal = lazy(() => import('./pages/Journal'));
const LifeGoals = lazy(() => import('./pages/LifeGoals'));
const ShoppingSmart = lazy(() => import('./pages/ShoppingSmart'));
const MealPlanning = lazy(() => import('./pages/MealPlanning'));
const ProjectTracking = lazy(() => import('./pages/ProjectTracking'));
const Shared = lazy(() => import('./pages/Shared'));
const Travel = lazy(() => import('./pages/Travel'));
const VisaPage = lazy(() => import('./travel/pages/VisaPage'));
const TripPlanner = lazy(() => import('./travel/components/TripPlanner'));
const Finances = lazy(() => import('./pages/Finances'));
const SeventyFiveHard = lazy(() => import('./pages/SeventyFiveHard/index'));
const Skincare = lazy(() => import('./pages/Skincare'));
const Assistant = lazy(() => import('./pages/Assistant'));

// Expose cleanup function globally for debugging
if (typeof window !== 'undefined') {
  window.cleanup75HardDuplicates = () => {
    void cleanup75HardDuplicates();
  };
}

function App(): React.ReactElement {
  const { activeView, loading, initializeData } = useRealAppStore();
  const { user, loading: authLoading } = useAuth();
  const initializedFor = useRef<string | null>(null);

  useEffect(() => {
    if (!isSupabaseConfigured) {
      return;
    }

    if (!authLoading && !user) {
      initializedFor.current = null;
    }
  }, [user, authLoading]);

  // Initialize data from Supabase database only
  useEffect(() => {
    // Only proceed if Supabase is configured
    if (!isSupabaseConfigured) {
      logger.warn('App', '🔄 Supabase not configured. Please configure environment variables.');
      return;
    }

    if (authLoading || !user) {
      return;
    }

    if (initializedFor.current === user.id) {
      return;
    }

    initializedFor.current = user.id;

    // Initialize data and load 75 Hard challenge
    void (async () => {
      try {
        await initializeData();
        logger.debug('App', '🔄 Initialized LifeSync data for Supabase user');

        // Load active 75 Hard challenge (new architecture)
        // This will check for missed days and show failure prompt if needed
        await loadSFHChallenge();
        logger.debug('App', '✅ 75 Hard challenge loaded');
      } catch (error) {
        logger.error('App', 'Failed to initialize data or load 75 Hard challenge:', { error });
      }
    })();
  }, [initializeData, user, authLoading]);

  // Show loading spinner while initializing
  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-center">
          <LoadingSpinner />
          <p className="mt-4 text-muted">Loading LifeSync...</p>
        </div>
      </div>
    );
  }

  const renderPage = (): React.ReactElement => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard />;
      case 'calendar':
        return <Calendar />;
      case 'focus':
        return <Focus />;
      case 'habits':
        return <Habits />;
      case 'todos':
        return <Todos />;
      case 'notes':
        return <Notes />;
      case 'projects':
        return (
          <ErrorBoundary>
            <ProjectTracking />
          </ErrorBoundary>
        );
      case 'journal':
        return <Journal />;
      case 'goals':
        return <LifeGoals />;
      case 'travel':
        return <Travel />;
      case 'visa':
        return <VisaPage />;
      case 'trip-planner':
        return <TripPlanner />;
      case 'finances':
        return <Finances />;
      case 'shopping':
        return <ShoppingSmart />;
      case 'meals':
        return <MealPlanning />;
      case 'shared':
        return <Shared />;
      case 'seventy-five-hard':
        return <SeventyFiveHard />;
      case 'skincare':
        return <Skincare />;
      case 'assistant':
        return <Assistant />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <AuthGate>
      <Layout>
        <Suspense fallback={
          <div className="min-h-screen bg-background flex items-center justify-center">
            <div className="text-center">
              <LoadingSpinner />
              <p className="mt-4 text-muted">Loading page...</p>
            </div>
          </div>
        }>
          {renderPage()}
        </Suspense>
      </Layout>
    </AuthGate>
  );
}

export default App;

