                    insight.type === 'warning' ? 'border-yellow-500 bg-yellow-50 dark:bg-yellow-900/20' :
                    insight.type === 'recommendation' ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20' :
                    'border-slate-500 bg-slate-50 dark:bg-slate-700'
