                className="w-full px-4 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
              >
                <option value="work">Work</option>
                <option value="personal">Personal</option>
                <option value="learning">Learning</option>
                <option value="creative">Creative</option>
                <option value="health">Health</option>
                <option value="other">Other</option>
              </select>
            </div>
          </div>

          <div>
            <label htmlFor="task-due-date" className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
              Due Date
            </label>
            <input
              id="task-due-date"
              type="date"
              value={formattedDueDate}
              onChange={handleDueDateChange}
              className="w-full px-4 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
            />
          </div>

          <div className="flex space-x-4">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-6 py-3 border border-slate-300 dark:border-slate-600 text-slate-700 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
            >
              Cancel
            </button>
            <button
              type="button"
              onClick={handleSubmit}
              disabled={isSubmitDisabled}
              className="flex-1 px-6 py-3 bg-indigo-500 hover:bg-indigo-600 disabled:bg-gray-400 text-white rounded-lg transition-colors"
            >
              Create Task
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

/**
 * Hook for aggregating focus session data
 */

import { useMemo } from 'react';
import type { FocusAggregate, FocusSession } from '../../../../focus/types';
import { useFocusSessionsQuery } from '../../../../focus/hooks/useFocusQuery';
import { buildFocusAggregate } from '../utils';

export const useFocusAggregate = (): FocusAggregate => {
  const { data: storeFocusSessions = [] as FocusSession[] } = useFocusSessionsQuery();

  const focusAggregate = useMemo((): FocusAggregate =>
    buildFocusAggregate(storeFocusSessions),
    [storeFocusSessions]
  );

  return focusAggregate;
};

