import React from 'react';
import { Briefcase, Heart, Book, Lightbulb, Target, CheckSquare } from 'lucide-react';

export const getPriorityColor = (priority: string): string => {
  switch (priority) {
    case 'urgent':
      return 'text-red-600 bg-red-100 border-red-200';
    case 'high':
      return 'text-orange-600 bg-orange-100 border-orange-200';
    case 'medium':
      return 'text-yellow-600 bg-yellow-100 border-yellow-200';
    case 'low':
      return 'text-green-600 bg-green-100 border-green-200';
    default:
      return 'text-gray-600 bg-gray-100 border-gray-200';
  }
};

export const getStatusColor = (status: string): string => {
  switch (status) {
    case 'completed':
      return 'text-green-600 bg-green-100';
    case 'in_progress':
      return 'text-blue-600 bg-blue-100';
    case 'cancelled':
      return 'text-red-600 bg-red-100';
    default:
      return 'text-gray-600 bg-gray-100';
  }
};

export const getCategoryIcon = (category: string): React.ReactElement => {
  switch (category) {
    case 'work':
      return <Briefcase className="w-4 h-4" />;
    case 'personal':
      return <Heart className="w-4 h-4" />;
    case 'learning':
      return <Book className="w-4 h-4" />;
    case 'creative':
      return <Lightbulb className="w-4 h-4" />;
    case 'health':
      return <Target className="w-4 h-4" />;
    default:
      return <CheckSquare className="w-4 h-4" />;
  }
};

/**
 * Advanced Focus Timer
 * 
 * Enhanced timer with session templates, Pomodoro cycles, auto-breaks,
 * session queuing, and advanced controls for power users.
 */

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { logger } from '../../../services/logger';
import {
  Play,
  Pause,
  Square,
  _RotateCcw,
  SkipForward,
  Timer,
  Coffee,
  Brain,
  Settings,
  Plus,
  _Edit,
  Trash2,
  _Save,
  Clock,
  _Target,
  _Zap,
  _CheckCircle,
  _AlertCircle,
  _Volume2,
  _VolumeX,
  _Maximize2,
  _Minimize2,
  _Calendar,
  _Book
} from 'lucide-react';

interface SessionTemplate {
  id: string;
  name: string;
  description?: string;
  sessions: Array<{
    type: 'focus' | 'break' | 'long-break';
    duration: number; // in minutes
    preset?: string;
    name?: string;
  }>;
  totalDuration: number;
  isDefault: boolean;
  usageCount: number;
}

interface QueueItem {
  type: 'focus' | 'break' | 'long-break';
  duration: number;
  name?: string;
  preset?: string;
}

interface TimerState {
  currentSession: {
    type: 'focus' | 'break' | 'long-break';
    duration: number;
    name?: string;
    preset?: string;
  } | null;
  timeRemaining: number; // in seconds
  isRunning: boolean;
  isPaused: boolean;
  sessionIndex: number;
  cycleCount: number;
  template: SessionTemplate | null;
  queue: Array<QueueItem>;
  startTime: Date | null;
  totalElapsed: number;
  autoStart: boolean;
  strictMode: boolean;
}

interface SessionCompleteData {
  type: 'focus' | 'break' | 'long-break';
  duration: number;
  completedAt: Date;
  template?: string;
}

interface BreakCompleteData {
  type: 'focus' | 'break' | 'long-break';
  duration: number;
  completedAt: Date;
}

interface Props {
  onSessionComplete: (session: SessionCompleteData) => void;
  onBreakComplete: (breakData: BreakCompleteData) => void;
  onTemplateComplete: (template: SessionTemplate) => void;
  backgroundMusic: boolean;
  musicType: string;
  soundEnabled: boolean;
  notificationsEnabled: boolean;
}

export const AdvancedTimer: React.FC<Props> = ({
  onSessionComplete,
  onBreakComplete,
  onTemplateComplete,
  _backgroundMusic,
  _musicType,
  soundEnabled,
  notificationsEnabled
}) => {
  const [timerState, setTimerState] = useState<TimerState>({
    currentSession: null,
    timeRemaining: 0,
    isRunning: false,
    isPaused: false,
    sessionIndex: 0,
    cycleCount: 0,
    template: null,
    queue: [],
    startTime: null,
    totalElapsed: 0,
    autoStart: false,
    strictMode: false
  });

  const [templates, setTemplates] = useState<SessionTemplate[]>([]);
  const [showTemplates, setShowTemplates] = useState(false);
  const [showCreateTemplate, setShowCreateTemplate] = useState(false);
  const [_showSettings, setShowSettings] = useState(false);
  const [isFullscreen, _setIsFullscreen] = useState(false);
  const [newTemplate, setNewTemplate] = useState<Partial<SessionTemplate>>({
    name: '',
    sessions: [{ type: 'focus', duration: 25 }]
  });

  const intervalRef = useRef<NodeJS.Timeout | null>(null);
  const _audioContextRef = useRef<AudioContext | null>(null);

  // Load default templates
  useEffect(() => {
    const defaultTemplates: SessionTemplate[] = [
      {
        id: 'classic-pomodoro',
        name: 'Classic Pomodoro',
        description: '25min focus + 5min break cycles with long breaks',
        sessions: [
          { type: 'focus', duration: 25, name: 'Focus Session 1' },
          { type: 'break', duration: 5, name: 'Short Break' },
          { type: 'focus', duration: 25, name: 'Focus Session 2' },
          { type: 'break', duration: 5, name: 'Short Break' },
          { type: 'focus', duration: 25, name: 'Focus Session 3' },
          { type: 'break', duration: 5, name: 'Short Break' },
          { type: 'focus', duration: 25, name: 'Focus Session 4' },
          { type: 'long-break', duration: 15, name: 'Long Break' }
        ],
        totalDuration: 160,
        isDefault: true,
        usageCount: 0
      },
      {
        id: 'deep-work',
        name: 'Deep Work Block',
        description: 'Extended focus sessions for complex tasks',
        sessions: [
          { type: 'focus', duration: 90, name: 'Deep Work Session' },
          { type: 'break', duration: 20, name: 'Recovery Break' },
          { type: 'focus', duration: 90, name: 'Deep Work Session' },
          { type: 'long-break', duration: 30, name: 'Long Break' }
        ],
        totalDuration: 230,
        isDefault: true,
        usageCount: 0
      },
      {
        id: 'study-session',
        name: 'Study Session',
        description: 'Optimized for learning and retention',
        sessions: [
          { type: 'focus', duration: 45, name: 'Study Block 1' },
          { type: 'break', duration: 10, name: 'Quick Break' },
          { type: 'focus', duration: 45, name: 'Study Block 2' },
          { type: 'break', duration: 15, name: 'Review Break' },
          { type: 'focus', duration: 30, name: 'Practice Session' }
        ],
        totalDuration: 145,
        isDefault: true,
        usageCount: 0
      },
      {
        id: 'creative-flow',
        name: 'Creative Flow',
        description: 'Longer blocks for creative work',
        sessions: [
          { type: 'focus', duration: 60, name: 'Creative Session 1' },
          { type: 'break', duration: 10, name: 'Inspiration Break' },
          { type: 'focus', duration: 60, name: 'Creative Session 2' },
          { type: 'break', duration: 20, name: 'Refresh Break' },
          { type: 'focus', duration: 45, name: 'Refinement Session' }
        ],
        totalDuration: 195,
        isDefault: true,
        usageCount: 0
      }
    ];

    setTemplates(defaultTemplates);
  }, []);

  // Timer logic
  useEffect(() => {
    if (timerState.isRunning && timerState.timeRemaining > 0) {
      intervalRef.current = setInterval(() => {
        setTimerState(prev => ({
          ...prev,
          timeRemaining: prev.timeRemaining - 1,
          totalElapsed: prev.totalElapsed + 1
        }));
      }, 1000);
    } else if (timerState.timeRemaining === 0 && timerState.isRunning && timerState.currentSession) {
      handleSessionComplete();
    } else {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    }

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [timerState.isRunning, timerState.timeRemaining, timerState.currentSession, handleSessionComplete]);

  const playNotificationSound = useCallback((): void => {
    if (!soundEnabled) return;

    try {
      // Type-safe way to access webkitAudioContext
      const AudioContextConstructor = window.AudioContext || (window as Window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (!AudioContextConstructor) return;

      const audioContext = new AudioContextConstructor();

      // Create completion chime
      const playTone = (frequency: number, startTime: number, duration: number): void => {
        const osc = audioContext.createOscillator();
        const gain = audioContext.createGain();

        osc.connect(gain);
        gain.connect(audioContext.destination);

        osc.frequency.setValueAtTime(frequency, startTime);
        gain.gain.setValueAtTime(0.3, startTime);
        gain.gain.exponentialRampToValueAtTime(0.01, startTime + duration);

        osc.start(startTime);
        osc.stop(startTime + duration);
      };

      const now = audioContext.currentTime;
      playTone(523.25, now, 0.2); // C5
      playTone(659.25, now + 0.2, 0.2); // E5
      playTone(783.99, now + 0.4, 0.4); // G5
    } catch (error) {
      logger.debug('Audio playback failed:', { error });
    }
  }, [soundEnabled]);

  const showNotification = useCallback((title: string, body: string): void => {
    if (!notificationsEnabled) return;

    if ('Notification' in window && Notification.permission === 'granted') {
      new Notification(title, {
        body,
        icon: '🎯'
      });
    }
  }, [notificationsEnabled]);

  const handleSessionComplete = useCallback((): void => {
    const currentSession = timerState.currentSession;
    if (!currentSession) return;

    playNotificationSound();

    if (currentSession.type === 'focus') {
      showNotification('Focus Session Complete! 🎉', `Great work on your ${currentSession.name ?? 'focus session'}!`);
      onSessionComplete({
        type: currentSession.type,
        duration: currentSession.duration,
        completedAt: new Date(),
        template: timerState.template?.name
      });
    } else {
      showNotification('Break Time Over! ⏰', 'Ready to get back to focused work?');
      onBreakComplete({
        type: currentSession.type,
        duration: currentSession.duration,
        completedAt: new Date()
      });
    }

    // Move to next session in template
    if (timerState.template && timerState.sessionIndex < timerState.template.sessions.length - 1) {
      const nextIndex = timerState.sessionIndex + 1;
      const nextSession = timerState.template.sessions[nextIndex];

      setTimerState(prev => ({
        ...prev,
        currentSession: nextSession,
        timeRemaining: nextSession.duration * 60,
        sessionIndex: nextIndex,
        isRunning: prev.autoStart,
        startTime: prev.autoStart ? new Date() : null
      }));
    } else if (timerState.template) {
      // Template complete
      onTemplateComplete(timerState.template);
      showNotification('Template Complete! 🏆', `You've completed the ${timerState.template.name} template!`);

      setTimerState(prev => ({
        ...prev,
        currentSession: null,
        timeRemaining: 0,
        isRunning: false,
        sessionIndex: 0,
        template: null,
        startTime: null
      }));
    } else {
      // Single session complete
      setTimerState(prev => ({
        ...prev,
        currentSession: null,
        timeRemaining: 0,
        isRunning: false,
        startTime: null
      }));
    }
  }, [timerState.currentSession, timerState.template, timerState.sessionIndex, playNotificationSound, showNotification, onSessionComplete, onBreakComplete, onTemplateComplete]);

  const startTemplate = (template: SessionTemplate): void => {
    const firstSession = template.sessions[0];

    setTimerState(prev => ({
      ...prev,
      template,
      currentSession: firstSession,
      timeRemaining: firstSession.duration * 60,
      sessionIndex: 0,
      isRunning: true,
      isPaused: false,
      startTime: new Date(),
      totalElapsed: 0
    }));

    // Update usage count
    setTemplates(prev => prev.map(t =>
      t.id === template.id ? { ...t, usageCount: t.usageCount + 1 } : t
    ));

    setShowTemplates(false);
  };

  const startSingleSession = (type: 'focus' | 'break', duration: number): void => {
    setTimerState(prev => ({
      ...prev,
      currentSession: { type, duration, name: `${type} Session` },
      timeRemaining: duration * 60,
      isRunning: true,
      isPaused: false,
      startTime: new Date(),
      totalElapsed: 0,
      template: null,
      sessionIndex: 0
    }));
  };

  const pauseSession = (): void => {
    setTimerState(prev => ({
      ...prev,
      isRunning: false,
      isPaused: true
    }));
  };

  const resumeSession = (): void => {
    setTimerState(prev => ({
      ...prev,
      isRunning: true,
      isPaused: false
    }));
  };

  const stopSession = (): void => {
    setTimerState(prev => ({
      ...prev,
      currentSession: null,
      timeRemaining: 0,
      isRunning: false,
      isPaused: false,
      startTime: null,
      template: null,
      sessionIndex: 0
    }));
  };

  const skipToNext = (): void => {
    if (timerState.template && timerState.sessionIndex < timerState.template.sessions.length - 1) {
      const nextIndex = timerState.sessionIndex + 1;
      const nextSession = timerState.template.sessions[nextIndex];

      setTimerState(prev => ({
        ...prev,
        currentSession: nextSession,
        timeRemaining: nextSession.duration * 60,
        sessionIndex: nextIndex,
        isRunning: true,
        startTime: new Date()
      }));
    }
  };

  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const getProgress = (): number => {
    if (!timerState.currentSession) return 0;
    const totalSeconds = timerState.currentSession.duration * 60;
    const elapsed = totalSeconds - timerState.timeRemaining;
    return (elapsed / totalSeconds) * 100;
  };

  const getTemplateProgress = (): number => {
    if (!timerState.template) return 0;
    return ((timerState.sessionIndex + 1) / timerState.template.sessions.length) * 100;
  };

  const addSessionToTemplate = (): void => {
    setNewTemplate(prev => ({
      ...prev,
      sessions: [...(prev.sessions ?? []), { type: 'focus', duration: 25 }]
    }));
  };

  const removeSessionFromTemplate = (index: number): void => {
    setNewTemplate(prev => ({
      ...prev,
      sessions: prev.sessions?.filter((_, i) => i !== index) ?? []
    }));
  };

  const saveTemplate = (): void => {
    if (newTemplate.name && newTemplate.sessions && newTemplate.sessions.length > 0) {
      const template: SessionTemplate = {
        id: `custom_${Date.now()}`,
        name: newTemplate.name,
        description: newTemplate.description,
        sessions: newTemplate.sessions,
        totalDuration: newTemplate.sessions.reduce((total, session) => total + session.duration, 0),
        isDefault: false,
        usageCount: 0
      };

      setTemplates(prev => [...prev, template]);
      setNewTemplate({ name: '', sessions: [{ type: 'focus', duration: 25 }] });
      setShowCreateTemplate(false);
    }
  };

  const deleteTemplate = (templateId: string): void => {
    setTemplates(prev => prev.filter(t => t.id !== templateId));
  };

  return (
    <div className={`${isFullscreen ? 'fixed inset-0 z-50 bg-slate-900' : ''}`}>
      <div className="space-y-8">
        {/* Timer Display */}
        <div className="bg-white dark:bg-slate-800 rounded-2xl p-8 shadow-xl border border-slate-200 dark:border-slate-700">
          <div className="text-center">
            {/* Session Info */}
            {timerState.currentSession && (
              <div className="mb-6">
                <div className="flex items-center justify-center space-x-3 mb-2">
                  {timerState.currentSession.type === 'focus' ? (
                    <Brain className="w-6 h-6 text-indigo-500" />
                  ) : (
                    <Coffee className="w-6 h-6 text-orange-500" />
                  )}
                  <h3 className="text-xl font-semibold text-slate-900 dark:text-white">
                    {timerState.currentSession.name ??
                     (timerState.currentSession.type === 'focus' ? 'Focus Session' :
                      timerState.currentSession.type === 'long-break' ? 'Long Break' : 'Break')}
                  </h3>
                </div>

                {timerState.template && (
                  <div className="text-sm text-slate-600 dark:text-slate-300 mb-4">
                    {timerState.template.name} - Session {timerState.sessionIndex + 1} of {timerState.template.sessions.length}
                  </div>
                )}
              </div>
            )}

            {/* Main Timer */}
            <div className={`text-8xl font-black font-mono mb-6 tracking-wider ${
              timerState.currentSession?.type === 'focus' ? 'text-indigo-600' : 'text-orange-500'
            }`}>
              {formatTime(timerState.timeRemaining)}
            </div>

            {/* Progress Ring */}
            {timerState.currentSession && (
              <div className="relative w-32 h-32 mx-auto mb-6">
                <svg className="w-32 h-32 transform -rotate-90" viewBox="0 0 120 120">
                  <circle
                    cx="60"
                    cy="60"
                    r="50"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="8"
                    className="text-slate-200 dark:text-slate-700"
                  />
                  <circle
                    cx="60"
                    cy="60"
                    r="50"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="8"
                    strokeLinecap="round"
                    className={timerState.currentSession.type === 'focus' ? 'text-indigo-500' : 'text-orange-500'}
                    strokeDasharray={`${2 * Math.PI * 50}`}
                    strokeDashoffset={`${2 * Math.PI * 50 * (1 - getProgress() / 100)}`}
                    style={{ transition: 'stroke-dashoffset 1s ease-in-out' }}
                  />
                </svg>
                <div className="absolute inset-0 flex items-center justify-center">
                  <span className="text-sm font-medium text-slate-600 dark:text-slate-300">
                    {Math.round(getProgress())}%
                  </span>
                </div>
              </div>
            )}

            {/* Controls */}
            <div className="flex items-center justify-center space-x-4">
              {timerState.currentSession ? (
                <>
                  <button
                    onClick={timerState.isRunning ? pauseSession : resumeSession}
                    disabled={timerState.strictMode && timerState.isRunning}
                    className={`flex items-center space-x-2 px-6 py-3 rounded-xl font-bold transition-all shadow-lg ${
                      timerState.isRunning
                        ? 'bg-yellow-500 hover:bg-yellow-600 text-white'
                        : 'bg-green-500 hover:bg-green-600 text-white'
                    } ${timerState.strictMode && timerState.isRunning ? 'opacity-50 cursor-not-allowed' : 'hover:scale-105'}`}
                  >
                    {timerState.isRunning ? <Pause size={20} /> : <Play size={20} />}
                    <span>{timerState.isRunning ? 'Pause' : timerState.isPaused ? 'Resume' : 'Start'}</span>
                  </button>

                  <button
                    onClick={stopSession}
                    disabled={timerState.strictMode && timerState.isRunning}
                    className={`flex items-center space-x-2 px-6 py-3 rounded-xl font-bold transition-all shadow-lg ${
                      timerState.strictMode && timerState.isRunning
                        ? 'opacity-50 cursor-not-allowed bg-gray-400'
                        : 'bg-red-500 hover:bg-red-600 hover:scale-105'
                    } text-white`}
                  >
                    <Square size={20} />
                    <span>Stop</span>
                  </button>

                  {timerState.template && timerState.sessionIndex < timerState.template.sessions.length - 1 && (
                    <button
                      onClick={skipToNext}
                      className="flex items-center space-x-2 px-6 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-xl font-bold transition-all shadow-lg hover:scale-105"
                    >
                      <SkipForward size={20} />
                      <span>Skip</span>
                    </button>
                  )}
                </>
              ) : (
                <div className="flex items-center space-x-4">
                  <button
                    onClick={() => startSingleSession('focus', 25)}
                    className="flex items-center space-x-2 px-6 py-3 bg-indigo-500 hover:bg-indigo-600 text-white rounded-xl font-bold transition-all shadow-lg hover:scale-105"
                  >
                    <Brain size={20} />
                    <span>Quick Focus</span>
                  </button>

                  <button
                    onClick={() => setShowTemplates(true)}
                    className="flex items-center space-x-2 px-6 py-3 bg-purple-500 hover:bg-purple-600 text-white rounded-xl font-bold transition-all shadow-lg hover:scale-105"
                  >
                    <Timer size={20} />
                    <span>Templates</span>
                  </button>
                </div>
              )}
            </div>

            {/* Template Progress */}
            {timerState.template && (
              <div className="mt-6 p-4 bg-slate-50 dark:bg-slate-700 rounded-lg">
                <div className="flex justify-between text-sm text-slate-600 dark:text-slate-300 mb-2">
                  <span>Template Progress</span>
                  <span>{timerState.sessionIndex + 1}/{timerState.template.sessions.length}</span>
                </div>
                <div className="w-full bg-slate-200 dark:bg-slate-600 rounded-full h-2">
                  <div
                    className="bg-gradient-to-r from-indigo-500 to-purple-500 h-2 rounded-full transition-all duration-500"
                    style={{ width: `${getTemplateProgress()}%` }}
                  ></div>
                </div>
                <div className="flex items-center justify-between mt-2 text-xs text-slate-500 dark:text-slate-400">
                  <span>Remaining: {Math.ceil((timerState.template.totalDuration - (timerState.totalElapsed / 60)))} min</span>
                  <span>Total: {timerState.template.totalDuration} min</span>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Quick Actions */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <button
            onClick={() => startSingleSession('focus', 25)}
            className="p-4 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 hover:border-indigo-300 dark:hover:border-indigo-600 transition-all group"
          >
            <Clock className="w-6 h-6 text-indigo-500 mx-auto mb-2 group-hover:scale-110 transition-transform" />
            <div className="text-sm font-medium text-slate-900 dark:text-white">25 min Focus</div>
          </button>

          <button
            onClick={() => startSingleSession('focus', 45)}
            className="p-4 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 hover:border-purple-300 dark:hover:border-purple-600 transition-all group"
          >
            <Brain className="w-6 h-6 text-purple-500 mx-auto mb-2 group-hover:scale-110 transition-transform" />
            <div className="text-sm font-medium text-slate-900 dark:text-white">45 min Deep</div>
          </button>

          <button
            onClick={() => startSingleSession('break', 5)}
            className="p-4 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 hover:border-orange-300 dark:hover:border-orange-600 transition-all group"
          >
            <Coffee className="w-6 h-6 text-orange-500 mx-auto mb-2 group-hover:scale-110 transition-transform" />
            <div className="text-sm font-medium text-slate-900 dark:text-white">5 min Break</div>
          </button>

          <button
            onClick={() => setShowSettings(true)}
            className="p-4 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600 transition-all group"
          >
            <Settings className="w-6 h-6 text-slate-500 mx-auto mb-2 group-hover:scale-110 transition-transform" />
            <div className="text-sm font-medium text-slate-900 dark:text-white">Settings</div>
          </button>
        </div>
      </div>

      {/* Templates Modal */}
      {showTemplates && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50">
          <div className="bg-white dark:bg-slate-800 rounded-2xl p-8 shadow-2xl border border-white/20 max-w-4xl w-full mx-4 max-h-[80vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-2xl font-bold text-slate-900 dark:text-white">Session Templates</h3>
              <div className="flex items-center space-x-2">
                <button
                  onClick={() => setShowCreateTemplate(true)}
                  className="flex items-center space-x-2 px-4 py-2 bg-indigo-500 hover:bg-indigo-600 text-white rounded-lg transition-colors"
                >
                  <Plus size={16} />
                  <span>Create</span>
                </button>
                <button
                  onClick={() => setShowTemplates(false)}
                  className="text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
                >
                  ×
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {templates.map((template) => (
                <div key={template.id} className="bg-slate-50 dark:bg-slate-700 rounded-xl p-6 border border-slate-200 dark:border-slate-600">
                  <div className="flex items-start justify-between mb-4">
                    <div>
                      <h4 className="font-semibold text-slate-900 dark:text-white mb-1">{template.name}</h4>
                      {template.description && (
                        <p className="text-sm text-slate-600 dark:text-slate-300 mb-2">{template.description}</p>
                      )}
                      <div className="flex items-center space-x-4 text-xs text-slate-500 dark:text-slate-400">
                        <span>{template.sessions.length} sessions</span>
                        <span>{template.totalDuration} min total</span>
                        <span>Used {template.usageCount} times</span>
                      </div>
                    </div>

                    {!template.isDefault && (
                      <button
                        onClick={() => deleteTemplate(template.id)}
                        className="text-red-500 hover:text-red-700 dark:text-red-400"
                      >
                        <Trash2 size={16} />
                      </button>
                    )}
                  </div>

                  <div className="space-y-2 mb-4">
                    {template.sessions.map((session, index) => (
                      <div key={index} className="flex items-center space-x-2 text-sm">
                        {session.type === 'focus' ? (
                          <Brain className="w-4 h-4 text-indigo-500" />
                        ) : session.type === 'long-break' ? (
                          <Coffee className="w-4 h-4 text-orange-600" />
                        ) : (
                          <Coffee className="w-4 h-4 text-orange-400" />
                        )}
                        <span className="text-slate-900 dark:text-white">
                          {session.name ?? `${session.type} (${session.duration}m)`}
                        </span>
                      </div>
                    ))}
                  </div>

                  <button
                    onClick={() => startTemplate(template)}
                    className="w-full px-4 py-2 bg-indigo-500 hover:bg-indigo-600 text-white rounded-lg transition-colors"
                  >
                    Start Template
                  </button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Create Template Modal */}
      {showCreateTemplate && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50">
          <div className="bg-white dark:bg-slate-800 rounded-2xl p-8 shadow-2xl border border-white/20 max-w-2xl w-full mx-4 max-h-[80vh] overflow-y-auto">
            <h3 className="text-2xl font-bold text-slate-900 dark:text-white mb-6">Create Template</h3>

            <div className="space-y-6">
              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                  Template Name
                </label>
                <input
                  type="text"
                  value={newTemplate.name ?? ''}
                  onChange={(e) => setNewTemplate({ ...newTemplate, name: e.target.value })}
                  className="w-full px-4 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  placeholder="My Custom Template"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                  Description (optional)
                </label>
                <textarea
                  value={newTemplate.description ?? ''}
                  onChange={(e) => setNewTemplate({ ...newTemplate, description: e.target.value })}
                  className="w-full px-4 py-2 border border-slate-300 dark:border-slate-600 rounded-lg bg-white dark:bg-slate-700 text-slate-900 dark:text-white"
                  rows={2}
                  placeholder="Describe your template..."
                />
              </div>

              <div>
                <div className="flex items-center justify-between mb-4">
                  <label className="text-sm font-medium text-slate-700 dark:text-slate-300">
                    Sessions
                  </label>
                  <button
                    onClick={addSessionToTemplate}
                    className="flex items-center space-x-1 text-indigo-600 hover:text-indigo-700 dark:text-indigo-400"
                  >
                    <Plus size={16} />
                    <span className="text-sm">Add Session</span>
                  </button>
                </div>

                <div className="space-y-3">
                  {newTemplate.sessions?.map((session, index) => (
                    <div key={index} className="flex items-center space-x-3 p-3 bg-slate-50 dark:bg-slate-700 rounded-lg">
                      <select
                        value={session.type}
                        onChange={(e) => {
                          const updatedSessions = [...(newTemplate.sessions ?? [])];
                          const sessionType = e.target.value as 'focus' | 'break' | 'long-break';
                          updatedSessions[index] = { ...session, type: sessionType };
                          setNewTemplate({ ...newTemplate, sessions: updatedSessions });
                        }}
                        className="px-3 py-1 border border-slate-300 dark:border-slate-600 rounded bg-white dark:bg-slate-800 text-slate-900 dark:text-white text-sm"
                      >
                        <option value="focus">Focus</option>
                        <option value="break">Break</option>
                        <option value="long-break">Long Break</option>
                      </select>

                      <input
                        type="number"
                        value={session.duration}
                        onChange={(e) => {
                          const updatedSessions = [...(newTemplate.sessions ?? [])];
                          updatedSessions[index] = { ...session, duration: parseInt(e.target.value) || 0 };
                          setNewTemplate({ ...newTemplate, sessions: updatedSessions });
                        }}
                        className="w-20 px-3 py-1 border border-slate-300 dark:border-slate-600 rounded bg-white dark:bg-slate-800 text-slate-900 dark:text-white text-sm"
                        min="1"
                      />
                      <span className="text-sm text-slate-600 dark:text-slate-300">min</span>

                      <input
                        type="text"
                        value={session.name ?? ''}
                        onChange={(e) => {
                          const updatedSessions = [...(newTemplate.sessions ?? [])];
                          updatedSessions[index] = { ...session, name: e.target.value };
                          setNewTemplate({ ...newTemplate, sessions: updatedSessions });
                        }}
                        className="flex-1 px-3 py-1 border border-slate-300 dark:border-slate-600 rounded bg-white dark:bg-slate-800 text-slate-900 dark:text-white text-sm"
                        placeholder="Session name (optional)"
                      />

                      {(newTemplate.sessions?.length ?? 0) > 1 && (
                        <button
                          onClick={() => removeSessionFromTemplate(index)}
                          className="text-red-500 hover:text-red-700 dark:text-red-400"
                        >
                          <Trash2 size={16} />
                        </button>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              <div className="flex space-x-4">
                <button
                  onClick={() => setShowCreateTemplate(false)}
                  className="flex-1 px-6 py-3 border border-slate-300 dark:border-slate-600 text-slate-700 dark:text-slate-300 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={saveTemplate}
                  disabled={!newTemplate.name || !newTemplate.sessions?.length}
                  className="flex-1 px-6 py-3 bg-indigo-500 hover:bg-indigo-600 disabled:bg-gray-400 text-white rounded-lg transition-colors"
                >
                  Save Template
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

/**
 * Wellness Center
 * 
 * Comprehensive wellness and health tracking integrated with focus sessions.
 * Eye strain reminders, posture checks, hydration tracking, mood logging,
 * breathing exercises, and health correlations.
 */

import React, { useState, useEffect, useRef } from 'react';
import {
  Eye,
  _Coffee,
  Heart,
  Activity,
  _Brain,
  _Moon,
  _Sun,
  Droplets,
  Wind,
  Smile,
  Frown,
  Meh,
  _Calendar,
  _Clock,
  _TrendingUp,
  AlertCircle,
  CheckCircle,
  _Play,
  _Pause,
  _RotateCcw,
  Settings,
  Bell,
  Target,
  BarChart3,
  Zap,
  _Shield,
  _Timer,
  _Award,
  _Plus,
  _ChevronRight,
  _Lightbulb,
  Sparkles
} from 'lucide-react';
import { format, subDays, startOfDay } from 'date-fns';
import { logger } from '../../../services/logger';

interface WellnessEvent {
  id: string;
  type: 'eye_strain' | 'posture' | 'hydration' | 'breathing' | 'mood' | 'energy' | 'break';
  timestamp: Date;
  completed: boolean;
  value?: number; // for mood/energy ratings
  notes?: string;
  sessionId?: string;
}

interface HealthMetrics {
  date: Date;
  sleepHours: number;
  sleepQuality: number; // 1-5
  stressLevel: number; // 1-5
  exerciseMinutes: number;
  waterIntake: number; // glasses
  screenTime: number; // minutes
  focusSessionsCount: number;
  focusQuality: number; // 1-5
  mood: number; // 1-5
  energy: number; // 1-5
}

interface WellnessSettings {
  eyeStrainReminders: boolean;
  eyeStrainInterval: number; // minutes
  postureReminders: boolean;
  postureInterval: number;
  hydrationReminders: boolean;
  hydrationInterval: number;
  breathingExercises: boolean;
  moodTracking: boolean;
  energyTracking: boolean;
  sleepCorrelation: boolean;
  maxDailyFocusTime: number; // minutes
  enforceBreaks: boolean;
  minBreakDuration: number; // minutes
}

interface BreathingExercise {
  id: string;
  name: string;
  description: string;
  pattern: Array<{ phase: 'inhale' | 'hold' | 'exhale' | 'rest'; duration: number }>;
  totalDuration: number;
  benefits: string[];
  icon: string;
}

interface FocusSessionType {
  id?: string;
  duration: number;
  // Add other required properties
}

interface Props {
  activeFocusSession?: FocusSessionType;
  onWellnessEvent: (event: Omit<WellnessEvent, 'id' | 'timestamp'>) => void;
  _onUpdateSettings: (settings: Partial<WellnessSettings>) => void;
}

export const WellnessCenter: React.FC<Props> = ({
  activeFocusSession,
  onWellnessEvent,
  _onUpdateSettings
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reminders' | 'breathing' | 'tracking' | 'analytics'>('dashboard');
  const [wellnessEvents, setWellnessEvents] = useState<WellnessEvent[]>([]);
  const [healthMetrics, setHealthMetrics] = useState<HealthMetrics[]>([]);
  const [settings, _setSettings] = useState<WellnessSettings>({
    eyeStrainReminders: true,
    eyeStrainInterval: 20,
    postureReminders: true,
    postureInterval: 30,
    hydrationReminders: true,
    hydrationInterval: 45,
    breathingExercises: true,
    moodTracking: true,
    energyTracking: true,
    sleepCorrelation: true,
    maxDailyFocusTime: 480,
    enforceBreaks: true,
    minBreakDuration: 5
  });

  const [activeBreathingExercise, setActiveBreathingExercise] = useState<BreathingExercise | null>(null);
  const [breathingTimer, setBreathingTimer] = useState(0);
  const [breathingPhase, setBreathingPhase] = useState(0);
  const [_isBreathing, setIsBreathing] = useState(false);
  const [currentMood, setCurrentMood] = useState<number>(3);
  const [currentEnergy, setCurrentEnergy] = useState<number>(3);
  const [todayWater, setTodayWater] = useState(0);
  const [showMoodLogger, setShowMoodLogger] = useState(false);
  const [_showSettings, setShowSettings] = useState(false);

  const breathingIntervalRef = useRef<NodeJS.Timeout | null>(null);
  const reminderTimeouts = useRef<NodeJS.Timeout[]>([]);

  const breathingExercises: BreathingExercise[] = [
    {
      id: 'box-breathing',
      name: 'Box Breathing',
      description: 'Equal counts for inhale, hold, exhale, hold',
      pattern: [
        { phase: 'inhale', duration: 4 },
        { phase: 'hold', duration: 4 },
        { phase: 'exhale', duration: 4 },
        { phase: 'hold', duration: 4 }
      ],
      totalDuration: 300, // 5 minutes
      benefits: ['Reduces stress', 'Improves focus', 'Calms nervous system'],
      icon: '⬜'
    },
    {
      id: '4-7-8',
      name: '4-7-8 Breathing',
      description: 'Inhale 4, hold 7, exhale 8',
      pattern: [
        { phase: 'inhale', duration: 4 },
        { phase: 'hold', duration: 7 },
        { phase: 'exhale', duration: 8 }
      ],
      totalDuration: 240, // 4 minutes
      benefits: ['Promotes sleep', 'Reduces anxiety', 'Lowers heart rate'],
      icon: '🌙'
    },
    {
      id: 'energizing',
      name: 'Energizing Breath',
      description: 'Quick inhale, slow exhale',
      pattern: [
        { phase: 'inhale', duration: 2 },
        { phase: 'exhale', duration: 6 }
      ],
      totalDuration: 180, // 3 minutes
      benefits: ['Increases energy', 'Improves alertness', 'Boosts concentration'],
      icon: '⚡'
    },
    {
      id: 'relaxing',
      name: 'Relaxing Breath',
      description: 'Long, slow breaths',
      pattern: [
        { phase: 'inhale', duration: 6 },
        { phase: 'exhale', duration: 8 }
      ],
      totalDuration: 420, // 7 minutes
      benefits: ['Deep relaxation', 'Stress relief', 'Mental clarity'],
      icon: '🧘'
    }
  ];

  // Generate mock data
  useEffect(() => {
    const generateMockData = (): void => {
      const events: WellnessEvent[] = [];
      const metrics: HealthMetrics[] = [];

      for (let i = 7; i >= 0; i--) {
        const date = subDays(new Date(), i);

        // Generate wellness events for the day
        const dayEvents: WellnessEvent[] = [
          {
            id: `eye_${i}_1`,
            type: 'eye_strain',
            timestamp: new Date(date.getTime() + 9 * 60 * 60 * 1000), // 9 AM
            completed: Math.random() > 0.3,
          },
          {
            id: `eye_${i}_2`,
            type: 'eye_strain',
            timestamp: new Date(date.getTime() + 14 * 60 * 60 * 1000), // 2 PM
            completed: Math.random() > 0.3,
          },
          {
            id: `hydration_${i}_1`,
            type: 'hydration',
            timestamp: new Date(date.getTime() + 10 * 60 * 60 * 1000), // 10 AM
            completed: Math.random() > 0.2,
            value: Math.floor(Math.random() * 3) + 1
          },
          {
            id: `mood_${i}`,
            type: 'mood',
            timestamp: new Date(date.getTime() + 18 * 60 * 60 * 1000), // 6 PM
            completed: true,
            value: Math.floor(Math.random() * 5) + 1
          }
        ];

        events.push(...dayEvents);

        // Generate health metrics for the day
        metrics.push({
          date,
          sleepHours: Math.random() * 3 + 6, // 6-9 hours
          sleepQuality: Math.floor(Math.random() * 5) + 1,
          stressLevel: Math.floor(Math.random() * 5) + 1,
          exerciseMinutes: Math.random() * 60,
          waterIntake: Math.floor(Math.random() * 8) + 2, // 2-10 glasses
          screenTime: Math.random() * 120 + 300, // 5-7 hours
          focusSessionsCount: Math.floor(Math.random() * 8) + 2,
          focusQuality: Math.floor(Math.random() * 5) + 1,
          mood: Math.floor(Math.random() * 5) + 1,
          energy: Math.floor(Math.random() * 5) + 1
        });
      }

      setWellnessEvents(events);
      setHealthMetrics(metrics);
    };

    generateMockData();
  }, []);

  // Set up wellness reminders
  useEffect(() => {
    // Clear existing timeouts
    reminderTimeouts.current.forEach(timeout => clearTimeout(timeout));
    reminderTimeouts.current = [];

    if (!activeFocusSession) return;

    const scheduleReminder = (type: string, interval: number): void => {
      const timeout = setTimeout(() => {
        showWellnessReminder(type);
      }, interval * 60 * 1000);

      reminderTimeouts.current.push(timeout);
    };

    if (settings.eyeStrainReminders) {
      scheduleReminder('eye_strain', settings.eyeStrainInterval);
    }

    if (settings.postureReminders) {
      scheduleReminder('posture', settings.postureInterval);
    }

    if (settings.hydrationReminders) {
      scheduleReminder('hydration', settings.hydrationInterval);
    }

    return () => {
      reminderTimeouts.current.forEach(timeout => clearTimeout(timeout));
    };
  }, [activeFocusSession, settings]);

  const showWellnessReminder = (type: string): void => {
    const messages = {
      eye_strain: {
        title: 'Eye Care Reminder 👁️',
        message: 'Time for the 20-20-20 rule: Look at something 20 feet away for 20 seconds!'
      },
      posture: {
        title: 'Posture Check 🧍',
        message: 'Check your posture! Sit up straight, shoulders relaxed, feet flat on the floor.'
      },
      hydration: {
        title: 'Hydration Break 💧',
        message: 'Time to drink some water! Staying hydrated improves focus and energy.'
      }
    };

    const reminder = messages[type as keyof typeof messages];

    if ('Notification' in window && Notification.permission === 'granted') {
      new Notification(reminder.title, {
        body: reminder.message,
        icon: '🎯'
      });
    }

    // Add visual reminder (you could implement a toast notification here)
    logger.debug('WellnessCenter', `Wellness reminder: ${reminder.title} - ${reminder.message}`);
  };

  const startBreathingExercise = (exercise: BreathingExercise): void => {
    setActiveBreathingExercise(exercise);
    setBreathingTimer(0);
    setBreathingPhase(0);
    setIsBreathing(true);

    breathingIntervalRef.current = setInterval(() => {
      setBreathingTimer(prev => {
        const newTime = prev + 1;
        const currentPattern = exercise.pattern[breathingPhase % exercise.pattern.length];

        if (newTime >= currentPattern.duration) {
          setBreathingPhase(prevPhase => prevPhase + 1);
          return 0;
        }

        return newTime;
      });
    }, 1000);
  };

  const stopBreathingExercise = (): void => {
    setIsBreathing(false);
    setActiveBreathingExercise(null);
    if (breathingIntervalRef.current) {
      clearInterval(breathingIntervalRef.current);
    }

    // Log breathing exercise completion
    onWellnessEvent({
      type: 'breathing',
      completed: true,
      notes: activeBreathingExercise?.name
    });
  };

  const logMoodAndEnergy = (): void => {
    onWellnessEvent({
      type: 'mood',
      completed: true,
      value: currentMood
    });

    onWellnessEvent({
      type: 'energy',
      completed: true,
      value: currentEnergy
    });

    setShowMoodLogger(false);
  };

  const addWaterIntake = (): void => {
    setTodayWater(prev => prev + 1);
    onWellnessEvent({
      type: 'hydration',
      completed: true,
      value: 1
    });
  };

  const completeEyeStrainExercise = (): void => {
    onWellnessEvent({
      type: 'eye_strain',
      completed: true
    });
  };

  const getTodayMetrics = (): HealthMetrics | undefined => {
    const today = startOfDay(new Date());
    return healthMetrics.find(m => startOfDay(m.date).getTime() === today.getTime());
  };

  const getTodayEvents = (): WellnessEvent[] => {
    const today = new Date();
    return wellnessEvents.filter(event => 
      startOfDay(event.timestamp).getTime() === startOfDay(today).getTime()
    );
  };

  const getWellnessScore = (): number => {
    const todayEvents = getTodayEvents();
    const completed = todayEvents.filter(e => e.completed).length;
    const total = todayEvents.length;
    return total > 0 ? Math.round((completed / total) * 100) : 0;
  };

  const getMoodIcon = (mood: number): JSX.Element => {
    if (mood <= 2) return <Frown className="w-6 h-6 text-red-500" />;
    if (mood <= 3) return <Meh className="w-6 h-6 text-yellow-500" />;
    return <Smile className="w-6 h-6 text-green-500" />;
  };

  const getCurrentBreathingPhase = (): { phase: 'inhale' | 'hold' | 'exhale' | 'rest', duration: number } | null => {
    if (!activeBreathingExercise) return null;
    return activeBreathingExercise.pattern[breathingPhase % activeBreathingExercise.pattern.length];
  };

  const todayMetrics = getTodayMetrics();
  const todayEvents = getTodayEvents();
  const wellnessScore = getWellnessScore();

