          { key: 'dashboard', label: 'Dashboard', icon: Activity },
          { key: 'reminders', label: 'Reminders', icon: Bell },
          { key: 'breathing', label: 'Breathing', icon: Wind },
          { key: 'tracking', label: 'Tracking', icon: Target },
