/**
 * GoalProgressChart Component
 * Simple progress chart matching the app's design system
 */

import React from 'react';
import type { GoalProgressPoint } from '../types';
import { formatCurrency } from '../utils/currency';

interface GoalProgressChartProps {
  expectedPath: GoalProgressPoint[];
  actualPath?: GoalProgressPoint[];
  targetAmount: number;
  currentAmount: number;
  height?: number;
}

export const GoalProgressChart: React.FC<GoalProgressChartProps> = ({
  expectedPath,
  actualPath = [],
  targetAmount,
  _currentAmount,
  height = 120,
}) => {
  const width = 600;
  const padding = { top: 10, right: 40, bottom: 25, left: 60 };
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;

  // Combine all points to find the max value for scaling
  const allPoints = [...expectedPath, ...actualPath];
  const maxAmount = Math.max(targetAmount, ...allPoints.map(p => p.amount));

  // Scale functions
  const scaleY = (amount: number) => {
    const ratio = amount / maxAmount;
    return padding.top + chartHeight - (ratio * chartHeight);
  };

  const scaleX = (index: number, totalPoints: number) => {
    return padding.left + (index / Math.max(1, totalPoints - 1)) * chartWidth;
  };

  // Generate path string for SVG
  const generatePath = (points: GoalProgressPoint[]) => {
    if (points.length === 0) return '';
    return points.map((p, i) => {
      const x = scaleX(i, points.length);
      const y = scaleY(p.amount);
      return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
    }).join(' ');
  };

  const expectedPathString = generatePath(expectedPath);
  const actualPathString = actualPath.length > 0 ? generatePath(actualPath) : '';

  // Format date for display
  const formatDate = (dateISO: string) => {
    return new Date(dateISO).toLocaleDateString('en-US', { month: 'short', year: '2-digit' });
  };

  // Y-axis labels
  const yLabels = [
    { amount: targetAmount, label: formatCurrency(targetAmount, 0) },
    { amount: 0, label: '$0' },
  ];

  return (
    <div className="w-full">
      {/* Chart Title */}
      <h4 className="text-xs font-medium text-primary opacity-70 mb-2">Progress Timeline</h4>

      {/* Chart Container */}
      <div className="relative w-full">
        <svg
          width="100%"
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          preserveAspectRatio="xMidYMid meet"
          className="w-full"
        >
          {/* Grid lines */}
          {yLabels.map((label, i) => (
            <line
              key={i}
              x1={padding.left}
              y1={scaleY(label.amount)}
              x2={padding.left + chartWidth}
              y2={scaleY(label.amount)}
              stroke="currentColor"
              strokeWidth="1"
              opacity="0.15"
            />
          ))}

          {/* Expected path (dashed) */}
          {expectedPathString && (
            <path
              d={expectedPathString}
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              opacity="0.4"
              strokeDasharray="4,4"
            />
          )}

          {/* Actual path */}
          {actualPathString && (
            <path
              d={actualPathString}
              fill="none"
              stroke="#60a5fa"
              strokeWidth="2"
            />
          )}

          {/* Target line */}
          <line
            x1={padding.left}
            y1={scaleY(targetAmount)}
            x2={padding.left + chartWidth}
            y2={scaleY(targetAmount)}
            stroke="#34d399"
            strokeWidth="2"
          />

          {/* Y-axis labels */}
          {yLabels.map((label, i) => (
            <text
              key={i}
              x={padding.left - 10}
              y={scaleY(label.amount)}
              textAnchor="end"
              dominantBaseline="middle"
              fontSize="11"
              fill="currentColor"
              opacity="0.6"
            >
              {label.label}
            </text>
          ))}

          {/* X-axis labels */}
          {expectedPath.length > 0 && (
            <>
              <text
                x={padding.left}
                y={height - 5}
                textAnchor="start"
                fontSize="11"
                fill="currentColor"
                opacity="0.6"
              >
                {formatDate(expectedPath[0].dateISO)}
              </text>
              <text
                x={padding.left + chartWidth}
                y={height - 5}
                textAnchor="end"
                fontSize="11"
                fill="currentColor"
                opacity="0.6"
              >
                {formatDate(expectedPath[expectedPath.length - 1].dateISO)}
              </text>
            </>
          )}
        </svg>
      </div>

      {/* Legend */}
      <div className="mt-2 flex items-center justify-center gap-4 text-xs text-primary opacity-70">
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-0.5 border-t border-dashed border-current opacity-40"></div>
          <span>Expected</span>
        </div>
        {actualPath.length > 0 && (
          <div className="flex items-center gap-1.5">
            <div className="w-3 h-0.5 bg-blue-400"></div>
            <span>Actual</span>
          </div>
        )}
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-0.5 bg-emerald-400"></div>
          <span>Target</span>
        </div>
      </div>
    </div>
  );
};

export default GoalProgressChart;

/**
 * Quick Add Transaction Modal
 *
 * Simple form for adding test transactions quickly
 */

import React from 'react';
import { Button } from '../ui/Button';
import { getFinanceAPI } from '../data';
import { logger } from '../../services/logger';

interface QuickAddTransactionProps {
  onClose: () => void;
  onSuccess: () => void;
}

export const QuickAddTransaction: React.FC<QuickAddTransactionProps> = ({ onClose, onSuccess }) => {
  const [loading, setLoading] = React.useState(false);
  const [accounts, setAccounts] = React.useState<Array<{ id: string; name: string }>>([]);
  const [formData, setFormData] = React.useState({
    accountId: '',
    description: '',
    amount: '',
    date: new Date().toISOString().split('T')[0],
    type: 'debit' as 'debit' | 'credit',
    notes: ''
  });

  // Load accounts
  React.useEffect(() => {
    async function loadAccounts(): Promise<void> {
      try {
        const api = await getFinanceAPI();
        const accts = await api.listAccounts();
        setAccounts(accts);
        if (accts.length > 0) {
          setFormData(prev => ({ ...prev, accountId: accts[0].id }));
        }
      } catch (error) {
        logger.error('Failed to load accounts:', { error });
      }
    }
    loadAccounts();
  }, []);

  const handleSubmit = async (e: React.FormEvent): Promise<void> => {
    e.preventDefault();
    setLoading(true);

    try {
      const api = await getFinanceAPI();
      await api.upsertTransaction({
        accountId: formData.accountId,
        description: formData.description,
        amount: parseFloat(formData.amount),
        dateISO: formData.date,
        type: formData.type,
        notes: formData.notes || undefined,
      });

      onSuccess();
      onClose();
    } catch (error: unknown) {
      logger.error('Failed to add transaction:', { error });
      alert('Failed to add transaction. Check console for details.');
    } finally {
      setLoading(false);
    }
  };

  const presetTransactions: Array<{ description: string; amount: string }> = [
    { description: 'STARBUCKS #1234', amount: '5.75' },
    { description: 'NETFLIX.COM', amount: '15.49' },
    { description: 'WHOLE FOODS', amount: '127.50' },
    { description: 'MY LOCAL CAFE', amount: '4.25' },
    { description: 'AMAZON PRIME', amount: '14.99' },
    { description: 'UBER TRIP', amount: '23.45' },
    { description: 'SPOTIFY PREMIUM', amount: '10.99' },
    { description: 'MCDONALDS #456', amount: '12.50' },
    { description: 'TARGET STORE', amount: '65.30' },
    { description: 'CVS PHARMACY', amount: '28.75' },
  ];

  const fillPreset = React.useCallback((preset: { description: string; amount: string }): void => {
    setFormData(prev => ({
      ...prev,
      description: preset.description,
      amount: preset.amount
    }));
  }, []);

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-lg shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="p-6 border-b border-slate-200">
          <h2 className="text-2xl font-semibold text-slate-900">Quick Add Transaction</h2>
          <p className="text-sm text-slate-600 mt-1">Add a test transaction</p>
        </div>

        {/* Content */}
        <div className="p-6">
          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Account */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">
                Account
              </label>
              <select
                value={formData.accountId}
                onChange={(e) => setFormData({ ...formData, accountId: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-slate-900"
                required
              >
                {accounts.length === 0 && (
                  <option value="">No accounts found - create one first</option>
                )}
                {accounts.map(acc => (
                  <option key={acc.id} value={acc.id}>{acc.name}</option>
                ))}
              </select>
            </div>

            {/* Quick Presets */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">
                Quick Presets (click to fill)
              </label>
              <div className="flex flex-wrap gap-2">
                {presetTransactions.map((preset) => (
                  <button
                    key={preset.description}
                    type="button"
                    onClick={() => fillPreset(preset)}
                    className="text-xs px-3 py-1 bg-slate-100 hover:bg-slate-200 rounded-full border border-slate-300 transition-colors"
                  >
                    {preset.description} (${preset.amount})
                  </button>
                ))}
              </div>
            </div>

            {/* Description */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">
                Description
              </label>
              <input
                type="text"
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-slate-900"
                placeholder="e.g., STARBUCKS #1234"
                required
              />
            </div>

            {/* Amount */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">
                Amount
              </label>
              <input
                type="number"
                step="0.01"
                value={formData.amount}
                onChange={(e) => setFormData({ ...formData, amount: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-slate-900"
                placeholder="0.00"
                required
              />
            </div>

            {/* Date */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">
                Date
              </label>
              <input
                type="date"
                value={formData.date}
                onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-slate-900"
                required
              />
            </div>

            {/* Type */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">
                Type
              </label>
              <div className="flex gap-4">
                <label className="flex items-center">
                  <input
                    type="radio"
                    value="debit"
                    checked={formData.type === 'debit'}
                    onChange={(_e) => setFormData({ ...formData, type: 'debit' })}
                    className="mr-2"
                  />
                  Debit (Expense)
                </label>
                <label className="flex items-center">
                  <input
                    type="radio"
                    value="credit"
                    checked={formData.type === 'credit'}
                    onChange={(_e) => setFormData({ ...formData, type: 'credit' })}
                    className="mr-2"
                  />
                  Credit (Income)
                </label>
              </div>
            </div>

            {/* Notes (optional) */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">
                Notes (optional)
              </label>
              <textarea
                value={formData.notes}
                onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-slate-900"
                rows={2}
                placeholder="Additional notes..."
              />
            </div>
          </form>
        </div>

        {/* Footer */}
        <div className="p-6 border-t border-slate-200 flex justify-between">
          <Button variant="ghost" onClick={onClose} disabled={loading}>
            Cancel
          </Button>
          <Button onClick={handleSubmit} disabled={loading || !formData.accountId}>
            {loading ? 'Adding...' : 'Add Transaction'}
          </Button>
        </div>
      </div>
    </div>
  );
};

/**
 * BudgetEditor Modal Component
 *
 * Modal dialog for creating and editing budgets with form validation.
 */

import React, { useState, useEffect } from 'react';
import { logger } from '../../../services/logger';

import { X, Save, AlertCircle, DollarSign, Lightbulb } from 'lucide-react';
import { formatCurrency } from '../../utils/currency';
import type { Budget, Category } from '../../types';
import type { BudgetRecommendation } from '../../utils/budgetRecommendations';

export interface BudgetEditorProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: { categoryId: string; month: string; limit: number }) => Promise<void>;
  categories: Category[];
  month: string;
  existingBudget?: Budget;
  previousMonthSpent?: number;
  categoryName?: string;
  recommendation?: BudgetRecommendation | null;
  onCategoryChange?: (categoryId: string) => void;
  initialCategoryId?: string;
}

const BudgetEditor: React.FC<BudgetEditorProps> = ({
  isOpen,
  onClose,
  onSave,
  categories,
  month,
  existingBudget,
  previousMonthSpent,
  categoryName,
  recommendation,
  onCategoryChange,
  initialCategoryId,
}): JSX.Element | null => {
  const [categoryId, setCategoryId] = useState<string>(
    existingBudget?.categoryId ?? initialCategoryId ?? ''
  );
  const [limit, setLimit] = useState<string>(
    existingBudget?.limit?.toString() ?? ''
  );
  const [saving, setSaving] = useState<boolean>(false);
  const [error, setError] = useState<string>('');

  const isEditing = Boolean(existingBudget);

  // Reset form when modal opens/closes or budget changes
  useEffect(() => {
    if (isOpen) {
      logger.info('BudgetEditor', '[BudgetEditor] Modal opened with:', {
        existingBudget,
        recommendation,
        categoriesCount: categories.length,
        initialCategoryId,
      });

      const selectedCategory = existingBudget?.categoryId ?? initialCategoryId ?? '';
      logger.info('BudgetEditor', '[BudgetEditor] Setting category to:', selectedCategory);
      setCategoryId(selectedCategory);

      // Pre-fill with recommendation for new budgets, or existing limit for edits
      if (existingBudget) {
        logger.info('BudgetEditor', '[BudgetEditor] Editing existing budget, setting limit to:', existingBudget.limit);
        setLimit(existingBudget.limit?.toString() ?? '');
      } else if (recommendation?.suggested) {
        logger.info('BudgetEditor', '[BudgetEditor] Pre-filling with recommendation:', recommendation.suggested);
        setLimit(recommendation.suggested.toString());
      } else {
        logger.info('BudgetEditor', '[BudgetEditor] No recommendation available, leaving limit empty');
        setLimit('');
      }

      setError('');
    }
  }, [isOpen, existingBudget, recommendation, categories.length, initialCategoryId]);

  // Don't render if not open
  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent): Promise<void> => {
    e.preventDefault();
    setError('');

    // Validation
    if (!categoryId) {
      setError('Please select a category');
      return;
    }

    const limitNum = parseFloat(limit);
    if (isNaN(limitNum) || limitNum < 0) {
      setError('Please enter a valid positive amount');
      return;
    }

    try {
      setSaving(true);
      await onSave({
        categoryId,
        month,
        limit: limitNum,
      });
      onClose();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to save budget');
    } finally {
      setSaving(false);
    }
  };

  const handleBackdropClick = (e: React.MouseEvent): void => {
    if (e.target === e.currentTarget) {
      onClose();
    }
  };

  const _selectedCategory = categories.find((c) => c.id === categoryId);

  // Format month display
  const monthDisplay = new Date(`${month}-01`).toLocaleDateString('en-US', {
    month: 'long',
    year: 'numeric',
  });

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4"
      onClick={handleBackdropClick}
    >
      <div className="relative w-full max-w-md max-h-[90vh] rounded-2xl bg-white shadow-2xl ring-1 ring-black/5 flex flex-col">
        {/* Header - Fixed */}
        <div className="flex-shrink-0 flex items-center justify-between border-b border-slate-200 px-6 py-4">
          <div>
            <h2 className="text-lg font-semibold text-slate-900">
              {isEditing ? 'Edit Budget' : 'Create Budget'}
            </h2>
            <p className="text-sm text-slate-600 mt-0.5">{monthDisplay}</p>
          </div>
          <button
            onClick={onClose}
            className="rounded-lg p-1.5 hover:bg-slate-100 transition-colors"
            aria-label="Close"
          >
            <X className="h-5 w-5 text-slate-600" />
          </button>
        </div>

        {/* Form - Scrollable */}
        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto min-h-0 px-6 py-5 space-y-5">
          {/* Category Selector */}
          <div>
            <label htmlFor="category" className="block text-sm font-medium text-slate-700 mb-2">
              Category
            </label>
            <select
              id="category"
              value={categoryId}
              onChange={(e) => {
                const newCategoryId = e.target.value;
                logger.info('BudgetEditor', '[BudgetEditor] Category changed to:', newCategoryId);
                setCategoryId(newCategoryId);
                if (onCategoryChange) {
                  logger.info('BudgetEditor', '[BudgetEditor] Calling onCategoryChange callback');
                  onCategoryChange(newCategoryId);
                }
              }}
              disabled={isEditing || saving}
              className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-500/20 disabled:bg-slate-50 disabled:text-slate-500 disabled:cursor-not-allowed"
              required
            >
              <option value="">Select a category...</option>
              {categories.map((cat) => (
                <option key={cat.id} value={cat.id}>
                  {cat.name}
                </option>
              ))}
            </select>
            {isEditing && categoryName && (
              <p className="mt-1.5 text-xs text-slate-500">
                Editing budget for <span className="font-medium">{categoryName}</span>
              </p>
            )}
          </div>

          {/* Budget Amount */}
          <div>
            <label htmlFor="limit" className="block text-sm font-medium text-slate-700 mb-2">
              Budget Limit
            </label>
            <div className="relative">
              <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                <DollarSign className="h-4 w-4 text-slate-400" />
              </div>
              <input
                id="limit"
                type="number"
                step="0.01"
                min="0"
                value={limit}
                onChange={(e) => setLimit(e.target.value)}
                disabled={saving}
                className="w-full rounded-lg border border-slate-300 bg-white pl-9 pr-3 py-2 text-sm text-slate-900 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-500/20 disabled:bg-slate-50 disabled:text-slate-500"
                placeholder="0.00"
                required
              />
            </div>
          </div>

          {/* Smart Recommendation */}
          {recommendation && !isEditing && (
            <div className={`rounded-lg border p-3 ${
              recommendation.confidence === 'high'
                ? 'bg-emerald-50 border-emerald-200'
                : recommendation.confidence === 'medium'
                ? 'bg-blue-50 border-blue-200'
                : 'bg-amber-50 border-amber-200'
            }`}>
              <div className="flex items-start gap-2">
                <Lightbulb className={`h-4 w-4 flex-shrink-0 mt-0.5 ${
                  recommendation.confidence === 'high'
                    ? 'text-emerald-600'
                    : recommendation.confidence === 'medium'
                    ? 'text-blue-600'
                    : 'text-amber-600'
                }`} />
                <div className="flex-1 min-w-0">
                  <p className={`text-xs font-medium ${
                    recommendation.confidence === 'high'
                      ? 'text-emerald-900'
                      : recommendation.confidence === 'medium'
                      ? 'text-blue-900'
                      : 'text-amber-900'
                  }`}>
                    Smart Recommendation
                  </p>
                  <p className="text-xs text-slate-700 mt-1">
                    Based on {recommendation.monthsAnalyzed} month{recommendation.monthsAnalyzed > 1 ? 's' : ''} of spending:
                    <span className="font-semibold"> ${recommendation.average.toFixed(0)}</span> avg
                    {recommendation.min !== recommendation.max && (
                      <span className="text-slate-600">
                        {' '}(${recommendation.min.toFixed(0)} - ${recommendation.max.toFixed(0)})
                      </span>
                    )}
                  </p>
                  <p className="text-xs text-slate-500 mt-1">
                    Suggested amount includes 10% buffer for safety
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Historical Insight */}
          {previousMonthSpent !== undefined && previousMonthSpent > 0 && (
            <div className="rounded-lg bg-blue-50 border border-blue-200 p-3">
              <div className="flex items-start gap-2">
                <AlertCircle className="h-4 w-4 text-blue-600 flex-shrink-0 mt-0.5" />
                <div className="text-xs text-slate-700">
                  <p className="font-medium text-blue-900">Previous Month Spending</p>
                  <p className="mt-1">
                    You spent <span className="font-semibold">{formatCurrency(previousMonthSpent)}</span> last month
                    in this category.
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Error Message */}
          {error && (
            <div className="rounded-lg bg-rose-50 border border-rose-200 p-3">
              <div className="flex items-start gap-2">
                <AlertCircle className="h-4 w-4 text-rose-600 flex-shrink-0 mt-0.5" />
                <p className="text-xs text-rose-900">{error}</p>
              </div>
            </div>
          )}

          {/* Action Buttons */}
          <div className="flex items-center gap-3 pt-2">
            <button
              type="button"
              onClick={onClose}
              disabled={saving}
              className="flex-1 rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-slate-500/20 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={saving}
              className="flex-1 inline-flex items-center justify-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500/50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {saving ? (
                <>
                  <div className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent"></div>
                  Saving...
                </>
              ) : (
                <>
                  <Save className="h-4 w-4" />
                  {isEditing ? 'Update Budget' : 'Create Budget'}
                </>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default BudgetEditor;

/**
 * BudgetProgressBar Component
 *
 * Color-coded progress bar for budget tracking with YNAB-style thresholds:
 * - Green (0-79%): Safe spending
 * - Yellow (80-99%): Warning - approaching limit
 * - Red (100%+): Over budget
 */

import React from 'react';

export interface BudgetProgressBarProps {
  spent: number;
  limit: number;
  className?: string;
  showPercentage?: boolean;
}

export type BudgetStatus = 'safe' | 'warning' | 'over';

export const getBudgetStatus = (percentage: number): BudgetStatus => {
  if (percentage >= 100) return 'over';
  if (percentage >= 80) return 'warning';
  return 'safe';
};

export const getBudgetColor = (status: BudgetStatus): string => {
  switch (status) {
    case 'over':
      return 'rose'; // Red
    case 'warning':
      return 'amber'; // Yellow
    case 'safe':
    default:
      return 'emerald'; // Green
  }
};

const BudgetProgressBar: React.FC<BudgetProgressBarProps> = ({
  spent,
  limit,
  className = '',
  showPercentage = false,
}) => {
  const percentage = limit > 0 ? (spent / limit) * 100 : 0;
  const cappedPercentage = Math.min(100, percentage); // Cap visual at 100%
  const status = getBudgetStatus(percentage);
  const color = getBudgetColor(status);

  // Color classes based on status
  const colorClasses: Record<string, { bg: string; text: string }> = {
    emerald: {
      bg: 'bg-emerald-500',
      text: 'text-emerald-700',
    },
    amber: {
      bg: 'bg-amber-500',
      text: 'text-amber-700',
    },
    rose: {
      bg: 'bg-rose-500',
      text: 'text-rose-700',
    },
  };

  const { bg, text } = colorClasses[color];

  return (
    <div className={`space-y-1 ${className}`}>
      {/* Progress bar */}
      <div className="h-2.5 w-full rounded-full bg-primary/20">
        <div
          className={`h-2.5 rounded-full ${bg} transition-all duration-300`}
          style={{ width: `${cappedPercentage}%` }}
        />
      </div>

      {/* Percentage indicator */}
      {showPercentage && (
        <div className="flex items-center justify-between text-xs">
          <span className={`font-semibold ${text}`}>
            {percentage.toFixed(0)}% used
          </span>
          {percentage >= 100 && (
            <span className="text-rose-600 font-semibold">Over budget!</span>
          )}
        </div>
      )}
    </div>
  );
};

export default BudgetProgressBar;

/**
 * CardBenefitsPanel Component
 * Displays and tracks credit card benefits, category bonuses, welcome bonuses, and offers
 */

import React from 'react';
import { Gift, TrendingUp, Target, Tag, Calendar, Award, Plane, Coffee } from 'lucide-react';
import type { CardBenefit, CardCategoryBonus, WelcomeBonus, CardOffer } from '../../types';
import { formatCurrency } from '../../utils/currency';

interface CardBenefitsPanelProps {
  accountId: string;
  benefits: CardBenefit[];
  categoryBonuses: CardCategoryBonus[];
  welcomeBonuses: WelcomeBonus[];
  offers: CardOffer[];
  className?: string;
}

export const CardBenefitsPanel: React.FC<CardBenefitsPanelProps> = ({
  _accountId,
  benefits,
  categoryBonuses,
  welcomeBonuses,
  offers,
  className = '',
}) => {
  // Group benefits by type
  const benefitsByType = benefits.reduce((acc, benefit) => {
    if (!acc[benefit.benefitType]) {
      acc[benefit.benefitType] = [];
    }
    acc[benefit.benefitType].push(benefit);
    return acc;
  }, {} as Record<string, CardBenefit[]>);

  // Get benefit type icon and label
  const getBenefitTypeConfig = (type: string) => {
    switch (type) {
      case 'travel_credit':
        return { icon: Plane, label: 'Travel Credits', color: 'text-blue-600' };
      case 'recurring_credit':
        return { icon: Calendar, label: 'Recurring Credits', color: 'text-purple-600' };
      case 'lounge_access':
        return { icon: Coffee, label: 'Lounge Access', color: 'text-amber-600' };
      case 'protection':
        return { icon: Award, label: 'Protection Benefits', color: 'text-emerald-600' };
      default:
        return { icon: Gift, label: 'Other Benefits', color: 'text-gray-600' };
    }
  };

  // Calculate welcome bonus progress
  const getWelcomeBonusProgress = (bonus: WelcomeBonus) => {
    const progress = (bonus.currentSpend / bonus.requiredSpend) * 100;
    const remaining = bonus.requiredSpend - bonus.currentSpend;
    const daysRemaining = Math.ceil((new Date(bonus.deadline).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24));

    return {
      progress: Math.min(100, progress),
      remaining,
      daysRemaining,
      isUrgent: daysRemaining <= 30,
      isCompleted: bonus.completed,
    };
  };

  // Calculate benefit usage progress
  const getBenefitProgress = (benefit: CardBenefit) => {
    if (!benefit.value) return null;
    const progress = (benefit.usedAmount / benefit.value) * 100;
    return {
      progress: Math.min(100, progress),
      remaining: benefit.value - benefit.usedAmount,
      isFullyUsed: benefit.usedAmount >= benefit.value,
    };
  };

  return (
    <div className={`space-y-6 ${className}`}>
      {/* Welcome Bonuses Section */}
      {welcomeBonuses.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center gap-2">
            <Target className="h-5 w-5 text-rose-600" />
            <h3 className="text-lg font-semibold text-primary">Welcome Bonus</h3>
          </div>

          {welcomeBonuses.map((bonus) => {
            const progress = getWelcomeBonusProgress(bonus);
            return (
              <div
                key={bonus.id}
                className={`rounded-xl p-4 border ${
                  progress.isCompleted
                    ? 'bg-emerald-50 border-emerald-200'
                    : progress.isUrgent
                    ? 'bg-rose-50 border-rose-200'
                    : 'bg-blue-50 border-blue-200'
                }`}
              >
                <div className="flex items-start justify-between mb-3">
                  <div>
                    <h4 className="font-semibold text-primary">
                      {bonus.bonusAmount.toLocaleString()} Points
                    </h4>
                    <p className="text-sm text-primary opacity-70">
                      Spend {formatCurrency(bonus.requiredSpend)} by {new Date(bonus.deadline).toLocaleDateString()}
                    </p>
                  </div>
                  {progress.isCompleted ? (
                    <span className="text-2xl">✅</span>
                  ) : progress.isUrgent ? (
                    <span className="text-2xl">⏰</span>
                  ) : (
                    <span className="text-2xl">🎯</span>
                  )}
                </div>

                {!progress.isCompleted && (
                  <>
                    <div className="mb-2">
                      <div className="flex items-center justify-between text-sm mb-1">
                        <span className="text-primary opacity-70">Progress</span>
                        <span className="font-semibold text-primary">
                          {formatCurrency(bonus.currentSpend)} / {formatCurrency(bonus.requiredSpend)}
                        </span>
                      </div>
                      <div className="h-2.5 w-full rounded-full bg-white/50 overflow-hidden">
                        <div
                          className={`h-full transition-all duration-300 ${
                            progress.isUrgent ? 'bg-rose-500' : 'bg-blue-500'
                          }`}
                          style={{ width: `${progress.progress}%` }}
                        />
                      </div>
                    </div>

                    <div className="flex items-center justify-between text-sm">
                      <span className={progress.isUrgent ? 'text-rose-700 font-medium' : 'text-primary opacity-70'}>
                        {formatCurrency(progress.remaining)} remaining
                      </span>
                      <span className={progress.isUrgent ? 'text-rose-700 font-medium' : 'text-primary opacity-70'}>
                        {progress.daysRemaining} days left
                      </span>
                    </div>
                  </>
                )}

                {progress.isCompleted && bonus.completedDate && (
                  <p className="text-sm text-emerald-700">
                    Completed on {new Date(bonus.completedDate).toLocaleDateString()}
                  </p>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Category Bonuses Section */}
      {categoryBonuses.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center gap-2">
            <TrendingUp className="h-5 w-5 text-green-600" />
            <h3 className="text-lg font-semibold text-primary">Earning Rates</h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {categoryBonuses.map((bonus) => (
              <div
                key={bonus.id}
                className={`rounded-lg p-3 border ${
                  bonus.isRotating
                    ? 'bg-amber-50 border-amber-200'
                    : 'bg-green-50 border-green-200'
                }`}
              >
                <div className="flex items-center justify-between">
                  <div>
                    <p className="font-semibold text-primary capitalize">
                      {bonus.category}
                    </p>
                    {bonus.isRotating && bonus.endDate && (
                      <p className="text-xs text-primary opacity-60">
                        Until {new Date(bonus.endDate).toLocaleDateString()}
                      </p>
                    )}
                  </div>
                  <div className="text-right">
                    <p className={`text-lg font-bold ${bonus.isRotating ? 'text-amber-700' : 'text-green-700'}`}>
                      {bonus.rewardsRate}x
                    </p>
                    <p className="text-xs text-primary opacity-60">points</p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Benefits Section - Grouped by Type */}
      {Object.keys(benefitsByType).length > 0 && (
        <div className="space-y-4">
          {Object.entries(benefitsByType).map(([type, typeBenefits]) => {
            const config = getBenefitTypeConfig(type);
            const Icon = config.icon;

            return (
              <div key={type} className="space-y-3">
                <div className="flex items-center gap-2">
                  <Icon className={`h-5 w-5 ${config.color}`} />
                  <h3 className="text-lg font-semibold text-primary">{config.label}</h3>
                </div>

                <div className="space-y-2">
                  {typeBenefits.map((benefit) => {
                    const progress = getBenefitProgress(benefit);

                    return (
                      <div
                        key={benefit.id}
                        className={`rounded-lg p-3 border transition-all ${
                          !benefit.active
                            ? 'bg-gray-50 border-gray-200 opacity-50'
                            : progress?.isFullyUsed
                            ? 'bg-gray-50 border-gray-300'
                            : 'bg-primary/5 border-primary/20 hover:bg-primary/10'
                        }`}
                      >
                        <div className="flex items-start justify-between mb-2">
                          <div className="flex-1">
                            <div className="flex items-center gap-2">
                              <h4 className="font-semibold text-primary">{benefit.name}</h4>
                              {!benefit.active && (
                                <span className="text-xs px-2 py-0.5 rounded-full bg-gray-200 text-gray-600">
                                  Inactive
                                </span>
                              )}
                            </div>
                            {benefit.description && (
                              <p className="text-sm text-primary opacity-70 mt-1">
                                {benefit.description}
                              </p>
                            )}
                          </div>
                          {benefit.value && (
                            <div className="text-right ml-3">
                              <p className="text-lg font-bold text-primary">
                                {formatCurrency(benefit.value)}
                              </p>
                              {benefit.frequency && (
                                <p className="text-xs text-primary opacity-60 capitalize">
                                  {benefit.frequency}
                                </p>
                              )}
                            </div>
                          )}
                        </div>

                        {progress && benefit.value && (
                          <div>
                            <div className="flex items-center justify-between text-sm mb-1">
                              <span className="text-primary opacity-70">Used</span>
                              <span className="font-semibold text-primary">
                                {formatCurrency(benefit.usedAmount)} / {formatCurrency(benefit.value)}
                              </span>
                            </div>
                            <div className="h-2 w-full rounded-full bg-primary/20 overflow-hidden">
                              <div
                                className={`h-full transition-all duration-300 ${
                                  progress.isFullyUsed ? 'bg-gray-400' : 'bg-blue-500'
                                }`}
                                style={{ width: `${progress.progress}%` }}
                              />
                            </div>
                            {progress.remaining > 0 && benefit.resetDate && (
                              <p className="text-xs text-primary opacity-60 mt-1">
                                {formatCurrency(progress.remaining)} remaining • Resets {new Date(benefit.resetDate).toLocaleDateString()}
                              </p>
                            )}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Card Offers Section */}
      {offers.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center gap-2">
            <Tag className="h-5 w-5 text-indigo-600" />
            <h3 className="text-lg font-semibold text-primary">Card Offers</h3>
          </div>

          <div className="space-y-2">
            {offers.map((offer) => {
              const isExpired = offer.expirationDate && new Date(offer.expirationDate) < new Date();
              const isRedeemed = offer.redeemed;

              return (
                <div
                  key={offer.id}
                  className={`rounded-lg p-3 border ${
                    isRedeemed
                      ? 'bg-emerald-50 border-emerald-200'
                      : isExpired
                      ? 'bg-gray-50 border-gray-200 opacity-50'
                      : offer.activated
                      ? 'bg-blue-50 border-blue-200'
                      : 'bg-indigo-50 border-indigo-200'
                  }`}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1">
                        <h4 className="font-semibold text-primary">{offer.merchant}</h4>
                        {!offer.activated && !isExpired && (
                          <span className="text-xs px-2 py-0.5 rounded-full bg-indigo-200 text-indigo-700">
                            Not Activated
                          </span>
                        )}
                        {isRedeemed && (
                          <span className="text-xs px-2 py-0.5 rounded-full bg-emerald-200 text-emerald-700">
                            Redeemed
                          </span>
                        )}
                        {isExpired && (
                          <span className="text-xs px-2 py-0.5 rounded-full bg-gray-200 text-gray-600">
                            Expired
                          </span>
                        )}
                      </div>
                      <p className="text-sm text-primary opacity-70 capitalize">
                        {offer.offerType}: {formatCurrency(offer.offerAmount)}
                        {offer.requiredSpend && ` (Spend ${formatCurrency(offer.requiredSpend)})`}
                      </p>
                      {offer.expirationDate && !isExpired && (
                        <p className="text-xs text-primary opacity-60 mt-1">
                          Expires {new Date(offer.expirationDate).toLocaleDateString()}
                        </p>
                      )}
                      {isRedeemed && offer.redeemedDate && (
                        <p className="text-xs text-emerald-700 mt-1">
                          Redeemed on {new Date(offer.redeemedDate).toLocaleDateString()}
                        </p>
                      )}
                    </div>
                    <span className="text-2xl ml-3">
                      {isRedeemed ? '✅' : offer.activated ? '🔵' : '💰'}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Empty State */}
      {benefits.length === 0 && categoryBonuses.length === 0 && welcomeBonuses.length === 0 && offers.length === 0 && (
        <div className="text-center py-12">
          <Gift className="h-12 w-12 text-primary opacity-30 mx-auto mb-3" />
          <p className="text-primary opacity-70">No benefits tracked for this card</p>
          <p className="text-sm text-primary opacity-50 mt-1">
            Add benefits manually or select a card template
          </p>
        </div>
      )}
    </div>
  );
};

export default CardBenefitsPanel;

/**
 * CardTemplateSelector Component
 * Allows users to select a credit card template to auto-populate benefits
 */

import React, { useState } from 'react';
import { Search, CreditCard, Award, Gift, DollarSign, CheckCircle } from 'lucide-react';
import { getAvailableCardTemplates, calculateAnnualBenefitValue, getNetAnnualValue } from '../../utils/cardBenefitsHelper';
import { formatCurrency } from '../../utils/currency';
import type { CreditCardTemplate } from '../../utils/creditCardTemplates';

interface CardTemplateSelectorProps {
  onSelect: (template: CreditCardTemplate | null) => void;
  selectedTemplateId?: string;
  className?: string;
}

export const CardTemplateSelector: React.FC<CardTemplateSelectorProps> = ({
  onSelect,
  selectedTemplateId,
  className = '',
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const templates = getAvailableCardTemplates();

  const filteredTemplates = templates.filter((template) => {
    if (!searchTerm) return true;
    const normalized = searchTerm.toLowerCase();
    return (
      template.name.toLowerCase().includes(normalized) ||
      template.issuer.toLowerCase().includes(normalized)
    );
  });

  const getIssuerColor = (issuer: string) => {
    switch (issuer) {
      case 'amex':
        return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'chase':
        return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case 'capital_one':
        return 'bg-rose-100 text-rose-700 border-rose-200';
      case 'citi':
        return 'bg-cyan-100 text-cyan-700 border-cyan-200';
      case 'discover':
        return 'bg-orange-100 text-orange-700 border-orange-200';
      default:
        return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  const getIssuerName = (issuer: string) => {
    return issuer.split('_').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
  };

  return (
    <div className={`space-y-4 ${className}`}>
      {/* Search */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-primary opacity-40" />
        <input
          type="text"
          placeholder="Search for a credit card..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-primary/20 bg-white text-primary placeholder:text-primary placeholder:opacity-40 focus:outline-none focus:ring-2 focus:ring-blue-500/30"
        />
      </div>

      {/* Manual Entry Option */}
      <button
        onClick={() => onSelect(null)}
        className={`w-full rounded-lg border-2 border-dashed p-4 text-left transition-all hover:bg-primary/5 ${
          !selectedTemplateId
            ? 'border-blue-500 bg-blue-50'
            : 'border-primary/20 bg-white'
        }`}
      >
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="rounded-lg bg-primary/10 p-2">
              <CreditCard className="h-5 w-5 text-primary" />
            </div>
            <div>
              <p className="font-semibold text-primary">Enter Manually</p>
              <p className="text-sm text-primary opacity-60">Custom card without template</p>
            </div>
          </div>
          {!selectedTemplateId && (
            <CheckCircle className="h-5 w-5 text-blue-600" />
          )}
        </div>
      </button>

      {/* Template Grid */}
      <div className="space-y-2 max-h-96 overflow-y-auto">
        {filteredTemplates.length === 0 ? (
          <div className="text-center py-8">
            <p className="text-primary opacity-60">No cards found</p>
            <p className="text-sm text-primary opacity-40 mt-1">Try a different search term</p>
          </div>
        ) : (
          filteredTemplates.map((template) => {
            const isSelected = selectedTemplateId === template.id;
            const annualValue = calculateAnnualBenefitValue(template.id);
            const netValue = getNetAnnualValue(template.id);

            return (
              <button
                key={template.id}
                onClick={() => {
                  // Need to import full template
                  import('../../utils/creditCardTemplates').then((module) => {
                    const fullTemplate = module.getCardTemplateById(template.id);
                    if (fullTemplate) {
                      onSelect(fullTemplate);
                    }
                  });
                }}
                className={`w-full rounded-lg border p-4 text-left transition-all ${
                  isSelected
                    ? 'border-blue-500 bg-blue-50 ring-2 ring-blue-500/30'
                    : 'border-primary/20 bg-white hover:bg-primary/5'
                }`}
              >
                <div className="flex items-start justify-between mb-3">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <h4 className="font-semibold text-primary">{template.name}</h4>
                      {isSelected && <CheckCircle className="h-4 w-4 text-blue-600" />}
                    </div>
                    <span
                      className={`inline-block text-xs px-2 py-0.5 rounded-full border ${getIssuerColor(
                        template.issuer
                      )}`}
                    >
                      {getIssuerName(template.issuer)}
                    </span>
                  </div>
                  <div className="text-right ml-3">
                    <p className="text-sm font-semibold text-primary">
                      {template.annualFee > 0 ? formatCurrency(template.annualFee) : 'No fee'}
                    </p>
                    <p className="text-xs text-primary opacity-60">Annual Fee</p>
                  </div>
                </div>

                {/* Benefits Summary */}
                <div className="grid grid-cols-2 gap-2 mb-3">
                  <div className="flex items-center gap-1.5">
                    <Award className="h-3.5 w-3.5 text-primary opacity-60" />
                    <span className="text-xs text-primary opacity-70">
                      {template.baseRewardsRate}x {template.rewardsType}
                    </span>
                  </div>
                  {template.benefitsCount > 0 && (
                    <div className="flex items-center gap-1.5">
                      <Gift className="h-3.5 w-3.5 text-primary opacity-60" />
                      <span className="text-xs text-primary opacity-70">
                        {template.benefitsCount} benefits
                      </span>
                    </div>
                  )}
                  {template.bonusesCount > 0 && (
                    <div className="flex items-center gap-1.5">
                      <DollarSign className="h-3.5 w-3.5 text-primary opacity-60" />
                      <span className="text-xs text-primary opacity-70">
                        {template.bonusesCount}x categories
                      </span>
                    </div>
                  )}
                  {template.hasWelcomeBonus && (
                    <div className="flex items-center gap-1.5">
                      <span className="text-xs">🎯</span>
                      <span className="text-xs text-primary opacity-70">Welcome bonus</span>
                    </div>
                  )}
                </div>

                {/* Value Proposition */}
                {annualValue > 0 && (
                  <div className="pt-3 border-t border-primary/10">
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-primary opacity-70">Annual value:</span>
                      <span className="font-semibold text-primary">
                        {formatCurrency(annualValue)}
                      </span>
                    </div>
                    {netValue !== 0 && (
                      <div className="flex items-center justify-between text-sm mt-1">
                        <span className="text-primary opacity-70">Net value:</span>
                        <span
                          className={`font-semibold ${
                            netValue > 0 ? 'text-emerald-600' : 'text-rose-600'
                          }`}
                        >
                          {netValue > 0 ? '+' : ''}
                          {formatCurrency(netValue)}
                        </span>
                      </div>
                    )}
                  </div>
                )}
              </button>
            );
          })
        )}
      </div>

      {filteredTemplates.length > 0 && (
        <p className="text-xs text-primary opacity-50 text-center">
          {filteredTemplates.length} card{filteredTemplates.length !== 1 ? 's' : ''} available
        </p>
      )}
    </div>
  );
};

