/**
 * CreditCardCard Component
 * Displays credit card details with utilization, due dates, and payment tracking
 */

import React from 'react';
import { CreditCard, Calendar, TrendingUp, DollarSign } from 'lucide-react';
import type { Account } from '../../types';
import { formatCurrency } from '../../utils/currency';

interface CreditCardCardProps {
  card: Account;
  className?: string;
}

export const CreditCardCard: React.FC<CreditCardCardProps> = ({ card, className = '' }) => {
  // Calculate utilization percentage
  const utilization = card.creditLimit && card.creditLimit > 0
    ? (Math.abs(card.balance) / card.creditLimit) * 100
    : 0;

  const availableCredit = card.creditLimit ? card.creditLimit - Math.abs(card.balance) : 0;

  // Calculate next due date
  const getNextDueDate = () => {
    if (!card.paymentDueDay) return null;
    const today = new Date();
    const dueDate = new Date(today.getFullYear(), today.getMonth(), card.paymentDueDay);

    // If due date has passed this month, show next month
    if (dueDate < today) {
      dueDate.setMonth(dueDate.getMonth() + 1);
    }

    return dueDate;
  };

  const nextDueDate = getNextDueDate();
  const daysUntilDue = nextDueDate
    ? Math.ceil((nextDueDate.getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24))
    : null;

  // Status-based styling
  const getUtilizationStatus = () => {
    if (utilization >= 90) return {
      status: 'critical',
      borderColor: 'border-rose-500/30',
      bgColor: 'bg-rose-500/10',
      textColor: 'text-rose-700',
      barColor: 'bg-rose-500',
      icon: '🔴',
      message: 'Very high utilization - pay down soon'
    };
    if (utilization >= 70) return {
      status: 'warning',
      borderColor: 'border-amber-500/30',
      bgColor: 'bg-amber-500/10',
      textColor: 'text-amber-700',
      barColor: 'bg-amber-500',
      icon: '⚠️',
      message: 'High utilization - consider paying down'
    };
    if (utilization >= 30) return {
      status: 'good',
      borderColor: 'border-blue-500/30',
      bgColor: 'bg-blue-500/10',
      textColor: 'text-blue-700',
      barColor: 'bg-blue-500',
      icon: '✓',
      message: 'Healthy utilization'
    };
    return {
      status: 'excellent',
      borderColor: 'border-emerald-500/30',
      bgColor: 'bg-emerald-500/10',
      textColor: 'text-emerald-700',
      barColor: 'bg-emerald-500',
      icon: '✨',
      message: 'Excellent utilization'
    };
  };

  const statusConfig = getUtilizationStatus();

  // Due date warning
  const getDueDateStatus = () => {
    if (!daysUntilDue) return null;
    if (daysUntilDue <= 3) return {
      color: 'text-rose-600',
      icon: '🔴',
      message: 'Due very soon!'
    };
    if (daysUntilDue <= 7) return {
      color: 'text-amber-600',
      icon: '⚠️',
      message: 'Due soon'
    };
    return {
      color: 'text-primary opacity-70',
      icon: '📅',
      message: ''
    };
  };

  const dueDateStatus = getDueDateStatus();

  return (
    <div
      className={`rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 ${statusConfig.borderColor} p-5 transition-all hover:shadow-md ${className}`}
    >
      {/* Header */}
      <div className="flex items-start justify-between mb-4">
        <div className="flex items-center gap-3">
          <div className={`rounded-lg ${statusConfig.bgColor} p-2.5`}>
            <CreditCard className={`h-5 w-5 ${statusConfig.textColor}`} />
          </div>
          <div>
            <h3 className="text-lg font-semibold text-primary">{card.name}</h3>
            {card.apr && (
              <p className="text-xs text-primary opacity-60 mt-0.5">
                {card.apr.toFixed(2)}% APR
              </p>
            )}
          </div>
        </div>
        <span className="text-2xl">{statusConfig.icon}</span>
      </div>

      {/* Rewards and Annual Fee */}
      {(card.rewardsBalance !== undefined || card.annualFee !== undefined) && (
        <div className="grid grid-cols-2 gap-4 mb-4 pb-4 border-b border-primary/20">
          {card.rewardsBalance !== undefined && (
            <div>
              <p className="text-xs font-medium text-primary opacity-70 mb-1">
                {card.rewardsType === 'points' ? 'Points' : card.rewardsType === 'miles' ? 'Miles' : 'Cash Back'}
              </p>
              <p className="text-lg font-bold text-blue-600">
                {card.rewardsType === 'cashback'
                  ? formatCurrency(card.rewardsBalance)
                  : card.rewardsBalance.toLocaleString()}
              </p>
            </div>
          )}
          {card.annualFee !== undefined && card.annualFee > 0 && (
            <div>
              <p className="text-xs font-medium text-primary opacity-70 mb-1">Annual Fee</p>
              <p className="text-lg font-bold text-primary">
                {formatCurrency(card.annualFee)}
              </p>
              {card.annualFeeDueDate && (
                <p className="text-xs text-primary opacity-60 mt-0.5">
                  Due {new Date(card.annualFeeDueDate).toLocaleDateString('en-US', { month: 'short', year: 'numeric' })}
                </p>
              )}
            </div>
          )}
        </div>
      )}

      {/* Balance and Limit */}
      <div className="grid grid-cols-2 gap-4 mb-4">
        <div>
          <p className="text-xs font-medium text-primary opacity-70 mb-1">Current Balance</p>
          <p className="text-xl font-bold text-primary">
            {formatCurrency(Math.abs(card.balance))}
          </p>
        </div>
        {card.creditLimit && (
          <div>
            <p className="text-xs font-medium text-primary opacity-70 mb-1">Credit Limit</p>
            <p className="text-xl font-bold text-primary">
              {formatCurrency(card.creditLimit)}
            </p>
          </div>
        )}
      </div>

      {/* Utilization Bar */}
      {card.creditLimit && (
        <div className="mb-4">
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs font-medium text-primary opacity-70">Utilization</span>
            <span className={`text-sm font-semibold ${statusConfig.textColor}`}>
              {utilization.toFixed(1)}%
            </span>
          </div>
          <div className="h-3 w-full rounded-full bg-primary/20 overflow-hidden">
            <div
              className={`h-full ${statusConfig.barColor} transition-all duration-300`}
              style={{ width: `${Math.min(100, utilization)}%` }}
            />
          </div>
          <p className="text-xs text-primary opacity-60 mt-1.5">
            {formatCurrency(availableCredit)} available
          </p>
        </div>
      )}

      {/* Status Message */}
      <div className={`mb-4 p-2.5 rounded-lg ${statusConfig.bgColor} border border-primary/20`}>
        <p className={`text-xs font-medium ${statusConfig.textColor}`}>
          {statusConfig.message}
        </p>
      </div>

      {/* Payment Info */}
      <div className="space-y-2 pt-3 border-t border-primary/20">
        {card.minimumPayment && (
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-1.5">
              <DollarSign className="h-3.5 w-3.5 text-primary opacity-60" />
              <span className="text-xs font-medium text-primary opacity-70">Minimum Payment</span>
            </div>
            <span className="text-sm font-semibold text-primary">
              {formatCurrency(card.minimumPayment)}
            </span>
          </div>
        )}

        {nextDueDate && (
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-1.5">
              {dueDateStatus && <span>{dueDateStatus.icon}</span>}
              <Calendar className="h-3.5 w-3.5 text-primary opacity-60" />
              <span className="text-xs font-medium text-primary opacity-70">Next Due Date</span>
            </div>
            <div className="text-right">
              <p className={`text-sm font-semibold ${dueDateStatus?.color || 'text-primary'}`}>
                {nextDueDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
              </p>
              {daysUntilDue !== null && (
                <p className="text-xs text-primary opacity-60">
                  {daysUntilDue === 0 ? 'Today' : `${daysUntilDue} days`}
                </p>
              )}
            </div>
          </div>
        )}

        {card.statementDate && (
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-1.5">
              <TrendingUp className="h-3.5 w-3.5 text-primary opacity-60" />
              <span className="text-xs font-medium text-primary opacity-70">Last Statement</span>
            </div>
            <div className="text-right">
              <p className="text-sm font-semibold text-primary">
                {new Date(card.statementDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
              </p>
              {card.statementBalance !== undefined && (
                <p className="text-xs text-primary opacity-60">
                  {formatCurrency(Math.abs(card.statementBalance))}
                </p>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default CreditCardCard;

/**
 * RewardsHistoryChart Component
 * Visualizes rewards earning and redemption history over time
 */

import React from 'react';
import { TrendingUp, TrendingDown, Calendar } from 'lucide-react';
import type { RewardsHistory } from '../../types';
import { formatCurrency } from '../../utils/currency';

interface RewardsHistoryChartProps {
  history: RewardsHistory[];
  rewardsType: 'points' | 'miles' | 'cashback';
  className?: string;
}

export const RewardsHistoryChart: React.FC<RewardsHistoryChartProps> = ({
  history,
  rewardsType,
  className = '',
}) => {
  const [timeRange, setTimeRange] = React.useState<'30d' | '90d' | '1y' | 'all'>('90d');

  // Filter history based on time range
  const getFilteredHistory = () => {
    const now = new Date();
    const cutoffDate = new Date();

    switch (timeRange) {
      case '30d':
        cutoffDate.setDate(now.getDate() - 30);
        break;
      case '90d':
        cutoffDate.setDate(now.getDate() - 90);
        break;
      case '1y':
        cutoffDate.setFullYear(now.getFullYear() - 1);
        break;
      default:
        return history;
    }

    return history.filter(h => new Date(h.dateISO) >= cutoffDate);
  };

  const filteredHistory = getFilteredHistory();

  // Calculate summary stats
  const totalEarned = filteredHistory.reduce((sum, h) => sum + h.pointsEarned, 0);
  const totalRedeemed = filteredHistory.reduce((sum, h) => sum + h.pointsRedeemed, 0);
  const netChange = totalEarned - totalRedeemed;
  const currentBalance = filteredHistory.length > 0
    ? filteredHistory[filteredHistory.length - 1].balance
    : 0;

  const formatValue = (value: number) => {
    if (rewardsType === 'cashback') {
      return formatCurrency(value);
    }
    return value.toLocaleString();
  };

  const getRewardLabel = () => {
    switch (rewardsType) {
      case 'points':
        return 'Points';
      case 'miles':
        return 'Miles';
      case 'cashback':
        return 'Cash Back';
      default:
        return 'Rewards';
    }
  };

  if (filteredHistory.length === 0) {
    return (
      <div className={`rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 border-primary/20 p-8 ${className}`}>
        <div className="text-center">
          <Calendar className="h-12 w-12 text-primary opacity-30 mx-auto mb-3" />
          <h3 className="text-lg font-semibold text-primary mb-2">No History Yet</h3>
          <p className="text-sm text-primary opacity-70">
            Start earning rewards and they'll appear here!
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className={`rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 border-primary/20 p-5 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-lg font-semibold text-primary">Rewards History</h3>
        <div className="flex gap-2">
          {(['30d', '90d', '1y', 'all'] as const).map((range) => (
            <button
              key={range}
              onClick={() => setTimeRange(range)}
              className={`px-3 py-1 rounded-lg text-xs font-medium transition-all ${
                timeRange === range
                  ? 'bg-blue-500 text-white'
                  : 'bg-primary/20 text-primary hover:bg-primary/30'
              }`}
            >
              {range === 'all' ? 'All' : range.toUpperCase()}
            </button>
          ))}
        </div>
      </div>

      {/* Summary Stats */}
      <div className="grid grid-cols-3 gap-4 mb-6">
        <div className="rounded-xl bg-emerald-50 border border-emerald-200 p-4">
          <div className="flex items-center gap-2 mb-1">
            <TrendingUp className="h-4 w-4 text-emerald-600" />
            <p className="text-xs font-medium text-emerald-700">Earned</p>
          </div>
          <p className="text-xl font-bold text-emerald-600">
            {formatValue(totalEarned)}
          </p>
        </div>

        <div className="rounded-xl bg-rose-50 border border-rose-200 p-4">
          <div className="flex items-center gap-2 mb-1">
            <TrendingDown className="h-4 w-4 text-rose-600" />
            <p className="text-xs font-medium text-rose-700">Redeemed</p>
          </div>
          <p className="text-xl font-bold text-rose-600">
            {formatValue(totalRedeemed)}
          </p>
        </div>

        <div className="rounded-xl bg-blue-50 border border-blue-200 p-4">
          <div className="flex items-center gap-2 mb-1">
            <Calendar className="h-4 w-4 text-blue-600" />
            <p className="text-xs font-medium text-blue-700">Net Change</p>
          </div>
          <p className={`text-xl font-bold ${netChange >= 0 ? 'text-blue-600' : 'text-rose-600'}`}>
            {netChange >= 0 ? '+' : ''}{formatValue(netChange)}
          </p>
        </div>
      </div>

      {/* Timeline */}
      <div className="space-y-2">
        <h4 className="text-sm font-semibold text-primary mb-3">Recent Activity</h4>
        <div className="max-h-96 overflow-y-auto space-y-2">
          {filteredHistory.slice().reverse().map((entry) => (
            <div
              key={entry.id}
              className="rounded-lg bg-primary/10 border border-primary/20 p-3 hover:bg-primary/20 transition-colors"
            >
              <div className="flex items-start justify-between">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    {entry.pointsEarned > 0 ? (
                      <TrendingUp className="h-4 w-4 text-emerald-600" />
                    ) : (
                      <TrendingDown className="h-4 w-4 text-rose-600" />
                    )}
                    <p className="text-sm font-medium text-primary">
                      {entry.description || (entry.pointsEarned > 0 ? 'Earned' : 'Redeemed')}
                    </p>
                  </div>
                  <div className="flex items-center gap-3 text-xs text-primary opacity-60">
                    <span>{new Date(entry.dateISO).toLocaleDateString()}</span>
                    {entry.category && (
                      <>
                        <span>•</span>
                        <span className="capitalize">{entry.category}</span>
                      </>
                    )}
                  </div>
                </div>
                <div className="text-right ml-3">
                  <p className={`text-sm font-bold ${
                    entry.pointsEarned > 0 ? 'text-emerald-600' : 'text-rose-600'
                  }`}>
                    {entry.pointsEarned > 0 ? '+' : '-'}
                    {formatValue(entry.pointsEarned || entry.pointsRedeemed)}
                  </p>
                  <p className="text-xs text-primary opacity-60">
                    Balance: {formatValue(entry.balance)}
                  </p>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Current Balance Highlight */}
      <div className="mt-4 pt-4 border-t border-primary/20">
        <div className="flex items-center justify-between">
          <p className="text-sm font-medium text-primary opacity-70">Current Balance</p>
          <p className="text-2xl font-bold text-blue-600">
            {formatValue(currentBalance)} {getRewardLabel()}
          </p>
        </div>
      </div>
    </div>
  );
};

export default RewardsHistoryChart;

/**
 * RewardsSummaryCard Component
 * Compact summary card showing total rewards across all credit cards
 * Perfect for displaying on the main dashboard
 */

import React from 'react';
import { Award, ChevronRight } from 'lucide-react';
import type { Account } from '../../types';
import { formatCurrency } from '../../utils/currency';

interface RewardsSummaryCardProps {
  cards: Account[];
  onClick?: () => void;
  className?: string;
}

export const RewardsSummaryCard: React.FC<RewardsSummaryCardProps> = ({
  cards,
  onClick,
  className = '',
}) => {
  // Filter only cards with rewards
  const rewardsCards = cards.filter(card =>
    card.type === 'credit' && card.rewardsType && card.rewardsBalance !== undefined
  );

  if (rewardsCards.length === 0) {
    return null;
  }

  // Group and calculate totals by type
  const totals = rewardsCards.reduce((acc, card) => {
    const type = card.rewardsType!;
    const balance = card.rewardsBalance || 0;

    if (!acc[type]) {
      acc[type] = { total: 0, count: 0 };
    }

    acc[type].total += balance;
    acc[type].count += 1;

    return acc;
  }, {} as Record<string, { total: number; count: number }>);

  // Calculate estimated total value
  const estimatedValue = Object.entries(totals).reduce((sum, [type, { total }]) => {
    if (type === 'cashback') {
      return sum + total;
    } else if (type === 'points') {
      return sum + (total * 0.01);
    } else if (type === 'miles') {
      return sum + (total * 0.015);
    }
    return sum;
  }, 0);

  const getRewardIcon = (type: string) => {
    switch (type) {
      case 'points':
        return '🌟';
      case 'miles':
        return '✈️';
      case 'cashback':
        return '💰';
      default:
        return '🎁';
    }
  };

  const formatRewardValue = (type: string, value: number) => {
    if (type === 'cashback') {
      return formatCurrency(value);
    }
    return value.toLocaleString();
  };

  return (
    <div
      onClick={onClick}
      className={`rounded-2xl bg-gradient-to-br from-blue-500/20 to-purple-500/20 backdrop-blur-sm shadow-sm ring-1 border-blue-500/30 p-5 ${
        onClick ? 'cursor-pointer transition-all hover:shadow-md hover:scale-[1.02]' : ''
      } ${className}`}
    >
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <div className="rounded-lg bg-white/50 p-2">
            <Award className="h-5 w-5 text-blue-600" />
          </div>
          <div>
            <h3 className="text-sm font-medium text-primary opacity-70">Total Rewards</h3>
            <p className="text-xs text-primary opacity-60">{rewardsCards.length} cards</p>
          </div>
        </div>
        {onClick && <ChevronRight className="h-5 w-5 text-primary opacity-40" />}
      </div>

      {/* Estimated Value */}
      <div className="mb-4">
        <p className="text-xs text-primary opacity-70 mb-1">Estimated Value</p>
        <p className="text-3xl font-bold text-emerald-600">
          {formatCurrency(estimatedValue)}
        </p>
      </div>

      {/* Breakdown by Type */}
      <div className="space-y-2">
        {Object.entries(totals).map(([type, { total, count }]) => (
          <div
            key={type}
            className="flex items-center justify-between p-2 rounded-lg bg-white/30"
          >
            <div className="flex items-center gap-2">
              <span className="text-lg">{getRewardIcon(type)}</span>
              <div>
                <p className="text-xs font-medium text-primary capitalize">{type}</p>
                <p className="text-xs text-primary opacity-60">{count} {count === 1 ? 'card' : 'cards'}</p>
              </div>
            </div>
            <p className="text-sm font-bold text-primary">
              {formatRewardValue(type, total)}
            </p>
          </div>
        ))}
      </div>

      {/* Footer Tip */}
      <div className="mt-3 pt-3 border-t border-white/30">
        <p className="text-xs text-primary opacity-60">
          💡 Track and update your points anytime
        </p>
      </div>
    </div>
  );
};

export default RewardsSummaryCard;

/**
 * Financial Insights Card Component
 * Shows key financial metrics and calculations on the dashboard
 */

import React from 'react';
import {
  TrendingUp,
  Target,
  DollarSign,
  Shield,
  PiggyBank,
  Calculator,
  ChevronRight,
  AlertCircle,
  CheckCircle,
  Info,
} from 'lucide-react';
import type { Transaction, Account, Goal } from '../../types';
// Unused import removed
import {
  calculateSavingsRate,
  calculateNetWorth,
  calculateDebtToIncome,
  calculateEmergencyFund,
  calculateYearsToFI,
  calculate4PercentRule,
  calculateCreditUtilization,
} from '../../utils/calculations';
import { formatCurrency } from '../../utils/currency';

interface FinancialInsightsCardProps {
  transactions: Transaction[];
  accounts: Account[];
  goals: Goal[];
  onClick?: () => void;
  className?: string;
}

export const FinancialInsightsCard: React.FC<FinancialInsightsCardProps> = ({
  transactions,
  accounts,
  goals: _goals = [], // Use underscore to indicate unused variable
  onClick,
  className = '',
}) => {
  // Calculate time period for analysis (last 3 months)
  const threeMonthsAgo = new Date();
  threeMonthsAgo.setMonth(threeMonthsAgo.getMonth() - 3);

  const recentTransactions = transactions.filter(
    t => new Date(t.dateISO) >= threeMonthsAgo
  );

  // Calculate monthly income and expenses
  const monthlyIncome = recentTransactions
    .filter(t => t.amount > 0)
    .reduce((sum, t) => sum + t.amount, 0) / 3;

  const monthlyExpenses = Math.abs(
    recentTransactions
      .filter(t => t.amount < 0)
      .reduce((sum, t) => sum + t.amount, 0) / 3
  );

  // Core calculations
  const netWorth = calculateNetWorth(accounts);
  const savingsRate = calculateSavingsRate(monthlyIncome, monthlyExpenses);

  // Emergency fund calculation
  const emergencyAccounts = accounts.filter(
    a => a.accountType === 'savings' || a.accountType === 'checking'
  );
  const emergencyFundBalance = emergencyAccounts.reduce(
    (sum, a) => sum + a.currentBalance,
    0
  );
  const emergencyFund = calculateEmergencyFund(emergencyFundBalance, monthlyExpenses);

  // Debt calculations
  const monthlyDebtPayments = Math.abs(
    recentTransactions
      .filter((t): t is Transaction & { category: string } => {
        if (t.amount >= 0 || t.category == null) return false;
        const lowercaseCategory = t.category.toLowerCase();
        const debtTypes = ['loan', 'debt', 'mortgage'] as const;
        return debtTypes.some(type => lowercaseCategory.includes(type));
      })
      .reduce((sum: number, t: Transaction & { category: string }) => sum + t.amount, 0) / 3
  );

  const dti = calculateDebtToIncome(monthlyDebtPayments, monthlyIncome);
  const creditUtil = calculateCreditUtilization(accounts);

  // Financial independence calculations
  const annualExpenses = monthlyExpenses * 12;
  const yearsToFI = calculateYearsToFI(
    savingsRate.savingsRate,
    netWorth.netWorth,
    annualExpenses
  );

  // Retirement calculations
  const retirementRule = calculate4PercentRule(netWorth.netWorth);

  // Determine overall financial health score (0-100)
  let healthScore = 0;

  // Savings rate (0-30 points)
  healthScore += Math.min(30, savingsRate.savingsRate * 1.5);

  // Emergency fund (0-20 points)
  healthScore += Math.min(20, emergencyFund.monthsCovered * 3.33);

  // DTI (0-20 points)
  healthScore += Math.max(0, 20 - (dti.dti * 0.5));

  // Credit utilization (0-15 points)
  healthScore += Math.max(0, 15 - (creditUtil.utilizationRate * 0.3));

  // Net worth growth (0-15 points) - simplified
  healthScore += netWorth.netWorth > 0 ? 15 : 0;

  const getHealthColor = React.useCallback((score: number): string => {
    if (score >= 80) return 'text-green-600';
    if (score >= 60) return 'text-blue-600';
    if (score >= 40) return 'text-yellow-600';
    return 'text-red-600';
  }, []);

  const getHealthLabel = React.useCallback((score: number): string => {
