/**
 * CreditCardDetailsPage
 * Detailed view of a single credit card with benefits tracking
 */

import React, { useEffect, useState } from 'react';
import { ArrowLeft, Edit, Plus } from 'lucide-react';
import { getFinanceAPI } from '../data';
import type { Account, CardBenefit, CardCategoryBonus, WelcomeBonus, CardOffer } from '../types';
import { CreditCardCard } from '../components/creditCards/CreditCardCard';
import { CardBenefitsPanel } from '../components/creditCards/CardBenefitsPanel';
import { logger } from '../../services/logger';

interface CreditCardDetailsPageProps {
  accountId: string;
  onBack: () => void;
}

export const CreditCardDetailsPage: React.FC<CreditCardDetailsPageProps> = ({ accountId, onBack }) => {
  const [card, setCard] = useState<Account | null>(null);
  const [benefits, setBenefits] = useState<CardBenefit[]>([]);
  const [categoryBonuses, setCategoryBonuses] = useState<CardCategoryBonus[]>([]);
  const [welcomeBonuses, setWelcomeBonuses] = useState<WelcomeBonus[]>([]);
  const [offers, setOffers] = useState<CardOffer[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadData();
  }, [accountId]);

  const loadData = async () => {
    try {
      setLoading(true);

      const api = await getFinanceAPI();

      // Load card details
      const accounts = await api.listAccounts();
      const foundCard = accounts.find((a) => a.id === accountId);
      if (foundCard) {
        setCard(foundCard);
      }

      // Load benefits data
      const [benefitsData, bonusesData, welcomeData, offersData] = await Promise.all([
        api.listCardBenefits(accountId),
        api.listCategoryBonuses(accountId),
        api.listWelcomeBonuses(accountId),
        api.listCardOffers(accountId),
      ]);

      setBenefits(benefitsData);
      setCategoryBonuses(bonusesData);
      setWelcomeBonuses(welcomeData);
      setOffers(offersData);
    } catch (error) {
      logger.error('Failed to load card details:', { error });
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-primary opacity-70">Loading card details...</div>
      </div>
    );
  }

  if (!card) {
    return (
      <div className="text-center py-12">
        <p className="text-primary opacity-70">Card not found</p>
        <button
          onClick={onBack}
          className="mt-4 px-4 py-2 text-sm font-medium text-primary bg-primary/10 rounded-lg hover:bg-primary/20 transition-colors"
        >
          Go Back
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <button
          onClick={onBack}
          className="flex items-center gap-2 text-primary hover:text-primary/80 transition-colors"
        >
          <ArrowLeft className="h-5 w-5" />
          <span className="font-medium">Back to Credit Cards</span>
        </button>

        <button
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-white bg-primary rounded-lg hover:bg-primary/90 transition-colors"
        >
          <Edit className="h-4 w-4" />
          Edit Card
        </button>
      </div>

      {/* Card Overview */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1">
          <CreditCardCard card={card} />
        </div>

        <div className="lg:col-span-2">
          <div className="rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 ring-primary/20 p-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-semibold text-primary">Benefits & Rewards</h2>
              <button
                className="flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium text-primary bg-primary/10 rounded-lg hover:bg-primary/20 transition-colors"
              >
                <Plus className="h-4 w-4" />
                Add Benefit
              </button>
            </div>

            <CardBenefitsPanel
              accountId={accountId}
              benefits={benefits}
              categoryBonuses={categoryBonuses}
              welcomeBonuses={welcomeBonuses}
              offers={offers}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default CreditCardDetailsPage;

/**
 * GoalsPage - Financial Goals Management
 * Track savings goals and debt payoff with smart recommendations
 */

import React from 'react';
import { Plus } from 'lucide-react';
import {
  useGoalsQuery,
  useAccountsQuery,
  useGoalProgressQuery,
  useUpsertGoalMutation,
  useDeleteGoalMutation,
} from '../hooks/useFinanceQuery';
import type { Goal, GoalInput, Account } from '../types';
import GoalCard from '../components/goals/GoalCard';
import GoalEditor from '../components/goals/GoalEditor';

// Wrapper component to load progress for each goal
const GoalCardWithProgress: React.FC<{
  goal: Goal;
  accounts: Account[];
  onEdit: (goal: Goal) => void;
}> = ({ goal, accounts, onEdit }) => {
  const { data: progressHistory = [] } = useGoalProgressQuery(goal.id);
  const linkedAccount = goal.linkedAccountId
    ? accounts.find(a => a.id === goal.linkedAccountId)
    : undefined;

  return (
    <GoalCard
      goal={goal}
      progressHistory={progressHistory}
      linkedAccount={linkedAccount}
      onEdit={onEdit}
    />
  );
};

const GoalsPage: React.FC = () => {
  const [editorOpen, setEditorOpen] = React.useState(false);
  const [editingGoal, setEditingGoal] = React.useState<Goal | undefined>(undefined);

  // React Query hooks
  const { data: goals = [], isLoading: goalsLoading } = useGoalsQuery();
  const { data: accounts = [], isLoading: accountsLoading } = useAccountsQuery();
  const upsertGoalMutation = useUpsertGoalMutation();
  const deleteGoalMutation = useDeleteGoalMutation();

  const loading = goalsLoading || accountsLoading;

  const handleCreateGoal = (): void => {
    setEditingGoal(undefined);
    setEditorOpen(true);
  };

  const handleEditGoal = (goal: Goal): void => {
    setEditingGoal(goal);
    setEditorOpen(true);
  };

  const handleSaveGoal = async (goal: GoalInput): Promise<void> => {
    await upsertGoalMutation.mutateAsync(goal);
    setEditorOpen(false);
    setEditingGoal(undefined);
  };

  const handleDeleteGoal = async (goalId: string): Promise<void> => {
    await deleteGoalMutation.mutateAsync(goalId);
    setEditorOpen(false);
    setEditingGoal(undefined);
  };

  const handleCloseEditor = (): void => {
    setEditorOpen(false);
    setEditingGoal(undefined);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-center">
          <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-white border-r-transparent"></div>
          <p className="mt-2 text-sm text-primary">Loading goals...</p>
        </div>
      </div>
    );
  }

  // Sort goals by status and due date
  const sortedGoals = React.useMemo<Goal[]>(() => {
    return [...goals].sort((a, b) => {
      // First by completion (incomplete first)
      const aComplete = a.currentAmount >= a.targetAmount;
      const bComplete = b.currentAmount >= b.targetAmount;
      if (aComplete !== bComplete) return aComplete ? 1 : -1;

      // Then by due date (soonest first)
      return new Date(a.dueDateISO).getTime() - new Date(b.dueDateISO).getTime();
    });
  }, [goals]);

  return (
    <>
      {/* Header */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between mb-6">
        <div>
          <h2 className="text-2xl font-semibold text-primary">Financial Goals</h2>
          <p className="mt-1 text-sm text-primary opacity-70">
            Track your savings targets and debt payoff progress
          </p>
        </div>
        <button
          onClick={handleCreateGoal}
          className="inline-flex items-center gap-2 rounded-lg bg-blue-600 hover:bg-blue-700 px-4 py-2 text-sm font-semibold text-white shadow-lg transition-all hover:scale-105"
        >
          <Plus className="h-4 w-4" />
          <span>Create Goal</span>
        </button>
      </div>

      {/* Empty State */}
      {goals.length === 0 && (
        <div className="rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 ring-primary/20 p-12 text-center mb-6">
          <div className="mx-auto max-w-md">
            <h3 className="text-lg font-semibold text-primary mb-2">No Goals Yet</h3>
            <p className="text-sm text-primary opacity-70 mb-6">
              Set up your first financial goal to start tracking your progress with smart recommendations
              and automatic account syncing.
            </p>
            <button
              onClick={handleCreateGoal}
              className="inline-flex items-center gap-2 rounded-lg bg-blue-600 hover:bg-blue-700 px-5 py-3 text-sm font-semibold text-white shadow-lg transition-all hover:scale-105"
            >
              <Plus className="h-5 w-5" />
              <span>Create Your First Goal</span>
            </button>
          </div>
        </div>
      )}

      {/* Goal Cards */}
      {goals.length > 0 && (
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-2 mb-6">
          {sortedGoals.map((goal) => (
            <GoalCardWithProgress
              key={goal.id}
              goal={goal}
              accounts={accounts}
              onEdit={handleEditGoal}
            />
          ))}
        </div>
      )}

      {/* Goal Editor Modal */}
      <GoalEditor
        isOpen={editorOpen}
        onClose={handleCloseEditor}
        onSave={handleSaveGoal}
        onDelete={handleDeleteGoal}
        goal={editingGoal}
        accounts={accounts}
      />
    </>
  );
};

export default GoalsPage;

