            ? {
                ...policyInput,
                id: editingPolicy.id,
                createdAt: editingPolicy.createdAt,
                updatedAt: new Date().toISOString(),
              } as InsurancePolicy
            : p
        )
      );
    } else {
      // Add new policy
      const newPolicy: InsurancePolicy = {
        ...policyInput,
        id: `policy-${Date.now()}`,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };
      setPolicies(prev => [...prev, newPolicy]);
    }
    setShowForm(false);
    setEditingPolicy(undefined);
  };

  const handleCancelForm = (): void => {
    setShowForm(false);
    setEditingPolicy(undefined);
  };

  // Calculate summary metrics
  const activePolicies = policies.filter(p => p.status === 'active');
  const totalAnnualPremium = activePolicies.reduce((sum, policy) => {
    const annual = (() => {
      switch (policy.premiumFrequency) {
        case 'monthly': return policy.premiumAmount * 12;
        case 'quarterly': return policy.premiumAmount * 4;
        case 'semi-annual': return policy.premiumAmount * 2;
        default: return policy.premiumAmount;
      }
    })();
    return sum + annual;
  }, 0);

  const totalCoverage = activePolicies
    .filter(p => p.coverageAmount)
    .reduce((sum, p) => sum + (p.coverageAmount || 0), 0);

  // Get upcoming renewals (next 60 days)
  const upcomingRenewals = activePolicies
    .filter(p => {
      if (!p.renewalDate) return false;
      const daysUntil = Math.ceil(
        (new Date(p.renewalDate).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24)
      );
      return daysUntil > 0 && daysUntil <= 60;
    })
    .sort((a, b) => {
      const aRenewalDate = a.renewalDate ? new Date(a.renewalDate).getTime() : Infinity;
      const bRenewalDate = b.renewalDate ? new Date(b.renewalDate).getTime() : Infinity;
      return aRenewalDate - bRenewalDate;
    })
    .slice(0, 3);

  // Get policies requiring attention
  const policiesNeedingAttention = policies.filter(p => {
    if (p.status === 'expired') return true;
    if (p.status === 'pending') return true;
    if (!p.renewalDate) return false;
    const daysUntil = Math.ceil(
      (new Date(p.renewalDate).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24)
    );
    return daysUntil <= 30 && daysUntil > 0;
  });

  // Group policies by type
  const policiesByType = activePolicies.reduce((acc, policy) => {
    if (!acc[policy.type]) {
      acc[policy.type] = [];
    }
    acc[policy.type].push(policy);
    return acc;
  }, {} as Record<string, InsurancePolicy[]>);

  // Filter policies
  const filteredPolicies = filterType === 'all'
    ? policies
    : policies.filter(p => p.type === filterType);

  const policyTypes = [
    { value: 'all', label: 'All Policies', icon: Shield },
    { value: 'health', label: 'Health', icon: Shield },
    { value: 'auto', label: 'Auto', icon: Shield },
    { value: 'home', label: 'Home', icon: Shield },
    { value: 'life', label: 'Life', icon: Shield },
    { value: 'disability', label: 'Disability', icon: Shield },
    { value: 'umbrella', label: 'Umbrella', icon: Shield },
    { value: 'pet', label: 'Pet', icon: Shield },
    { value: 'travel', label: 'Travel', icon: Shield },
  ];

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <div className="h-8 w-8 animate-spin rounded-full border-4 border-blue-500 border-t-transparent mx-auto mb-2" />
          <p className="text-sm text-primary opacity-60">Loading insurance policies...</p>
        </div>
      </div>
    );
  }

  if (policies.length === 0) {
    return (
      <>
        <div className="flex items-center justify-center min-h-[400px]">
          <div className="text-center max-w-md">
            <Shield className="h-16 w-16 text-primary opacity-40 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-primary mb-2">No Insurance Policies Yet</h3>
            <p className="text-sm text-primary opacity-70 mb-6">
              Track all your insurance policies in one place. Monitor premiums, coverage, renewals, and claims.
            </p>
            <button
              onClick={handleAddPolicy}
              className="px-4 py-2 rounded-lg bg-blue-500 text-white font-medium hover:bg-blue-600 transition-colors inline-flex items-center gap-2"
            >
              <Plus className="h-4 w-4" />
              Add Insurance Policy
            </button>
          </div>
        </div>

        {/* Form Modal */}
        {showForm && (
          <InsurancePolicyForm
            policy={editingPolicy}
            onSave={handleSavePolicy}
            onCancel={handleCancelForm}
          />
        )}
      </>
    );
  }

  return (
    <div className="space-y-6">
      {/* Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {/* Active Policies */}
        <div className="rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 border-emerald-500/30 p-4">
          <div className="flex items-center gap-2 mb-2">
            <div className="rounded-lg bg-emerald-500/10 p-2">
              <Shield className="h-4 w-4 text-emerald-600" />
            </div>
            <h3 className="text-sm font-medium text-primary opacity-70">Active Policies</h3>
          </div>
          <p className="text-2xl font-bold text-primary">{activePolicies.length}</p>
          <p className="text-xs text-primary opacity-60 mt-1">
            {Object.keys(policiesByType).length} types
          </p>
        </div>

        {/* Total Annual Premium */}
        <div className="rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 border-blue-500/30 p-4">
          <div className="flex items-center gap-2 mb-2">
            <div className="rounded-lg bg-blue-500/10 p-2">
              <DollarSign className="h-4 w-4 text-blue-600" />
            </div>
            <h3 className="text-sm font-medium text-primary opacity-70">Annual Premium</h3>
          </div>
          <p className="text-2xl font-bold text-primary">{formatCurrency(totalAnnualPremium)}</p>
          <p className="text-xs text-primary opacity-60 mt-1">
            {formatCurrency(totalAnnualPremium / 12)}/mo avg
          </p>
        </div>

        {/* Total Coverage */}
        <div className="rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 border-purple-500/30 p-4">
          <div className="flex items-center gap-2 mb-2">
            <div className="rounded-lg bg-purple-500/10 p-2">
              <TrendingUp className="h-4 w-4 text-purple-600" />
            </div>
            <h3 className="text-sm font-medium text-primary opacity-70">Total Coverage</h3>
          </div>
          <p className="text-2xl font-bold text-primary">{formatCurrency(totalCoverage)}</p>
          <p className="text-xs text-primary opacity-60 mt-1">Combined protection</p>
        </div>

        {/* Needs Attention */}
        <div className={`rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 ${
          policiesNeedingAttention.length > 0 ? 'border-amber-500/30' : 'border-primary/20'
        } p-4`}>
          <div className="flex items-center gap-2 mb-2">
            <div className={`rounded-lg ${
              policiesNeedingAttention.length > 0 ? 'bg-amber-500/10' : 'bg-primary/10'
            } p-2`}>
              <AlertTriangle className={`h-4 w-4 ${
                policiesNeedingAttention.length > 0 ? 'text-amber-600' : 'text-primary opacity-60'
              }`} />
            </div>
            <h3 className="text-sm font-medium text-primary opacity-70">Needs Attention</h3>
          </div>
          <p className="text-2xl font-bold text-primary">{policiesNeedingAttention.length}</p>
          <p className="text-xs text-primary opacity-60 mt-1">
            {policiesNeedingAttention.length === 0 ? 'All up to date' : 'policies require action'}
          </p>
        </div>
      </div>

      {/* Upcoming Renewals */}
      {upcomingRenewals.length > 0 && (
        <div className="rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 border-primary/20 p-5">
          <div className="flex items-center gap-2 mb-4">
            <Calendar className="h-5 w-5 text-blue-600" />
            <h3 className="text-lg font-semibold text-primary">Upcoming Renewals</h3>
          </div>
          <div className="space-y-3">
            {upcomingRenewals.map(policy => {
              const renewalDate = policy.renewalDate ? new Date(policy.renewalDate) : null;
              const daysUntil = renewalDate
                ? Math.ceil(
                    (renewalDate.getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24)
                  )
                : 0;
              const isUrgent = daysUntil <= 14;

              return (
                <div
                  key={policy.id}
                  className={`flex items-center justify-between p-3 rounded-lg border ${
                    isUrgent
                      ? 'bg-amber-50 border-amber-200'
                      : 'bg-blue-50 border-blue-200'
                  }`}
                >
                  <div className="flex-1">
                    <p className="text-sm font-medium text-primary">{policy.policyName}</p>
                    <p className="text-xs text-primary opacity-60 mt-0.5 capitalize">
                      {policy.type} • {policy.provider}
                    </p>
                  </div>
                  <div className="text-right">
                    {renewalDate && (
                      <>
                        <p className={`text-sm font-semibold ${
                          isUrgent ? 'text-amber-700' : 'text-blue-700'
                        }`}>
                          {renewalDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                        </p>
                        <p className="text-xs text-primary opacity-60">
                          {daysUntil} {daysUntil === 1 ? 'day' : 'days'}
                        </p>
                      </>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Filter Tabs */}
      <div className="flex items-center gap-2 overflow-x-auto pb-2">
        {policyTypes.map(type => {
          const count = type.value === 'all'
            ? policies.length
            : policies.filter(p => p.type === type.value).length;

          if (count === 0 && type.value !== 'all') return null;

          return (
            <button
              key={type.value}
              onClick={() => setFilterType(type.value)}
              className={`px-4 py-2 rounded-lg font-medium whitespace-nowrap transition-all ${
                filterType === type.value
                  ? 'bg-blue-500 text-white'
                  : 'bg-primary/20 text-primary hover:bg-primary/30'
              }`}
            >
              {type.label} {count > 0 && `(${count})`}
            </button>
          );
        })}
      </div>

      {/* Policies Grid */}
      <div>
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold text-primary">Your Policies</h3>
          <button
            onClick={handleAddPolicy}
            className="px-3 py-1.5 rounded-lg bg-blue-500 text-white text-sm font-medium hover:bg-blue-600 transition-colors inline-flex items-center gap-1.5"
          >
            <Plus className="h-4 w-4" />
            Add Policy
          </button>
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-4">
          {filteredPolicies.map(policy => (
            <InsuranceCard
              key={policy.id}
              policy={policy}
              onClick={() => handleEditPolicy(policy)}
            />
          ))}
        </div>
      </div>

      {/* Form Modal */}
      {showForm && (
        <InsurancePolicyForm
          policy={editingPolicy}
          onSave={handleSavePolicy}
          onCancel={handleCancelForm}
        />
      )}
    </div>
  );
};

export default InsurancePage;

/**
 * NetWorthPage - Enhanced with account breakdown, growth metrics, and insights
 * Matches Monarch Money / Empower design patterns
 */

import React from 'react';
import { TrendingUp, TrendingDown, DollarSign, PieChart, BarChart3 } from 'lucide-react';
import { Card } from '../components/Card';
import { ChartLazy } from '../components/ChartLazy';
import { formatCurrency } from '../utils/currency';
import { useNetWorthQuery, useAccountsQuery } from '../hooks/useFinanceQuery';
import type { Account } from '../types';

const NetWorthPage: React.FC = () => {
  // React Query hooks
  const { data: netWorthData = [], isLoading: netWorthLoading } = useNetWorthQuery();
  const { data: accounts = [], isLoading: accountsLoading } = useAccountsQuery();

  const loading = netWorthLoading || accountsLoading;

  // Transform data to include net worth calculation
  const data = React.useMemo(() => {
    return netWorthData.map((p) => ({ ...p, net: p.assets - p.liabilities }));
  }, [netWorthData]);

  // Calculate current metrics
  const last = data[data.length - 1];
  const prev = data.length > 1 ? data[data.length - 2] : undefined;
  const yearAgo = data.length > 12 ? data[data.length - 13] : undefined;

  // Growth calculations
  const monthDelta = last && prev ? last.net - prev.net : 0;
  const monthPercent = prev && prev.net !== 0 ? ((last.net - prev.net) / Math.abs(prev.net)) * 100 : 0;
  const yearDelta = last && yearAgo ? last.net - yearAgo.net : 0;
  const yearPercent = yearAgo && yearAgo.net !== 0 ? ((last.net - yearAgo.net) / Math.abs(yearAgo.net)) * 100 : 0;

  // Account breakdown
  const assetAccounts = accounts.filter(a => !a.liability);
  const liabilityAccounts = accounts.filter(a => a.liability);
  const totalAssets = assetAccounts.reduce((sum, a) => sum + a.balance, 0);
  const totalLiabilities = liabilityAccounts.reduce((sum, a) => sum + Math.abs(a.balance), 0);
  const currentNet = totalAssets - totalLiabilities;

  // Group accounts by type
  const groupByType = (accts: Account[]) => {
    const groups: Record<string, Account[]> = {};
    accts.forEach(a => {
      if (!groups[a.type]) groups[a.type] = [];
      groups[a.type].push(a);
    });
    return groups;
  };

  const assetGroups = groupByType(assetAccounts);
  const liabilityGroups = groupByType(liabilityAccounts);

  // Account type display names
  const typeNames: Record<string, string> = {
    checking: 'Checking',
    savings: 'Savings',
    credit: 'Credit Cards',
    brokerage: 'Brokerage',
    loan: 'Loans',
    investment: 'Investments',
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <div className="h-8 w-8 animate-spin rounded-full border-4 border-blue-500 border-t-transparent mx-auto mb-2" />
          <p className="text-sm text-primary opacity-60">Loading net worth data...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Enhanced Metric Cards */}
      {last && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {/* Assets Card */}
          <div className="rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 border-emerald-500/30 p-4">
            <div className="flex items-start justify-between mb-2">
              <div className="flex items-center gap-2">
                <div className="rounded-lg bg-emerald-500/10 p-2">
                  <TrendingUp className="h-4 w-4 text-emerald-600" />
                </div>
                <h3 className="text-sm font-medium text-primary opacity-70">Total Assets</h3>
              </div>
            </div>
            <div className="space-y-1">
              <p className="text-2xl font-bold text-primary">{formatCurrency(totalAssets)}</p>
              <p className="text-xs text-primary opacity-60">{assetAccounts.length} accounts</p>
            </div>
          </div>

          {/* Liabilities Card */}
          <div className="rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 border-rose-500/30 p-4">
            <div className="flex items-start justify-between mb-2">
              <div className="flex items-center gap-2">
                <div className="rounded-lg bg-rose-500/10 p-2">
                  <TrendingDown className="h-4 w-4 text-rose-600" />
                </div>
                <h3 className="text-sm font-medium text-primary opacity-70">Total Liabilities</h3>
              </div>
            </div>
            <div className="space-y-1">
              <p className="text-2xl font-bold text-primary">{formatCurrency(totalLiabilities)}</p>
              <p className="text-xs text-primary opacity-60">{liabilityAccounts.length} accounts</p>
            </div>
          </div>

          {/* Net Worth Card */}
          <div className={`rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 ${currentNet >= 0 ? 'border-blue-500/30' : 'border-amber-500/30'} p-4`}>
            <div className="flex items-start justify-between mb-2">
              <div className="flex items-center gap-2">
                <div className={`rounded-lg ${currentNet >= 0 ? 'bg-blue-500/10' : 'bg-amber-500/10'} p-2`}>
                  <DollarSign className={`h-4 w-4 ${currentNet >= 0 ? 'text-blue-600' : 'text-amber-600'}`} />
                </div>
                <h3 className="text-sm font-medium text-primary opacity-70">Net Worth</h3>
              </div>
            </div>
            <div className="space-y-1">
              <p className="text-2xl font-bold text-primary">{formatCurrency(currentNet)}</p>
              {prev && (
                <div className="flex items-center gap-2 text-xs">
                  <span className={monthDelta >= 0 ? 'text-emerald-600' : 'text-rose-600'}>
                    {monthDelta >= 0 ? '+' : ''}{formatCurrency(monthDelta)}
                  </span>
                  <span className="text-primary opacity-60">
                    ({monthDelta >= 0 ? '+' : ''}{monthPercent.toFixed(1)}% MoM)
                  </span>
                </div>
              )}
              {yearAgo && (
                <div className="flex items-center gap-2 text-xs">
                  <span className={yearDelta >= 0 ? 'text-emerald-600' : 'text-rose-600'}>
                    {yearDelta >= 0 ? '+' : ''}{formatCurrency(yearDelta)}
                  </span>
                  <span className="text-primary opacity-60">
                    ({yearDelta >= 0 ? '+' : ''}{yearPercent.toFixed(1)}% YoY)
                  </span>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Main Chart */}
      {data.length > 0 && (
        <Card title="Net Worth Over Time">
          <ChartLazy
            data={data}
            xKey="month"
            yKeys={[
              { key: 'assets', color: '#10b981', type: 'area' },
              { key: 'liabilities', color: '#ef4444', type: 'area' },
              { key: 'net', color: '#3b82f6', type: 'line' }
            ]}
          />
        </Card>
      )}

      {/* Account Breakdown */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Assets Breakdown */}
        <div className="rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 border-emerald-500/30 p-5">
          <div className="flex items-center gap-2 mb-4">
            <BarChart3 className="h-5 w-5 text-emerald-600" />
            <h3 className="text-lg font-semibold text-primary">Assets Breakdown</h3>
          </div>
          <div className="space-y-4">
            {Object.entries(assetGroups).map(([type, accts]) => {
              const typeTotal = accts.reduce((sum, a) => sum + a.balance, 0);
              const percentage = totalAssets > 0 ? (typeTotal / totalAssets) * 100 : 0;
              return (
                <div key={type}>
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-medium text-primary">{typeNames[type] || type}</span>
                    <span className="text-sm font-semibold text-primary">{formatCurrency(typeTotal)}</span>
                  </div>
                  <div className="mb-2 h-2 w-full rounded-full bg-primary/20">
                    <div
                      className="h-2 rounded-full bg-emerald-500"
                      style={{ width: `${percentage}%` }}
                    />
                  </div>
                  <div className="space-y-1.5 ml-3">
                    {accts.map(a => (
                      <div key={a.id} className="flex items-center justify-between text-xs text-primary opacity-70">
                        <span>{a.name}</span>
                        <span>{formatCurrency(a.balance)}</span>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
            {assetAccounts.length === 0 && (
              <p className="text-sm text-primary opacity-60 text-center py-4">No asset accounts yet</p>
            )}
          </div>
        </div>

        {/* Liabilities Breakdown */}
        <div className="rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 border-rose-500/30 p-5">
          <div className="flex items-center gap-2 mb-4">
            <PieChart className="h-5 w-5 text-rose-600" />
            <h3 className="text-lg font-semibold text-primary">Liabilities Breakdown</h3>
          </div>
          <div className="space-y-4">
            {Object.entries(liabilityGroups).map(([type, accts]) => {
              const typeTotal = accts.reduce((sum, a) => sum + Math.abs(a.balance), 0);
              const percentage = totalLiabilities > 0 ? (typeTotal / totalLiabilities) * 100 : 0;
              return (
                <div key={type}>
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-medium text-primary">{typeNames[type] || type}</span>
                    <span className="text-sm font-semibold text-primary">{formatCurrency(typeTotal)}</span>
                  </div>
                  <div className="mb-2 h-2 w-full rounded-full bg-primary/20">
                    <div
                      className="h-2 rounded-full bg-rose-500"
                      style={{ width: `${percentage}%` }}
                    />
                  </div>
                  <div className="space-y-1.5 ml-3">
                    {accts.map(a => (
                      <div key={a.id} className="flex items-center justify-between text-xs text-primary opacity-70">
                        <span>{a.name}</span>
                        <span>{formatCurrency(Math.abs(a.balance))}</span>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
            {liabilityAccounts.length === 0 && (
              <p className="text-sm text-primary opacity-60 text-center py-4">No liabilities - great job! 🎉</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default NetWorthPage;

/**
 * ProjectionsPage - Financial projections and future planning
 * Shows net worth growth, goal timelines, and retirement projections
 */

import React, { lazy, Suspense } from 'react';
import {
  TrendingUp,
  Target,
  Calendar,
  _DollarSign,
  PiggyBank,
  Zap,
  Settings,
} from 'lucide-react';
import type { Account, Transaction, Goal } from '../types';
import { getFinanceAPI } from '../data';
import {
  calculateNetWorth,
  calculateSavingsRate,
  projectNetWorth,
  calculateYearsToFI,
  calculate4PercentRule,
  calculateRequiredSavings,
  calculateCompoundInterest,
} from '../utils/calculations';
import { formatCurrency } from '../utils/currency';

// Lazy load chart components to defer loading Recharts
const NetWorthChart = lazy(() => import('../components/ProjectionCharts').then(module => ({ default: module.NetWorthChart })));
const CompoundInterestChart = lazy(() => import('../components/ProjectionCharts').then(module => ({ default: module.CompoundInterestChart })));

const ProjectionsPage: React.FC = () => {
  const [loading, setLoading] = React.useState(true);
  const [accounts, setAccounts] = React.useState<Account[]>([]);
  const [transactions, setTransactions] = React.useState<Transaction[]>([]);
  const [goals, setGoals] = React.useState<Goal[]>([]);

  // Projection settings
  const [projectionYears, setProjectionYears] = React.useState(10);
  const [annualReturnRate, setAnnualReturnRate] = React.useState(7);
  const [inflationRate, setInflationRate] = React.useState(3);

  React.useEffect(() => {
    let mounted = true;
    (async () => {
      setLoading(true);
      const api = await getFinanceAPI();

      const [accts, { items: txns }, gls] = await Promise.all([
        api.listAccounts(),
        api.listTransactions({ limit: 1000 }),
        api.listGoals(),
      ]);

      if (!mounted) return;
      setAccounts(accts);
      setTransactions(txns);
      setGoals(gls);
      setLoading(false);
    })();

    return () => {
      mounted = false;
    };
  }, []);

  // Calculate current metrics
  const threeMonthsAgo = new Date();
  threeMonthsAgo.setMonth(threeMonthsAgo.getMonth() - 3);

  const recentTransactions = transactions.filter(
    t => new Date(t.dateISO) >= threeMonthsAgo
  );

  const monthlyIncome = recentTransactions
    .filter(t => t.amount > 0)
    .reduce((sum, t) => sum + t.amount, 0) / 3;

  const monthlyExpenses = Math.abs(
    recentTransactions
      .filter(t => t.amount < 0)
      .reduce((sum, t) => sum + t.amount, 0) / 3
  );

  const netWorth = calculateNetWorth(accounts);
  const savingsRate = calculateSavingsRate(monthlyIncome, monthlyExpenses);
  const yearsToFI = calculateYearsToFI(
    savingsRate.savingsRate,
    netWorth.netWorth,
    monthlyExpenses * 12
  );

  // Generate net worth projections
  const netWorthProjections = projectNetWorth(
    netWorth.netWorth,
    savingsRate.monthlySavings,
    annualReturnRate,
    projectionYears
  );

  // Prepare chart data
  const netWorthChartData = [
    {
      year: 'Today',
      value: netWorth.netWorth,
      optimistic: netWorth.netWorth,
      pessimistic: netWorth.netWorth,
    },
    ...netWorthProjections.map(p => ({
      year: `Year ${p.year}`,
      value: p.baseCase,
      optimistic: p.optimistic,
      pessimistic: p.pessimistic,
      contributions: p.contributions,
    })),
  ];

  // Calculate goal projections
  const goalProjections = goals.map(goal => {
    const currentProgress = goal.currentAmount || 0;
    const targetAmount = goal.targetAmount;
    const remaining = targetAmount - currentProgress;

    if (remaining <= 0) {
      return {
        ...goal,
        yearsToGoal: 0,
        onTrack: true,
        monthlyRequired: 0,
      };
    }

    // Calculate years to reach goal with current savings rate
    const targetDate = goal.targetDate ? new Date(goal.targetDate) : null;
    const yearsUntilTarget = targetDate
      ? (targetDate.getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24 * 365)
      : 10; // Default to 10 years if no target date

    const requiredSavings = calculateRequiredSavings(
      targetAmount,
      currentProgress,
      Math.max(1, yearsUntilTarget),
      annualReturnRate
    );

    const yearsAtCurrentRate =
      savingsRate.monthlySavings > 0
        ? remaining / (savingsRate.monthlySavings * 12)
        : Infinity;

    return {
      ...goal,
      yearsToGoal: yearsAtCurrentRate,
      onTrack: yearsAtCurrentRate <= yearsUntilTarget,
      monthlyRequired: requiredSavings.requiredMonthlySavings,
      yearsUntilTarget,
    };
  });

  // Retirement projections
  const retirementRule = calculate4PercentRule(netWorth.netWorth);
  const targetRetirementAmount = (monthlyExpenses * 12) / 0.04;
  const retirementGap = targetRetirementAmount - netWorth.netWorth;

  // Generate compound interest data for visualization
  const investmentGrowthData = calculateCompoundInterest(
    netWorth.netWorth > 0 ? netWorth.netWorth : 10000,
    savingsRate.monthlySavings > 0 ? savingsRate.monthlySavings : 500,
    annualReturnRate,
    30
  );

  const compoundInterestChartData = investmentGrowthData.yearByYear.map(y => ({
    year: `Year ${y.year}`,
    totalValue: y.balance,
    contributions: y.contributions,
    gains: y.gains,
  }));

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <div className="h-8 w-8 animate-spin rounded-full border-4 border-blue-500 border-t-transparent mx-auto mb-2" />
          <p className="text-sm text-primary opacity-60">Loading projections...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h2 className="text-2xl font-bold text-primary mb-2">Financial Projections</h2>
        <p className="text-sm text-primary opacity-70">
          Visualize your financial future based on current trajectory and assumptions
        </p>
      </div>

      {/* Settings Panel */}
      <div className="rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 border-primary/20 p-5">
        <div className="flex items-center gap-2 mb-4">
          <Settings className="h-5 w-5 text-blue-600" />
          <h3 className="text-lg font-semibold text-primary">Projection Settings</h3>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <label className="block text-sm font-medium text-primary opacity-70 mb-2">
              Projection Years
            </label>
            <select
              value={projectionYears}
              onChange={e => setProjectionYears(Number(e.target.value))}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
            >
              <option value={5}>5 Years</option>
              <option value={10}>10 Years</option>
              <option value={20}>20 Years</option>
              <option value={30}>30 Years</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-primary opacity-70 mb-2">
              Expected Return Rate
            </label>
            <select
              value={annualReturnRate}
              onChange={e => setAnnualReturnRate(Number(e.target.value))}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
            >
              <option value={5}>5% (Conservative)</option>
              <option value={7}>7% (Moderate)</option>
              <option value={9}>9% (Aggressive)</option>
              <option value={10}>10% (Very Aggressive)</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-primary opacity-70 mb-2">
              Inflation Rate
            </label>
            <select
              value={inflationRate}
              onChange={e => setInflationRate(Number(e.target.value))}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
            >
              <option value={2}>2%</option>
              <option value={3}>3%</option>
              <option value={4}>4%</option>
            </select>
          </div>
        </div>
      </div>

      {/* Net Worth Projection Chart */}
      <div className="rounded-2xl bg-primary/30 backdrop-blur-sm shadow-sm ring-1 border-primary/20 p-5">
        <div className="flex items-center gap-2 mb-4">
          <TrendingUp className="h-5 w-5 text-emerald-600" />
