/**
 * Project net worth growth over time
 */
export function projectNetWorth(
  currentNetWorth: number,
  monthlySavings: number,
  annualReturnRate: number,
  years: number
): Array<{
  year: number;
  optimistic: number;
  baseCase: number;
  pessimistic: number;
  contributions: number;
}> {
  const projections = [];
  const optimisticRate = annualReturnRate + 3; // +3% optimistic
  const pessimisticRate = Math.max(0, annualReturnRate - 3); // -3% pessimistic

  for (let year = 1; year <= years; year++) {
    const months = year * 12;
    const monthlyRate = annualReturnRate / 12 / 100;
    const optimisticMonthlyRate = optimisticRate / 12 / 100;
    const pessimisticMonthlyRate = pessimisticRate / 12 / 100;

    // Calculate future value for each scenario
    const calculateFV = (rate: number): number => {
      let balance = currentNetWorth;
      for (let m = 0; m < months; m++) {
        balance = balance * (1 + rate) + monthlySavings;
      }
      return balance;
    };

    projections.push({
      year,
      optimistic: calculateFV(optimisticMonthlyRate),
      baseCase: calculateFV(monthlyRate),
      pessimistic: calculateFV(pessimisticMonthlyRate),
      contributions: currentNetWorth + (monthlySavings * months),
    });
  }

  return projections;
}

/**
 * Card Benefits Helper
 * Utilities for automatically populating benefits from templates
 */

import type { FinanceAPI } from '../data/api';
import { findCardTemplate, CREDIT_CARD_TEMPLATES } from './creditCardTemplates';
import type { CardBenefitInput, CardCategoryBonusInput, WelcomeBonusInput, CreditCardTemplate } from '../types';
import type { Benefit, CategoryBonus } from './creditCardTemplates';onusInput } from '../types';
import { logger } from '../../services/logger';

/**
 * Automatically populate benefits for a credit card based on its name
 * Returns the number of benefits added
 */
export async function populateBenefitsFromTemplate(
  api: FinanceAPI,
  accountId: string,
  cardName: string
): Promise<{ benefitsAdded: number; bonusesAdded: number; welcomeBonusAdded: boolean }> {
  const template = findCardTemplate(cardName);

  if (!template) {
    return { benefitsAdded: 0, bonusesAdded: 0, welcomeBonusAdded: false };
  }

  let benefitsAdded = 0;
  let bonusesAdded = 0;
  let welcomeBonusAdded = false;

  try {
    // Add benefits
    if (template.benefits && template.benefits.length > 0) {
      for (const benefit of template.benefits) {
        const benefitInput: CardBenefitInput = {
          name: benefit.name,
          description: benefit.description,
          value: benefit.value,
          frequency: benefit.frequency
        };
        await api.upsertCardBenefit(accountId, benefitInput);
        benefitsAdded++;
      }
    }

    // Add category bonuses
    if (template.categoryBonuses && template.categoryBonuses.length > 0) {
      for (const bonus of template.categoryBonuses) {
        const bonusInput: CardCategoryBonusInput = {
          category: bonus.category,
          rewardsRate: bonus.rewardsRate
        };
        await api.upsertCategoryBonus(accountId, bonusInput);
        bonusesAdded++;
      }
    }

    // Add welcome bonus
    if (template.welcomeBonus) {
      const welcomeBonusInput: WelcomeBonusInput = {
        bonusAmount: template.welcomeBonus.bonusAmount,
        minimumSpend: template.welcomeBonus.minimumSpend,
        expirationMonths: template.welcomeBonus.expirationMonths
      };
      await api.upsertWelcomeBonus(accountId, welcomeBonusInput);
      welcomeBonusAdded = true;
    }

    return { benefitsAdded, bonusesAdded, welcomeBonusAdded };
  } catch (error) {
    logger.error('Failed to populate benefits from template:', { error });
    throw error;
  }
}

/**
 * Get a list of all available card templates for selection
 */
export function getAvailableCardTemplates(): Array<{
  id: string;
  name: string;
  issuer: string;
  annualFee: number;
  rewardsType: string;
  baseRewardsRate: number;
  benefitsCount: number;
  bonusesCount: number;
  hasWelcomeBonus: boolean;
}> {
  return CREDIT_CARD_TEMPLATES.map((template) => ({
    id: template.id,
    name: template.name,
    issuer: template.issuer,
    annualFee: template.annualFee,
    rewardsType: template.rewardsType,
    baseRewardsRate: template.baseRewardsRate,
    benefitsCount: template.benefits.length,
    bonusesCount: template.categoryBonuses.length,
    hasWelcomeBonus: !!template.welcomeBonus,
  }));
}

/**
 * Get template by ID
 */
export function getTemplateById(id: string): CreditCardTemplate | undefined {
  return CREDIT_CARD_TEMPLATES.find((t) => t.id === id);
}

/**
 * Suggest card templates based on partial name match
 */
export function suggestCardTemplates(partialName: string, limit = 5): CreditCardTemplate[] {
  const normalized = partialName.toLowerCase().trim();

  if (!normalized) {
    return CREDIT_CARD_TEMPLATES.slice(0, limit);
  }

  const matches = CREDIT_CARD_TEMPLATES.filter((template) => {
    const templateName = template.name.toLowerCase();
    const issuerName = template.issuer.replace('_', ' ');
    return templateName.includes(normalized) || issuerName.includes(normalized);
  });

  return matches.slice(0, limit);
}

/**
 * Calculate total annual value of benefits for a template
 */
export function calculateAnnualBenefitValue(templateId: string): number {
  const template = getTemplateById(templateId);
  if (!template) return 0;

  let total = 0;

  template.benefits.forEach((benefit: Benefit) => {
    if (benefit.value) {
      // Convert to annual value based on frequency
      switch (benefit.frequency) {
        case 'monthly':
          total += benefit.value; // Value is already annual (e.g., $15/mo = $180 stored)
          break;
        case 'quarterly':
          total += benefit.value; // Value is already annual
          break;
        case 'annual':
          total += benefit.value;
          break;
        case 'once':
          // One-time benefits don't count toward annual value
          break;
        default:
          break;
      }
    }
  });

  // Add welcome bonus value (estimated at 1 cent per point/mile)
  if (template.welcomeBonus) {
    total += template.welcomeBonus.bonusAmount * 0.01;
  }

  return total;
}

/**
 * Get net annual value after fee
 */
export function getNetAnnualValue(templateId: string): number {
  const template = getTemplateById(templateId);
  if (!template) return 0;

  const benefitValue = calculateAnnualBenefitValue(templateId);
  return benefitValue - template.annualFee;
}

/**
 * Recommend best cards for a user based on spending categories
 */
export function recommendCardsForCategories(
  categories: string[]
): Array<{
  template: CreditCardTemplate;
  score: number;
  reason: string
}> {
  const recommendations = CREDIT_CARD_TEMPLATES.map((template) => {
    let score = 0;
    const reasons: string[] = [];

    // Check category bonuses
    categories.forEach((category) => {
      const bonus = template.categoryBonuses.find((b: CategoryBonus) => b.category === category);
      if (bonus) {
        score += bonus.rewardsRate * 10; // Weight by earning rate
        reasons.push(`${bonus.rewardsRate}x on ${category}`);
      }
    });

    // Add base rewards
    score += template.baseRewardsRate;

    // Factor in annual fee (negative impact)
    score -= template.annualFee / 100;

    // Factor in benefits value
    const benefitValue = calculateAnnualBenefitValue(template.id);
    score += benefitValue / 100;

    return {
      template,
      score,
      reason: reasons.length > 0 ? reasons.join(', ') : `${template.baseRewardsRate}x on all purchases`,
    };
  });

  return recommendations.sort((a, b) => b.score - a.score);
}

/**
 * Cash Flow Calculator
 *
 * Calculates income, expenses, and net cash flow from transactions.
 * Used across Dashboard, Reports, and Analytics.
 */

import type { Transaction } from '../types';

export interface CashFlowResult {
  totalIncome: number;
  totalExpenses: number;
  netCashFlow: number;
  incomeTransactions: Transaction[];
  expenseTransactions: Transaction[];
}

export interface CashFlowByCategory {
  categoryId: string;
  categoryName: string;
  amount: number;
  percentage: number;
  transactionCount: number;
}

/**
 * Calculate cash flow metrics from a list of transactions
 */
export function calculateCashFlow(transactions: Transaction[]): CashFlowResult {
  const incomeTransactions = transactions.filter(t => t.type === 'credit');
  const expenseTransactions = transactions.filter(t => t.type === 'debit');

  const totalIncome = incomeTransactions.reduce((sum, t) => sum + t.amount, 0);
  const totalExpenses = expenseTransactions.reduce((sum, t) => sum + t.amount, 0);
  const netCashFlow = totalIncome - totalExpenses;

  return {
    totalIncome,
    totalExpenses,
    netCashFlow,
    incomeTransactions,
    expenseTransactions,
  };
}

/**
 * Calculate cash flow breakdown by category
 */
export function calculateCashFlowByCategory(
  transactions: Transaction[],
  categories: Array<{ id: string; name: string }>,
  type: 'debit' | 'credit' | 'all' = 'all'
): CashFlowByCategory[] {
  // Filter by type if specified
  const filteredTxns = type === 'all'
    ? transactions
    : transactions.filter(t => t.type === type);

  // Group by category
  const categoryMap = new Map<string, { amount: number; count: number }>();

  for (const txn of filteredTxns) {
    const catId = txn.categoryId || 'uncategorized';
    const existing = categoryMap.get(catId) || { amount: 0, count: 0 };
    categoryMap.set(catId, {
      amount: existing.amount + txn.amount,
      count: existing.count + 1,
    });
  }

  // Calculate total for percentage
  const total = Array.from(categoryMap.values()).reduce((sum, cat) => sum + cat.amount, 0);

  // Convert to array and add metadata
  const results: CashFlowByCategory[] = [];

  for (const [catId, data] of categoryMap.entries()) {
    const category = categories.find(c => c.id === catId);
    results.push({
      categoryId: catId,
      categoryName: category?.name || 'Uncategorized',
      amount: data.amount,
      percentage: total > 0 ? (data.amount / total) * 100 : 0,
      transactionCount: data.count,
    });
  }

  // Sort by amount descending
  return results.sort((a, b) => b.amount - a.amount);
}

/**
 * Calculate month-over-month cash flow comparison
 */
export function calculateCashFlowTrend(
  currentPeriodTxns: Transaction[],
  previousPeriodTxns: Transaction[]
): {
  currentIncome: number;
  previousIncome: number;
  incomeChange: number;
  incomeChangePercent: number;
  currentExpenses: number;
  previousExpenses: number;
  expensesChange: number;
  expensesChangePercent: number;
  currentNet: number;
  previousNet: number;
  netChange: number;
  netChangePercent: number;
} {
  const current = calculateCashFlow(currentPeriodTxns);
  const previous = calculateCashFlow(previousPeriodTxns);

  return {
    currentIncome: current.totalIncome,
    previousIncome: previous.totalIncome,
    incomeChange: current.totalIncome - previous.totalIncome,
    incomeChangePercent: previous.totalIncome > 0
      ? ((current.totalIncome - previous.totalIncome) / previous.totalIncome) * 100
      : 0,
    currentExpenses: current.totalExpenses,
    previousExpenses: previous.totalExpenses,
    expensesChange: current.totalExpenses - previous.totalExpenses,
    expensesChangePercent: previous.totalExpenses > 0
      ? ((current.totalExpenses - previous.totalExpenses) / previous.totalExpenses) * 100
      : 0,
    currentNet: current.netCashFlow,
    previousNet: previous.netCashFlow,
    netChange: current.netCashFlow - previous.netCashFlow,
    netChangePercent: previous.netCashFlow !== 0
      ? ((current.netCashFlow - previous.netCashFlow) / Math.abs(previous.netCashFlow)) * 100
      : 0,
  };
}

/**
 * Prepare data for Sankey diagram
 * Format: { source: string, target: string, value: number }
 */
export interface SankeyNode {
  source: string;
  target: string;
  value: number;
}

export function prepareSankeyData(
  transactions: Transaction[],
  categories: Array<{ id: string; name: string }>
): SankeyNode[] {
  const nodes: SankeyNode[] = [];

  // Income flows: Income -> Total Income
  const incomeBySource = calculateCashFlowByCategory(
    transactions.filter(t => t.type === 'credit'),
    categories,
    'credit'
  );

  const totalIncome = incomeBySource.reduce((sum, cat) => sum + cat.amount, 0);

  // Add income sources to total income
  for (const source of incomeBySource) {
    if (source.amount > 0) {
      nodes.push({
        source: source.categoryName,
        target: 'Total Income',
        value: source.amount,
      });
    }
  }

  // Expense flows: Total Income -> Category
  const expenseByCategory = calculateCashFlowByCategory(
    transactions.filter(t => t.type === 'debit'),
    categories,
    'debit'
  );

  for (const expense of expenseByCategory) {
    if (expense.amount > 0) {
      nodes.push({
        source: 'Total Income',
        target: expense.categoryName,
        value: expense.amount,
      });
    }
  }

  // Savings: Total Income -> Savings (if positive net flow)
  const totalExpenses = expenseByCategory.reduce((sum, cat) => sum + cat.amount, 0);
  const savings = totalIncome - totalExpenses;

  if (savings > 0) {
    nodes.push({
      source: 'Total Income',
      target: 'Savings',
      value: savings,
    });
  }

  return nodes;
}

export function toCSV<T extends Record<string, unknown>>(rows: T[]): string {
  if (!rows.length) return '';
  const headers = Object.keys(rows[0]);
  const escape = (v: unknown): string => {
    if (v == null) return '';
    const s = String(v).replaceAll('"', '""');
    if (s.includes(',') || s.includes('\n') || s.includes('"')) return `"${s}"`;
    return s;
  };
  const lines = [headers.join(',')];
  for (const r of rows) {
    lines.push(headers.map((h) => escape(r[h])).join(','));
  }
  return lines.join('\n');
}

export function downloadCSV(filename: string, csv: string): void {
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.style.display = 'none';
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

export function formatCurrency(
  n: number,
  fractionDigits?: number,
  currency = 'USD',
  locale = 'en-US'
) {
  const options: Intl.NumberFormatOptions = {
    style: 'currency',
    currency,
  };

  if (fractionDigits !== undefined) {
    options.minimumFractionDigits = fractionDigits;
    options.maximumFractionDigits = fractionDigits;
  }

  return new Intl.NumberFormat(locale, options).format(n);
}

/**
 * Time Period Utilities
 *
 * Utilities for handling date ranges, time periods, and date formatting
 * for financial reports and analysis.
 */

import { format, startOfMonth, endOfMonth, subMonths, startOfYear, endOfYear, subYears } from 'date-fns';

export type TimePeriod = 'this-month' | 'last-month' | 'last-3-months' | 'last-6-months' | 'this-year' | 'last-year' | 'custom';

export interface DateRange {
  from: string; // ISO date string
  to: string;   // ISO date string
  label: string;
}

/**
 * Get date range for a predefined time period
 */
export function getTimePeriodRange(period: TimePeriod, customRange?: { from: Date; to: Date }): DateRange {
  const now = new Date();

  switch (period) {
    case 'this-month': {
      const from = startOfMonth(now);
      const to = endOfMonth(now);
      return {
        from: from.toISOString(),
        to: to.toISOString(),
        label: format(now, 'MMMM yyyy'),
      };
    }

    case 'last-month': {
      const lastMonth = subMonths(now, 1);
      const from = startOfMonth(lastMonth);
      const to = endOfMonth(lastMonth);
      return {
        from: from.toISOString(),
        to: to.toISOString(),
        label: format(lastMonth, 'MMMM yyyy'),
      };
    }

    case 'last-3-months': {
      const from = startOfMonth(subMonths(now, 2));
      const to = endOfMonth(now);
      return {
        from: from.toISOString(),
        to: to.toISOString(),
        label: 'Last 3 Months',
      };
    }

    case 'last-6-months': {
      const from = startOfMonth(subMonths(now, 5));
      const to = endOfMonth(now);
      return {
        from: from.toISOString(),
        to: to.toISOString(),
        label: 'Last 6 Months',
      };
    }

    case 'this-year': {
      const from = startOfYear(now);
      const to = endOfYear(now);
      return {
        from: from.toISOString(),
        to: to.toISOString(),
        label: format(now, 'yyyy'),
      };
    }

    case 'last-year': {
      const lastYear = subYears(now, 1);
      const from = startOfYear(lastYear);
      const to = endOfYear(lastYear);
      return {
        from: from.toISOString(),
        to: to.toISOString(),
        label: format(lastYear, 'yyyy'),
      };
    }

    case 'custom': {
      if (!customRange) {
        throw new Error('Custom range requires from and to dates');
      }
      return {
        from: customRange.from.toISOString(),
        to: customRange.to.toISOString(),
        label: `${format(customRange.from, 'MMM d')} - ${format(customRange.to, 'MMM d, yyyy')}`,
      };
    }

    default:
      return getTimePeriodRange('this-month');
  }
}

/**
 * Get previous period for comparison
 */
export function getPreviousPeriodRange(currentRange: DateRange): DateRange {
  const from = new Date(currentRange.from);
  const to = new Date(currentRange.to);

  // Calculate period length in days
  const periodLength = Math.ceil((to.getTime() - from.getTime()) / (1000 * 60 * 60 * 24));

  // Go back by the same period length
  const prevTo = new Date(from);
  prevTo.setDate(prevTo.getDate() - 1);

  const prevFrom = new Date(prevTo);
  prevFrom.setDate(prevFrom.getDate() - periodLength + 1);

  return {
    from: prevFrom.toISOString(),
    to: prevTo.toISOString(),
    label: `${format(prevFrom, 'MMM d')} - ${format(prevTo, 'MMM d, yyyy')}`,
  };
}

/**
 * Get available time period options
 */
export function getTimePeriodOptions(): Array<{ value: TimePeriod; label: string }> {
  return [
    { value: 'this-month', label: 'This Month' },
    { value: 'last-month', label: 'Last Month' },
    { value: 'last-3-months', label: 'Last 3 Months' },
    { value: 'last-6-months', label: 'Last 6 Months' },
    { value: 'this-year', label: 'This Year' },
    { value: 'last-year', label: 'Last Year' },
    { value: 'custom', label: 'Custom Range' },
  ];
}

/**
 * Check if a transaction falls within a date range
 */
export function isInRange(transactionDate: string, range: DateRange): boolean {
  const txnDate = new Date(transactionDate);
  const fromDate = new Date(range.from);
  const toDate = new Date(range.to);

  return txnDate >= fromDate && txnDate <= toDate;
}

/**
 * Filter transactions by date range
 */
export function filterByDateRange<T extends { dateISO: string }>(
  items: T[],
  range: DateRange
): T[] {
  return items.filter(item => isInRange(item.dateISO, range));
}

/**
 * Group items by month
 */
export function groupByMonth<T extends { dateISO: string }>(
  items: T[]
): Map<string, T[]> {
  const groups = new Map<string, T[]>();

  for (const item of items) {
    const month = item.dateISO.slice(0, 7); // YYYY-MM
    const existing = groups.get(month) || [];
    groups.set(month, [...existing, item]);
  }

  return groups;
}

/**
 * Get month list between two dates
 */
export function getMonthsBetween(from: string, to: string): string[] {
  const months: string[] = [];
  const current = new Date(from);
  const end = new Date(to);

  while (current <= end) {
    months.push(format(current, 'yyyy-MM'));
    current.setMonth(current.getMonth() + 1);
  }

  return months;
}

