        <span>Streak: {currentStreak}</span>
      </div>
      {isEditing && editDraft && (
        <HabitEditForm
          editDraft={editDraft}
          isSubmitting={isUpdating}
          hasError={hasUpdateError}
          onDraftChange={onEditDraftChange}
          onSubmit={onEditSubmit}
          onCancel={onCancelEdit}
        />
      )}
    </article>
  );
}

