  updateProject: (id: string, updates: Partial<ProjectData>) => Promise<void>;
  deleteProject: (id: string) => Promise<void>;

  // Utility functions
  refreshData: () => Promise<void>;
}

const toTaskStatus = (status?: TodoItem['status']): TaskData['status'] => {
  switch (status) {
    case 'todo':
    case 'need-to-start':
      return 'todo';
    case 'done':
      return 'done';
    case 'waiting':
    case 'pending-others':
      return 'waiting';
    case 'currently-working':
    case 'in_progress':
    case 'in-progress':
      return 'in_progress';
    case 'scheduled':
      return 'scheduled';
    default:
      return 'todo';
  }
};

const fromTaskStatus = (status?: TaskData['status']): TodoItem['status'] => {
  switch (status) {
    case 'in_progress':
      return 'in-progress';
    case 'waiting':
      return 'waiting';
    case 'scheduled':
      return 'scheduled';
    case 'done':
      return 'done';
    case 'todo':
    default:
      return 'todo';
  }
};

const mapTodoToTaskData = (todo: TodoItem): TaskData => ({
  id: todo.id,
  title: todo.title,
  description: todo.description,
  status: toTaskStatus(todo.status),
  priority: todo.priority as TaskData['priority'],
  estimated_time: todo.estimatedTime,
  actual_time: todo.actualTime,
  due_date: todo.dueDate?.toISOString(),
  tags: todo.tags,
  category: (todo.categoryId ?? todo.category ?? 'other') as TaskData['category'],
  notes: todo.notes,
  starred: todo.starred,
  archived: todo.archived,
  deleted: todo.deleted,
  deleted_at: todo.deletedAt?.toISOString(),
  completed_at: todo.completedAt?.toISOString(),
  created_at: todo.createdAt?.toISOString(),
  updated_at: todo.updatedAt?.toISOString(),
  project_id: todo.projectId,
  parent_id: todo.parentId,
});

const mapTaskInsertToTodo = (
  task: Omit<TaskData, 'id' | 'created_at' | 'updated_at'>,
): Omit<TodoItem, 'id' | 'createdAt' | 'updatedAt'> => ({
  title: task.title,
  description: task.description ?? undefined,
  status: fromTaskStatus(task.status),
  priority: (task.priority as TodoItem['priority']) ?? 'medium',
  estimatedTime: task.estimated_time ?? undefined,
  actualTime: task.actual_time ?? undefined,
  dueDate: task.due_date ? new Date(task.due_date) : undefined,
  tags: task.tags ?? [],
  categoryId: task.category ?? undefined,
  category: task.category ?? undefined,
  projectId: task.project_id ?? undefined,
  parentId: task.parent_id ?? undefined,
  completed: task.completed_at ? true : task.status === 'done',
  completedAt: task.completed_at ? new Date(task.completed_at) : undefined,
  deleted: task.deleted ?? false,
  deletedAt: task.deleted_at ? new Date(task.deleted_at) : undefined,
  notes: task.notes ?? undefined,
  archived: task.archived ?? undefined,
  starred: task.starred ?? undefined,
});

const mapTaskUpdateToTodoUpdate = (updates: Partial<TaskData>): Partial<TodoItem> => {
  const partial: Partial<TodoItem> = {};

  if (updates.title !== undefined) partial.title = updates.title;
  if (updates.description !== undefined) partial.description = updates.description ?? undefined;
  if (updates.status !== undefined) partial.status = fromTaskStatus(updates.status);
  if (updates.priority !== undefined) partial.priority = updates.priority as TodoItem['priority'];
  if (updates.estimated_time !== undefined) partial.estimatedTime = updates.estimated_time ?? undefined;
  if (updates.actual_time !== undefined) partial.actualTime = updates.actual_time ?? undefined;
  if (updates.due_date !== undefined) partial.dueDate = updates.due_date ? new Date(updates.due_date) : undefined;
  if (updates.tags !== undefined) partial.tags = updates.tags ?? [];
  if (updates.category !== undefined) partial.categoryId = updates.category ?? undefined;
  if (updates.category !== undefined) partial.category = updates.category ?? undefined;
  if (updates.project_id !== undefined) partial.projectId = updates.project_id ?? undefined;
  if (updates.parent_id !== undefined) partial.parentId = updates.parent_id ?? undefined;
  if (updates.deleted !== undefined) partial.deleted = updates.deleted;
  if (updates.deleted_at !== undefined) partial.deletedAt = updates.deleted_at ? new Date(updates.deleted_at) : undefined;
  if (updates.completed_at !== undefined) {
    partial.completed = Boolean(updates.completed_at);
    partial.completedAt = updates.completed_at ? new Date(updates.completed_at) : undefined;
  }

  return partial;
};

const mapProjectToProjectData = (project: StoreProject): ProjectData => ({
  id: project.id,
  name: project.name,
  description: project.description,
  color: project.color,
  status: project.status as ProjectData['status'],
  icon: project.icon,
  created_at: project.createdAt?.toISOString(),
  updated_at: project.updatedAt?.toISOString(),
});

export const useApiTasks = (): UseApiTasksReturn => {
  const {
    tasks: storeTasks,
    projects: storeProjects,
    tasksLoading,
    projectsLoading,
    addTodo,
    updateTodo,
    deleteTodo,
    restoreTodo,
    permanentlyDeleteTodo,
    addProject: addProjectToStore,
    updateProject: updateProjectInStore,
    deleteProject: deleteProjectFromStore,
  } = useAppStore();

  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState<boolean>(false);

  const tasks = useMemo((): TaskData[] => {
    if (!storeTasks || !Array.isArray(storeTasks)) return [];
    try {
      return storeTasks.map(mapTodoToTaskData);
    } catch {
      return [];
    }
  }, [storeTasks]);

  const projects = useMemo((): ProjectData[] => {
    if (!storeProjects || !Array.isArray(storeProjects)) return [];
    try {
      return storeProjects.map(mapProjectToProjectData);
    } catch {
      return [];
    }
  }, [storeProjects]);

  const createTask = useCallback(async (taskData: Omit<TaskData, 'id' | 'created_at' | 'updated_at'>): Promise<void> => {
    setError(null);
    try {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      await addTodo(mapTaskInsertToTodo(taskData));
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message);
      throw new Error(message);
    }
  }, [addTodo]);

  const updateTask = useCallback(async (id: string, updates: Partial<TaskData>): Promise<void> => {
    setError(null);
    try {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      await updateTodo(id, mapTaskUpdateToTodoUpdate(updates));
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message);
      throw new Error(message);
    }
  }, [updateTodo]);

  const deleteTask = useCallback(async (id: string): Promise<void> => {
    setError(null);
    try {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      await deleteTodo(id);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message);
      throw new Error(message);
    }
  }, [deleteTodo]);

  const restoreTask = useCallback(async (id: string): Promise<void> => {
    setError(null);
    try {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      await restoreTodo(id);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message);
      throw new Error(message);
    }
  }, [restoreTodo]);

  const permanentlyDeleteTask = useCallback(async (id: string): Promise<void> => {
    setError(null);
    try {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      await permanentlyDeleteTodo(id);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message);
      throw new Error(message);
    }
  }, [permanentlyDeleteTodo]);

  const createProject = useCallback(async (projectData: Omit<ProjectData, 'id' | 'created_at' | 'updated_at'>): Promise<void> => {
    setError(null);
    try {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      await addProjectToStore({
        name: projectData.name,
        description: projectData.description ?? undefined,
        color: projectData.color ?? '#6366f1',
        status: (projectData.status as StoreProject['status']) ?? 'active',
        icon: projectData.icon ?? '📁',
      });
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message);
      throw new Error(message);
    }
  }, [addProjectToStore]);

  const updateProject = useCallback(async (id: string, updates: Partial<ProjectData>): Promise<void> => {
    setError(null);
    try {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      await updateProjectInStore(id, {
        name: updates.name,
        description: updates.description ?? undefined,
        color: updates.color ?? undefined,
        status: updates.status,
        icon: updates.icon ?? undefined,
      });
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message);
      throw new Error(message);
    }
  }, [updateProjectInStore]);

  const deleteProject = useCallback(async (id: string): Promise<void> => {
    setError(null);
    try {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-call
      await deleteProjectFromStore(id);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message);
      throw new Error(message);
    }
  }, [deleteProjectFromStore]);

  const refreshData = useCallback(async (): Promise<void> => {
    setRefreshing(true);
    setError(null);
    try {
      await useAppStore.getState().initializeData();
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      setError(message);
      throw new Error(message);
    } finally {
      setRefreshing(false);
    }
  }, []);

  return {
    tasks,
    projects,
    loading: (tasksLoading === true) || (projectsLoading === true) || refreshing,
    error,
    createTask,
    updateTask,
    deleteTask,
    restoreTask,
    permanentlyDeleteTask,
    createProject,
    updateProject,
    deleteProject,
    refreshData,
  };
};

import { useState, useEffect, useCallback } from 'react';

interface AsyncState<T> {
  data: T | null;
  loading: boolean;
  error: Error | null;
}

interface UseAsyncReturn<T> extends AsyncState<T> {
  execute: () => Promise<void>;
  reset: () => void;
}

export function useAsync<T>(
  asyncFunction: () => Promise<T>,
  immediate = true
): UseAsyncReturn<T> {
  const [state, setState] = useState<AsyncState<T>>({
    data: null,
    loading: immediate,
    error: null,
  });

  const execute = useCallback(async () => {
    setState(prev => ({ ...prev, loading: true, error: null }));

    try {
      const data = await asyncFunction();
      setState({ data, loading: false, error: null });
    } catch (error) {
      setState({ data: null, loading: false, error: error as Error });
    }
  }, [asyncFunction]);

  const reset = useCallback(() => {
    setState({ data: null, loading: false, error: null });
  }, []);

  useEffect(() => {
    if (immediate) {
      execute();
    }
  }, [execute, immediate]);

  return { ...state, execute, reset };
}

// Hook for debounced async operations
export function useDebouncedAsync<T>(
  asyncFunction: () => Promise<T>,
  delay: number = 300,
  immediate = false
): UseAsyncReturn<T> & { debounce: () => void } {
  const [timeoutId, setTimeoutId] = useState<NodeJS.Timeout | null>(null);
  const asyncHook = useAsync(asyncFunction, immediate);

  const debounce = useCallback(() => {
    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    const newTimeoutId = setTimeout(() => {
      asyncHook.execute();
    }, delay);

    setTimeoutId(newTimeoutId);
  }, [asyncHook.execute, delay, timeoutId]);

  useEffect(() => {
    return () => {
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    };
  }, [timeoutId]);

  return { ...asyncHook, debounce };
}

// Hook for polling data
export function usePolling<T>(
  asyncFunction: () => Promise<T>,
  interval: number = 5000,
  enabled = true
): UseAsyncReturn<T> & { startPolling: () => void; stopPolling: () => void } {
  const [isPolling, setIsPolling] = useState(enabled);
  const asyncHook = useAsync(asyncFunction, true);

  const startPolling = useCallback(() => {
    setIsPolling(true);
  }, []);

  const stopPolling = useCallback(() => {
    setIsPolling(false);
  }, []);

  useEffect(() => {
    if (!isPolling) return;

    const intervalId = setInterval(() => {
      asyncHook.execute();
    }, interval);

    return () => clearInterval(intervalId);
  }, [isPolling, interval, asyncHook.execute]);

  return { ...asyncHook, startPolling, stopPolling };
}

// Conversational Voice Interface using FREE Web Speech API
// Works in Chrome, Safari, Edge (no API keys needed)

import { useState, useCallback, useRef, useEffect } from 'react';
import { logger } from '../services/logger';

import { ConversationEngine } from '../services/conversationEngine';

// TypeScript declarations for Web Speech API
interface SpeechRecognition extends EventTarget {
  continuous: boolean;
  interimResults: boolean;
  lang: string;
  start(): void;
  stop(): void;
  abort(): void;
  onresult: (event: SpeechRecognitionEvent) => void;
  onerror: (event: SpeechRecognitionErrorEvent) => void;
  onend: () => void;
}

interface SpeechRecognitionEvent {
  results: SpeechRecognitionResultList;
  resultIndex: number;
}

interface SpeechRecognitionResultList {
  length: number;
  item(index: number): SpeechRecognitionResult;
  [index: number]: SpeechRecognitionResult;
}

interface SpeechRecognitionResult {
  isFinal: boolean;
  length: number;
  item(index: number): SpeechRecognitionAlternative;
  [index: number]: SpeechRecognitionAlternative;
}

interface SpeechRecognitionAlternative {
  transcript: string;
  confidence: number;
}

interface SpeechRecognitionErrorEvent extends Event {
  error: string;
  message: string;
}

declare global {
  interface Window {
    SpeechRecognition: new () => SpeechRecognition;
    webkitSpeechRecognition: new () => SpeechRecognition;
  }
}

export interface ConversationState {
  isListening: boolean;
  isSpeaking: boolean;
  isThinking: boolean;
  transcript: string; // Current partial transcript
  error: string | null;
}

export function useConversationalVoice(userId: string): {
  isListening: boolean;
  isSpeaking: boolean;
  isThinking: boolean;
  transcript: string;
  error: string | null;
  startListening: () => void;
  stopListening: () => void;
  stopSpeaking: () => void;
  sendTextMessage: (text: string) => Promise<{ response: string } | undefined>;
  getMessages: () => Array<unknown>;
  clearHistory: () => void;
  isSupported: boolean;
} {
  const [state, setState] = useState<ConversationState>({
    isListening: false,
    isSpeaking: false,
    isThinking: false,
    transcript: '',
    error: null
  });

  const recognitionRef = useRef<SpeechRecognition | null>(null);
  const engineRef = useRef<ConversationEngine | null>(null);
  const utteranceRef = useRef<SpeechSynthesisUtterance | null>(null);

  // Initialize conversation engine
  useEffect(() => {
    engineRef.current = new ConversationEngine(userId);
  }, [userId]);

  // Initialize speech recognition
  useEffect(() => {
    const SpeechRecognitionAPI = window.SpeechRecognition || window.webkitSpeechRecognition;

    if (!SpeechRecognitionAPI) {
      setState(prev => ({
        ...prev,
        error: 'Speech recognition not supported in this browser. Try Chrome or Safari.'
      }));
      return;
    }

    const recognition = new SpeechRecognitionAPI();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = 'en-US';

    recognition.onresult = (event: SpeechRecognitionEvent): void => {
      let interimTranscript = '';
      let finalTranscript = '';

      for (let i = event.resultIndex; i < event.results.length; i++) {
        const transcript = event.results[i]?.[0]?.transcript ?? '';
        if (event.results[i].isFinal) {
          finalTranscript += transcript + ' ';
        } else {
          interimTranscript += transcript;
        }
      }

      // Update UI with interim results
      if (interimTranscript) {
        setState(prev => ({ ...prev, transcript: interimTranscript }));
      }

      // Process final transcript
      if (finalTranscript.trim()) {
        const userMessage = finalTranscript.trim();
        logger.info('UseConversationalVoice', '[Voice] User said:', userMessage);

        setState(prev => ({
          ...prev,
          isListening: false,
          isThinking: true,
          transcript: ''
        }));

        recognition.stop();

        // Send to conversation engine
        void (async () => {
          try {
            const result = await engineRef.current?.chat(userMessage);

            if (result) {
              setState(prev => ({
                ...prev,
                isThinking: false,
                isSpeaking: true
              }));

              // Speak response
              await speakText(result.response);

              setState(prev => ({
                ...prev,
                isSpeaking: false
              }));

              // Restart listening after a brief pause
              setTimeout(() => {
                startListening();
              }, 500);
            }
          } catch (error: unknown) {
            logger.error('UseConversationalVoice', '[Voice] Error:', error);
            setState(prev => ({
              ...prev,
              isThinking: false,
              error: error instanceof Error ? error.message : 'An unknown error occurred'
            }));
          }
        })();
      }
    };

    recognition.onerror = (event: SpeechRecognitionErrorEvent) => {
      logger.error('UseConversationalVoice', '[Voice] Recognition error:', event.error);

      if (event.error === 'no-speech') {
        // User didn't say anything, just continue listening
        return;
      }

      if (event.error === 'aborted') {
        // Intentional abort, don't show error
        return;
      }

      setState(prev => ({
        ...prev,
        error: `Speech recognition error: ${event.error}`,
        isListening: false
      }));
    };

    recognition.onend = () => {
      setState(prev => ({ ...prev, isListening: false }));
    };

    recognitionRef.current = recognition;

    return () => {
      recognition.stop();
    };
  }, [userId, speakText, startListening, engineRef]);

  const startListening = useCallback((): void => {
    if (!recognitionRef.current) {
      setState(prev => ({
        ...prev,
        error: 'Speech recognition not initialized'
      }));
      return;
    }

    try {
      // Stop any ongoing speech
      window.speechSynthesis.cancel();

      setState(prev => ({
        ...prev,
        isListening: true,
        isSpeaking: false,
        error: null,
        transcript: ''
      }));

      recognitionRef.current.start();
    } catch (error: unknown) {
      // Recognition might already be started
      logger.info('UseConversationalVoice', '[Voice] Start error (might already be running):',
        error instanceof Error ? error.message : 'An unknown error occurred'
      );
    }
  }, []);

  const stopListening = useCallback((): void => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
    }

    setState(prev => ({
      ...prev,
      isListening: false,
      transcript: ''
    }));
  }, []);

  const speakText = useCallback((text: string): Promise<void> => {
    return new Promise((resolve) => {
      // Cancel any ongoing speech
      window.speechSynthesis.cancel();

      const utterance = new SpeechSynthesisUtterance(text);

      // Use a more natural voice if available
      const voices = window.speechSynthesis.getVoices();
      const preferredVoice = voices.find(voice =>
        voice.name.includes('Samantha') || // macOS
        voice.name.includes('Google US English') || // Chrome
        voice.name.includes('Microsoft Zira') // Windows
      );

      if (preferredVoice) {
        utterance.voice = preferredVoice;
      }

      utterance.rate = 1.1; // Slightly faster for more natural flow
      utterance.pitch = 1.0;
      utterance.volume = 1.0;

      utterance.onend = () => {
        logger.info('UseConversationalVoice', '[Voice] Finished speaking');
        resolve();
      };

      utterance.onerror = (event) => {
        logger.error('UseConversationalVoice', '[Voice] Speech synthesis error:', event);
        resolve(); // Resolve anyway to not block
      };

      utteranceRef.current = utterance;
      window.speechSynthesis.speak(utterance);
    });
  }, []);

  const stopSpeaking = useCallback(() => {
    window.speechSynthesis.cancel();
    setState(prev => ({ ...prev, isSpeaking: false }));
  }, []);

  const sendTextMessage = useCallback(async (text: string): Promise<{ response: string } | undefined> => {
    setState(prev => ({ ...prev, isThinking: true }));

    try {
      const result = await engineRef.current?.chat(text);

      setState(prev => ({ ...prev, isThinking: false }));

      return result;
    } catch (error: unknown) {
      setState(prev => ({
        ...prev,
        isThinking: false,
        error: error instanceof Error ? error.message : 'An unknown error occurred'
      }));
      throw error;
    }
  }, []);

  const getMessages = useCallback((): Array<unknown> => {
    return engineRef.current?.getHistory() ?? [];
  }, []);

  const clearHistory = useCallback(() => {
    engineRef.current?.clearHistory();
  }, []);

  return {
    ...state,
    startListening,
    stopListening,
    stopSpeaking,
    sendTextMessage,
    getMessages,
    clearHistory,
    isSupported: !!(window.SpeechRecognition || window.webkitSpeechRecognition)
  };
}

import { useState, useEffect, useCallback } from 'react';
import { logger } from '../services/logger';

type SetValue<T> = T | ((val: T) => T);

export function useLocalStorage<T>(
  key: string,
  initialValue: T
): [T, (value: SetValue<T>) => void, () => void] {
  // Get value from localStorage on initial load
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      logger.warn('LocalStorage', `Error reading localStorage key "${key}":`, { error });
      return initialValue;
    }
  });

  // Return a wrapped version of useState's setter function that persists the new value to localStorage
  const setValue = useCallback(
    (value: SetValue<T>) => {
      try {
        // Allow value to be a function so we have the same API as useState
        const valueToStore = value instanceof Function ? value(storedValue) : value;
        setStoredValue(valueToStore);
        window.localStorage.setItem(key, JSON.stringify(valueToStore));
      } catch (error) {
        logger.warn('LocalStorage', `Error setting localStorage key "${key}":`, { error });
      }
    },
    [key, storedValue]
  );

  // Remove value from localStorage
  const removeValue = useCallback(() => {
    try {
      window.localStorage.removeItem(key);
      setStoredValue(initialValue);
    } catch (error) {
      logger.warn('LocalStorage', `Error removing localStorage key "${key}":`, { error });
    }
  }, [key, initialValue]);

  // Listen for changes to localStorage from other tabs/windows
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === key && e.newValue !== null) {
        try {
          setStoredValue(JSON.parse(e.newValue));
        } catch (error) {
          logger.warn('LocalStorage', `Error parsing localStorage value for key "${key}":`, { error });
        }
      }
    };

    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, [key]);

  return [storedValue, setValue, removeValue];
}

// Hook for session storage
export function useSessionStorage<T>(
  key: string,
  initialValue: T
): [T, (value: SetValue<T>) => void, () => void] {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.sessionStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      logger.warn('LocalStorage', `Error reading sessionStorage key "${key}":`, { error });
      return initialValue;
    }
  });

  const setValue = useCallback(
    (value: SetValue<T>) => {
      try {
        const valueToStore = value instanceof Function ? value(storedValue) : value;
        setStoredValue(valueToStore);
        window.sessionStorage.setItem(key, JSON.stringify(valueToStore));
      } catch (error) {
        logger.warn('LocalStorage', `Error setting sessionStorage key "${key}":`, { error });
      }
    },
    [key, storedValue]
  );

  const removeValue = useCallback(() => {
    try {
      window.sessionStorage.removeItem(key);
      setStoredValue(initialValue);
    } catch (error) {
      logger.warn('LocalStorage', `Error removing sessionStorage key "${key}":`, { error });
    }
  }, [key, initialValue]);

  return [storedValue, setValue, removeValue];
}

import { useMemo, useCallback, useRef, useEffect, useState } from 'react';
import { logger } from '../services/logger';

// Memoization hook for expensive calculations
export function useMemoizedCalculation<T>(
  calculateFn: () => T,
  dependencies: React.DependencyList
): T {
  return useMemo(calculateFn, dependencies);
}

// Debounced callback hook
export function useDebouncedCallback<T extends (...args: unknown[]) => unknown>(
  callback: T,
  delay = 300
): T {
  const debounceRef = useRef<NodeJS.Timeout | null>(null);

  return useCallback(
    ((...args: unknown[]) => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
      debounceRef.current = setTimeout(() => {
        callback(...args);
      }, delay);
    }) as T,
    [callback, delay]
  );
}

// Throttled callback hook
export function useThrottledCallback<T extends (...args: unknown[]) => unknown>(
  callback: T,
  delay = 300
): T {
  const lastRun = useRef(Date.now());

  return useCallback(
    ((...args: unknown[]) => {
      if (Date.now() - lastRun.current >= delay) {
        callback(...args);
        lastRun.current = Date.now();
      }
    }) as T,
    [callback, delay]
  );
}

// Previous value hook for comparison
export function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T>();
  useEffect(() => {
    ref.current = value;
  });
  return ref.current;
}

// Mount status hook
export function useIsMounted(): React.MutableRefObject<boolean> {
  const isMounted = useRef(false);

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
    };
  }, []);

  return isMounted;
}

// Intersection observer hook for lazy loading
export function useIntersectionObserver(
  elementRef: React.RefObject<Element>,
  options: IntersectionObserverInit = {}
): boolean {
  const [isIntersecting, setIsIntersecting] = useState(false);

  useEffect(() => {
    const element = elementRef.current;
    if (!element) return;

    const observer = new IntersectionObserver(
      ([entry]) => setIsIntersecting(entry.isIntersecting),
      {
        threshold: 0.1,
        ...options
      }
    );

    observer.observe(element);
    return () => observer.disconnect();
  }, [elementRef, options]);

  return isIntersecting;
}

// Virtual scrolling hook for large lists
export function useVirtualScroll<T>({
  items,
  itemHeight,
  containerHeight,
  overscan = 5
}: {
  items: T[];
  itemHeight: number;
  containerHeight: number;
  overscan?: number;
}): {
  visibleItems: { item: T; index: number }[];
  totalHeight: number;
  onScroll: (e: React.UIEvent<HTMLDivElement>) => void;
} {
  const [scrollTop, setScrollTop] = useState(0);

  const visibleItems = useMemo(() => {
    const startIndex = Math.max(0, Math.floor(scrollTop / itemHeight) - overscan);
    const endIndex = Math.min(
      items.length - 1,
      Math.ceil((scrollTop + containerHeight) / itemHeight) + overscan
    );

    return items.slice(startIndex, endIndex + 1).map((item, index) => ({
      item,
      index: startIndex + index
    }));
  }, [items, itemHeight, containerHeight, scrollTop, overscan]);

  const totalHeight = items.length * itemHeight;

  return {
    visibleItems,
    totalHeight,
    onScroll: (e: React.UIEvent<HTMLDivElement>) => {
      setScrollTop(e.currentTarget.scrollTop);
    }
  };
}

// Performance monitoring hook
export function usePerformanceMonitor(name: string): void {
  const startTime = useRef<number>(performance.now());

  useEffect(() => {
    startTime.current = performance.now();
  });

  useEffect(() => {
    return () => {
      const endTime = performance.now();
      const duration = endTime - startTime.current;
      logger.debug('Optimization', `${name} render time: ${duration.toFixed(2)}ms`);
    };
  });
}

// Memory usage monitoring (development only)
export function useMemoryMonitor(componentName: string): void {
  useEffect(() => {
    if (process.env.NODE_ENV === 'development') {
      const memoryInfo = (performance as { memory?: {
        usedJSHeapSize: number;
        totalJSHeapSize: number;
        jsHeapSizeLimit: number;
      } }).memory;
      if (memoryInfo) {
        logger.debug('Optimization', `${componentName} Memory Usage`, {
          used: Math.round(memoryInfo.usedJSHeapSize / 1048576) + ' MB',
          total: Math.round(memoryInfo.totalJSHeapSize / 1048576) + ' MB',
          limit: Math.round(memoryInfo.jsHeapSizeLimit / 1048576) + ' MB'
        });
      }
    }
  });
}

import { useState, useEffect } from 'react';

interface ResponsiveMapConfig {
  isMobile: boolean;
  isTablet: boolean;
  isDesktop: boolean;
  markerSize: number;
  popupMaxWidth: number;
  zoomLevel: number;
  sidebarWidth: string;
}

export const useResponsiveMap = (): ResponsiveMapConfig => {
  const [screenSize, setScreenSize] = useState({
    width: typeof window !== 'undefined' ? window.innerWidth : 1024,
    height: typeof window !== 'undefined' ? window.innerHeight : 768,
  });

  useEffect(() => {
    const handleResize = () => {
      setScreenSize({
        width: window.innerWidth,
        height: window.innerHeight,
      });
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const isMobile = screenSize.width < 640;
  const isTablet = screenSize.width >= 640 && screenSize.width < 1024;
  const isDesktop = screenSize.width >= 1024;

  const markerSize = isMobile ? 20 : isTablet ? 28 : 32;
  const popupMaxWidth = isMobile ? 240 : isTablet ? 280 : 320;
  const zoomLevel = isMobile ? 3 : isTablet ? 3.5 : 4;
  const sidebarWidth = isMobile ? '100%' : isTablet ? '50%' : '320px';

  return {
    isMobile,
    isTablet,
    isDesktop,
    markerSize,
    popupMaxWidth,
    zoomLevel,
    sidebarWidth,
  };
};

export default useResponsiveMap;

import { useCallback, useEffect, useRef, useState } from 'react';

export type ToastKind = 'info' | 'success' | 'error';

export interface ToastState {
  message: string;
  type?: ToastKind;
}

export const useToast = (duration = 4000) => {
  const [toast, setToast] = useState<ToastState | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const clearTimer = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
  }, []);

  const dismissToast = useCallback(() => {
    clearTimer();
    setToast(null);
  }, [clearTimer]);

  const showToast = useCallback(
    (message: string, type: ToastKind = 'info') => {
      clearTimer();
      setToast({ message, type });
      timeoutRef.current = setTimeout(() => {
        setToast(null);
        timeoutRef.current = null;
      }, duration);
    },
    [clearTimer, duration],
  );

  useEffect(() => () => clearTimer(), [clearTimer]);

  return { toast, showToast, dismissToast };
};

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

export type VoiceState = {
  supported: boolean
  listening: boolean
  transcript: string
  lang: string
  error?: string
}

export type UseVoice = VoiceState & {
  start: () => void
  stop: () => void
  toggle: () => void
  clear: () => void
  setLang: (lang: string) => void
  speak: (text: string, opts?: { rate?: number; pitch?: number; lang?: string }) => Promise<void>
}

type Options = {
  onFinal?: (text: string) => void
}

export function useVoice(initialLang = 'en-US', options?: Options): UseVoice {
  const recRef = useRef<ISpeechRecognition | null>(null);
  const [supported] = useState<boolean>(() => !!(window.SpeechRecognition || window.webkitSpeechRecognition));
  const [listening, setListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [lang, setLang] = useState(initialLang);
  const [error, setError] = useState<string | undefined>(undefined);

  useEffect(() => {
    if (!supported) return;
    const Ctor = (window.SpeechRecognition || window.webkitSpeechRecognition) as new () => ISpeechRecognition;
    const rec: ISpeechRecognition = new Ctor();
    rec.continuous = true;
    rec.interimResults = true;
    rec.lang = lang;
    rec.onresult = (ev: SpeechRecognitionEvent) => {
      let interim = '';
      for (let i = ev.results.length - 1; i >= 0; i--) {
        const result = ev.results[i];
        const alt = result[0];
        if (!alt) continue;
        if (result.isFinal) {
          setTranscript((t) => (t ? `${t} ${alt.transcript}` : alt.transcript));
          if (options?.onFinal) options.onFinal(alt.transcript);
        } else {
          interim = alt.transcript;
        }
      }
      // Show interim in suffix (UI can choose how to display)
      if (interim) setTranscript((t) => `${t.replace(/\s+$/, '')} ${interim}`);
    };
    rec.onerror = (e: Event) => {
      const error = e as { error?: string };
      setError(error.error || 'speech_error');
    };
    rec.onend = () => setListening(false);
    recRef.current = rec;
    return () => {
      try { rec.stop(); } catch (e: unknown) {
        // Ignore any errors during stop
        void e;
      }
      recRef.current = null;
    };
  }, [lang, supported, options]);

  const start = useCallback((): void => {
    if (!supported || !recRef.current) return;
    setError(undefined);
    try {
      if (recRef.current) {
        recRef.current.lang = lang;
        recRef.current.start();
      }
      setListening(true);
    } catch (e: unknown) {
      const error = e as Error;
      setError(error.message || 'speech_start_failed');
    }
  }, [lang, supported]);

  const stop = useCallback((): void => {
    if (!recRef.current) return;
    try { recRef.current.stop(); } catch {}
    setListening(false);
  }, []);

  const toggle = useCallback((): void => (listening ? stop() : start()), [listening, start, stop]);
  const clear = useCallback((): void => setTranscript(''), []);

  const speak = useCallback((text: string, opts?: { rate?: number; pitch?: number; lang?: string }): Promise<void> => {
    return new Promise<void>((resolve) => {
      if (!('speechSynthesis' in window)) return resolve();
      const u = new SpeechSynthesisUtterance(text);
      u.lang = opts?.lang || lang;
      u.rate = opts?.rate ?? 1;
      u.pitch = opts?.pitch ?? 1;
      u.onend = () => resolve();
      u.onerror = () => resolve();
      try { window.speechSynthesis.cancel(); } catch (e: unknown) {
        // Ignore cancellation errors
        void e;
      }
      window.speechSynthesis.speak(u);
    });
  }, [lang]);

  return useMemo(
    () => ({ supported, listening, transcript, lang, error, start, stop, toggle, clear, setLang, speak }),
    [supported, listening, transcript, lang, error, start, stop, toggle, clear, setLang, speak]
  )
}

export default useVoice

import { useState, useEffect, useRef, useCallback, startTransition } from 'react';
import { logger } from '../services/logger';

type GenericPayload = Record<string, unknown>;

interface WebSocketMessage<T extends GenericPayload = GenericPayload> {
  type: string;
  payload: T;
  timestamp: Date;
}

interface UseWebSocketOptions<T extends GenericPayload = GenericPayload> {
  url?: string;
  onMessage?: (message: WebSocketMessage<T>) => void;
  onConnect?: () => void;
  onDisconnect?: () => void;
  onError?: (error: Event) => void;
  reconnectInterval?: number;
  maxReconnectAttempts?: number;
  simulateConnection?: boolean;
}

interface WebSocketState<T extends GenericPayload = GenericPayload> {
  isConnected: boolean;
  isConnecting: boolean;
  error: string | null;
  lastMessage: WebSocketMessage<T> | null;
  connectionAttempts: number;
}

export function useWebSocket<T extends GenericPayload = GenericPayload>(
  options: UseWebSocketOptions<T> = {}
): {
  isConnected: boolean;
  isConnecting: boolean;
  error: string | null;
  lastMessage: WebSocketMessage<T> | null;
  connectionAttempts: number;
  connect: () => void;
  disconnect: () => void;
  sendMessage: (message: T) => boolean;
  reconnect: () => void;
} {
  const {
    url = 'wss://api.example.com/financial-data',
    onMessage,
    onConnect,
    onDisconnect,
    onError,
    reconnectInterval = 3000,
    maxReconnectAttempts = 5,
    simulateConnection = true
  } = options;

  const [state, setState] = useState<WebSocketState>({
    isConnected: false,
    isConnecting: false,
    error: null,
    lastMessage: null,
    connectionAttempts: 0
  });

  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const simulationIntervalRef = useRef<NodeJS.Timeout | null>(null);

  // Simulate market data for demo purposes
  const simulateMarketData = useCallback(() => {
    const marketDataTypes = [
      'price_update',
      'portfolio_update',
      'news_update',
      'alert_trigger',
      'market_status'
    ];

    const generateMessage = (): WebSocketMessage => {
      const type = marketDataTypes[Math.floor(Math.random() * marketDataTypes.length)];
      let payload;

      switch (type) {
        case 'price_update':
          payload = {
            symbol: ['AAPL', 'MSFT', 'GOOGL', 'TSLA', 'SPY'][Math.floor(Math.random() * 5)],
            price: 150 + Math.random() * 300,
            change: (Math.random() - 0.5) * 10,
            changePercent: (Math.random() - 0.5) * 5,
            volume: Math.floor(Math.random() * 1000000)
          };
          break;

        case 'portfolio_update':
          payload = {
            totalValue: 50000 + Math.random() * 100000,
            dayChange: (Math.random() - 0.5) * 5000,
            positions: [
              {
                symbol: 'VTI',
                value: 25000 + Math.random() * 10000,
                change: (Math.random() - 0.5) * 1000
              }
            ]
          };
          break;

        case 'news_update':
          payload = {
            headline: 'Market Update: ' + new Date().toLocaleTimeString(),
            sentiment: ['positive', 'negative', 'neutral'][Math.floor(Math.random() * 3)],
            impact: ['high', 'medium', 'low'][Math.floor(Math.random() * 3)],
            symbols: ['AAPL', 'MSFT']
          };
          break;

        case 'alert_trigger':
          payload = {
            type: 'price_target',
            symbol: 'AAPL',
            message: 'Price target reached',
            threshold: 180
          };
          break;

        case 'market_status':
          payload = {
            status: 'open',
            nextClose: new Date(Date.now() + 6 * 60 * 60 * 1000),
            tradingVolume: Math.floor(Math.random() * 1000000000)
          };
          break;

        default:
          payload = {};
      }

      return {
        type,
        payload,
        timestamp: new Date()
      };
    };

    return generateMessage;
  }, []);

  const connect = useCallback(() => {
    if (state.isConnecting || state.isConnected) return;

    setState(prev => ({ ...prev, isConnecting: true, error: null }));

    if (simulateConnection) {
      // Simulate connection delay
      setTimeout(() => {
        setState(prev => ({
          ...prev,
          isConnected: true,
          isConnecting: false,
          connectionAttempts: 0
        }));

        onConnect?.();

        // Start sending simulated data
        const generateMessage = simulateMarketData();
        simulationIntervalRef.current = setInterval(() => {
          const message = generateMessage();
          startTransition(() => {
            setState(prev => ({ ...prev, lastMessage: message }));
            onMessage?.(message);
          });
        }, 1000 + Math.random() * 4000); // Random interval between 1-5 seconds

      }, 500 + Math.random() * 1500); // Random connection delay
    } else {
      // Real WebSocket connection
      try {
        wsRef.current = new WebSocket(url);

        wsRef.current.onopen = () => {
          setState(prev => ({
            ...prev,
            isConnected: true,
            isConnecting: false,
            connectionAttempts: 0,
            error: null
          }));
          onConnect?.();
        };

        wsRef.current.onmessage = (event) => {
          // Defer heavy work off the message event loop tick
          const raw = event.data;
          setTimeout(() => {
            try {
              const message: WebSocketMessage = typeof raw === 'string' ? JSON.parse(raw) : raw;
              startTransition(() => {
                setState(prev => ({ ...prev, lastMessage: message }));
                onMessage?.(message);
              });
            } catch (error) {
              logger.error('Failed to handle WebSocket message:', { error });
            }
          }, 0);
        };

        wsRef.current.onclose = () => {
          setState(prev => ({ ...prev, isConnected: false, isConnecting: false }));
          onDisconnect?.();
          attemptReconnect();
        };

        wsRef.current.onerror = (error) => {
          setState(prev => ({
            ...prev,
            error: 'Connection failed',
            isConnecting: false
          }));
          onError?.(error);
        };
      } catch (_error) {
        setState(prev => ({
          ...prev,
          error: 'Failed to create WebSocket connection',
          isConnecting: false
        }));
      }
    }
  }, [state.isConnecting, state.isConnected, simulateConnection, url, onConnect, onMessage, onDisconnect, onError, simulateMarketData]);

  const disconnect = useCallback(() => {
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
      reconnectTimeoutRef.current = null;
    }

    if (simulationIntervalRef.current) {
      clearInterval(simulationIntervalRef.current);
      simulationIntervalRef.current = null;
    }

    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }

    setState(prev => ({
      ...prev,
      isConnected: false,
      isConnecting: false,
      connectionAttempts: 0
    }));
  }, []);

  const attemptReconnect = useCallback(() => {
    if (state.connectionAttempts >= maxReconnectAttempts) {
      setState(prev => ({
        ...prev,
        error: `Max reconnection attempts (${maxReconnectAttempts}) reached`
      }));
      return;
    }

    setState(prev => ({
      ...prev,
      connectionAttempts: prev.connectionAttempts + 1
    }));

    reconnectTimeoutRef.current = setTimeout(() => {
      connect();
    }, reconnectInterval);
  }, [state.connectionAttempts, maxReconnectAttempts, reconnectInterval, connect]);

  const sendMessage = useCallback((message: T) => {
    if (!state.isConnected) {
      logger.warn('WebSocket', 'WebSocket is not connected');
      return false;
    }

    try {
      if (simulateConnection) {
        // For simulation, just log the message
        logger.debug('Simulated WebSocket send:', { message });
        return true;
      } else if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
        wsRef.current.send(JSON.stringify(message));
        return true;
      }
    } catch (error) {
      logger.error('Failed to send WebSocket message:', { error });
      setState(prev => ({ ...prev, error: 'Failed to send message' }));
    }

    return false;
  }, [state.isConnected, simulateConnection]);

  // Auto-connect on mount
  useEffect(() => {
    connect();

    return () => {
      disconnect();
    };
  }, [connect, disconnect]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
      }
      if (simulationIntervalRef.current) {
        clearInterval(simulationIntervalRef.current);
      }
      if (wsRef.current) {
        wsRef.current.close();
      }
    };
  }, []);

  return {
    ...state,
    connect,
    disconnect,
    sendMessage,
    reconnect: connect
  };
}

// Hook for financial data specifically
interface FinancialDataPayload {
  symbol?: string;
  price?: number;
  totalValue?: number;
  title?: string;
  type?: string;
}

export function useFinancialDataWebSocket(): {
  marketData: FinancialDataPayload[];
  portfolioData: FinancialDataPayload | null;
  alerts: FinancialDataPayload[];
  news: FinancialDataPayload[];
  clearAlerts: () => void;
  clearNews: () => void;
  isConnected: boolean;
  isConnecting: boolean;
  error: string | null;
  lastMessage: WebSocketMessage<FinancialDataPayload> | null;
  connectionAttempts: number;
  connect: () => void;
  disconnect: () => void;
  sendMessage: (message: FinancialDataPayload) => boolean;
  reconnect: () => void;
} {
  const SIMULATE_WS = import.meta.env.VITE_SIMULATE_WS === 'true';
  const [marketData, setMarketData] = useState<FinancialDataPayload[]>([]);
  const [portfolioData, setPortfolioData] = useState<FinancialDataPayload | null>(null);
  const [alerts, setAlerts] = useState<FinancialDataPayload[]>([]);
  const [news, setNews] = useState<FinancialDataPayload[]>([]);

  const handleMessage = useCallback((message: WebSocketMessage<FinancialDataPayload>) => {
    switch (message.type) {
      case 'price_update':
        setMarketData(prev => {
          const updated = [...prev];
          const index = updated.findIndex(item => item.symbol === message.payload.symbol);
          if (index >= 0) {
            updated[index] = { ...updated[index], ...message.payload };
          } else {
            updated.push(message.payload);
          }
          return updated;
        });
        break;

      case 'portfolio_update':
        setPortfolioData(message.payload);
        break;

      case 'news_update':
        setNews(prev => [message.payload, ...prev.slice(0, 9)]); // Keep last 10 news items
        break;

      case 'alert_trigger':
        setAlerts(prev => [message.payload, ...prev.slice(0, 4)]); // Keep last 5 alerts
        break;
    }
  }, []);

  const webSocket = useWebSocket({
    onMessage: handleMessage,
    simulateConnection: SIMULATE_WS // Control via VITE_SIMULATE_WS env var
  });

  return {
    ...webSocket,
    marketData,
    portfolioData,
    alerts,
    news,
    clearAlerts: () => setAlerts([]),
    clearNews: () => setNews([])
  };
}

/**
 * Groq LLM Provider
 *
 * Free tier: 14,400 requests/day
 * Models: llama-3.1-70b-versatile, mixtral-8x7b-32768
 * Fast inference, function calling support
 */

import Groq from 'groq-sdk';
import type {
  LLMProvider,
  Message,
  ChatOptions,
  ChatResponse,
  ChatChunk,
  FunctionCall
} from '../interfaces';
import { logger } from '../../../services/logger';

export class GroqProvider implements LLMProvider {
  private client: Groq;
  private model: string;
  private available: boolean = true;

  constructor(apiKey: string, model: string = 'llama-3.1-70b-versatile') {
    this.client = new Groq({
      apiKey,
      dangerouslyAllowBrowser: true // OK for personal use; use server proxy in production
    });
    this.model = model;
  }

  async chat(messages: Message[], options?: ChatOptions): Promise<ChatResponse> {
    try {
      const response = await this.client.chat.completions.create({
        model: this.model,
        messages: messages.map(msg => ({
          role: msg.role as 'system' | 'user' | 'assistant',
          content: msg.content,
          ...(msg.name && { name: msg.name })
        })),
        temperature: options?.temperature ?? 0.7,
        max_tokens: options?.maxTokens ?? 2000,
        ...(options?.functions && {
          tools: options.functions.map(fn => ({
            type: 'function' as const,
            function: {
              name: fn.name,
              description: fn.description,
              parameters: fn.parameters
            }
          }))
        })
      });

      const choice = response.choices[0];

      // Check for function call
      let functionCall: FunctionCall | undefined;
      if (choice.message.tool_calls && choice.message.tool_calls.length > 0) {
        const toolCall = choice.message.tool_calls[0];
        functionCall = {
          name: toolCall.function.name,
          arguments: toolCall.function.arguments
        };
      }

      return {
        content: choice.message.content || '',
        functionCall,
        usage: response.usage ? {
          promptTokens: response.usage.prompt_tokens,
          completionTokens: response.usage.completion_tokens,
          totalTokens: response.usage.total_tokens
        } : undefined
      };
    } catch (error) {
      logger.error('GroqProvider.chat failed', { error });

      // Mark as unavailable on rate limit or auth errors
      if (error instanceof Error &&
          (error.message.includes('rate limit') || error.message.includes('401'))) {
        this.available = false;
      }

      throw error;
    }
  }

  async *streamChat(messages: Message[], options?: ChatOptions): AsyncIterable<ChatChunk> {
    try {
      const stream = await this.client.chat.completions.create({
        model: this.model,
        messages: messages.map(msg => ({
          role: msg.role as 'system' | 'user' | 'assistant',
          content: msg.content
        })),
        temperature: options?.temperature ?? 0.7,
        max_tokens: options?.maxTokens ?? 2000,
        stream: true
      });

      for await (const chunk of stream) {
        const delta = chunk.choices[0]?.delta;

        if (delta?.content) {
          yield {
            content: delta.content,
            done: false
          };
        }
      }

      yield { done: true };
    } catch (error) {
      logger.error('GroqProvider.streamChat failed', { error });
      throw error;
    }
  }

  getName(): string {
    return 'groq';
  }

  async isAvailable(): Promise<boolean> {
    if (!this.available) {
      return false;
    }

    try {
      // Simple ping to check availability
      await this.client.chat.completions.create({
        model: this.model,
        messages: [{ role: 'user', content: 'ping' }],
        max_tokens: 5
      });
      return true;
    } catch (error) {
      logger.warn('GroqProvider availability check failed', { error });
      return false;
    }
  }
}

