/**
 * useRecipeImport Hook
 * Handles importing recipes from various sources (YouTube, URL, text)
 */

import { useState } from 'react';
import type { Recipe } from '../../../types';
import { fetchYoutubeRecipe } from '../../services/parsers/youtubeParser';
import { parseTextToRecipe } from '../../services/parsers/textParser';
import { logger } from '../../../services/logger';

export interface RecipeImportState {
  isImporting: boolean;
  error: string | null;
  draft: Omit<Recipe, 'id' | 'createdAt'> | null;
}

export interface RecipeImportActions {
  importFromVideo: (url: string, lang?: string) => Promise<void>;
  importFromText: (text: string, title?: string) => Promise<void>;
  importFromUrl: (url: string) => Promise<void>;
  clearDraft: () => void;
  clearError: () => void;
}

export type UseRecipeImportReturn = RecipeImportState & RecipeImportActions;

/**
 * Hook for importing recipes from various sources
 */
export function useRecipeImport(): UseRecipeImportReturn {
  const [isImporting, setIsImporting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [draft, setDraft] = useState<Omit<Recipe, 'id' | 'createdAt'> | null>(null);

  /**
   * Import recipe from YouTube video
   */
  const importFromVideo = async (url: string, lang: string = 'en'): Promise<void> => {
    try {
      setIsImporting(true);
      setError(null);

      const recipe = await fetchYoutubeRecipe(url, lang);
      setDraft(recipe);

      logger.info('RecipeImport', 'Successfully imported recipe from YouTube:', { url });
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to import from video';
      setError(errorMessage);
      logger.error('RecipeImport', 'Failed to import from YouTube:', { error: err });
    } finally {
      setIsImporting(false);
    }
  };

  /**
   * Import recipe from pasted text
   */
  const importFromText = async (text: string, title?: string): Promise<void> => {
    try {
      setIsImporting(true);
      setError(null);

      const recipe = parseTextToRecipe(text, title);
      setDraft(recipe);

      logger.info('RecipeImport', 'Successfully parsed recipe from text');
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to parse text';
      setError(errorMessage);
      logger.error('RecipeImport', 'Failed to parse text:', { error: err });
    } finally {
      setIsImporting(false);
    }
  };

  /**
   * Import recipe from URL (website scraping)
   * TODO: Implement website scraping service
   */
  const importFromUrl = async (url: string): Promise<void> => {
    try {
      setIsImporting(true);
      setError(null);

      // For now, use a simple fetch approach
      // In the future, this can use a dedicated scraping service
      const response = await fetch(`/api/recipe/scrape?url=${encodeURIComponent(url)}`);

      if (!response.ok) {
        throw new Error('Failed to fetch recipe from URL');
      }

      const recipe = await response.json();
      setDraft(recipe);

      logger.info('RecipeImport', 'Successfully imported recipe from URL:', { url });
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to import from URL';
      setError(errorMessage);
      logger.error('RecipeImport', 'Failed to import from URL:', { error: err });
    } finally {
      setIsImporting(false);
    }
  };

  /**
   * Clear the current draft
   */
  const clearDraft = (): void => {
    setDraft(null);
    setError(null);
  };

  /**
   * Clear error state
   */
  const clearError = (): void => {
    setError(null);
  };

  return {
    // State
    isImporting,
    error,
    draft,

    // Actions
    importFromVideo,
    importFromText,
    importFromUrl,
    clearDraft,
    clearError,
  };
}

/**
 * Text Parser Service
 * Parses recipes from plain text, markdown, and pasted content
 */

import type { Recipe } from '../../../types';
import { parseDescriptionToLists } from './youtubeParser';

/**
 * Parse markdown table into structured ingredients
 */
export function parseMarkdownTable(rows: string[]): Array<{ name: string; amount?: string }> {
  const out: Array<{ name: string; amount?: string }> = [];
  let i = 0;
  while (i < rows.length) {
    if (!/^\|/.test(rows[i])) { i++; continue; }
    // collect contiguous table block
    const block: string[] = [];
    while (i < rows.length && /^\|.*\|$/.test(rows[i])) { block.push(rows[i]); i++; }
    if (block.length < 2) continue;
    const cells = (r: string) => r.split('|').slice(1, -1).map(c => c.trim());
    const header = cells(block[0]);
    const sep = block[1];
    if (!/^-/.test(sep.replace(/\|/g, '').trim())) {
      // no separator, treat as simple rows with 2 columns fallback
    }
    const idxName = header.findIndex(h => /ingredient/i.test(h));
    const idxAmt = header.findIndex(h => /amount|notes/i.test(h));
    for (let j = 1; j < block.length; j++) {
      const row = cells(block[j]);
      if (!row.length) continue;
      if (row.every(col => /^-+$/.test(col))) continue; // separator
      const name = (idxName !== -1 ? row[idxName] : row[0] || '').trim();
      const amount = (idxAmt !== -1 ? row[idxAmt] : row[1] || '').trim();
      if (name) out.push({ name, amount: amount || undefined });
    }
  }
  return out;
}

/**
 * Normalize fraction characters to standard format
 */
export function normalizeFractions(text: string): string {
  return text
    .replace(/½/g, ' 1/2')
    .replace(/¼/g, ' 1/4')
    .replace(/¾/g, ' 3/4')
    .replace(/⅓/g, ' 1/3')
    .replace(/⅔/g, ' 2/3')
    .replace(/⅛/g, ' 1/8')
    .replace(/⅜/g, ' 3/8')
    .replace(/⅝/g, ' 5/8')
    .replace(/⅞/g, ' 7/8');
}

/**
 * Parse text into a recipe object
 */
export function parseTextToRecipe(text: string, title?: string): Omit<Recipe, 'id' | 'createdAt'> {
  const rawLines = text.split(/\r?\n/);
  const lines = rawLines.map(l => l.trim()).filter(Boolean);

  // Detect sections
  const idxIng = lines.findIndex(l => /^ingredients?\b/i.test(l));
  const idxEqp = lines.findIndex(l => /^(equipment|tools?)\b/i.test(l));
  const idxTip = lines.findIndex(l => /^tips?\b|^notes?\b/i.test(l));
  const idxDir = lines.findIndex(l => /^(directions?|instructions?|method)\b/i.test(l));

  let ingredients: string[] = [];
  let equipment: string[] = [];
  let tips: string[] = [];
  let instructions: string[] = [];

  const endOf = (...idx: number[]) => {
    const positive = idx.filter(i => i !== -1).sort((a,b)=>a-b);
    return (start: number) => positive.find(i => i > start) ?? lines.length;
  };

  if (idxIng !== -1 || idxDir !== -1 || idxEqp !== -1 || idxTip !== -1) {
    const nextAfter = endOf(idxIng, idxDir, idxEqp, idxTip);
    if (idxIng !== -1) ingredients = lines.slice(idxIng + 1, nextAfter(idxIng));
    if (idxDir !== -1) instructions = lines.slice(idxDir + 1, nextAfter(idxDir));
    if (idxEqp !== -1) equipment = lines.slice(idxEqp + 1, nextAfter(idxEqp));
    if (idxTip !== -1) tips = lines.slice(idxTip + 1, nextAfter(idxTip));
  }

  // Try to pull servings from headings like "Ingredients (for ~2–3 servings)"
  let inferredServings: number | undefined;
  const servingsRe = /for\s*~?\s*(\d+)(?:\s*[–-]\s*|\s*to\s*)(\d+)\s*servings?|for\s*(\d+)\s*servings?/i;
  for (const l of lines.slice(Math.max(0, idxIng - 2), Math.min(lines.length, idxIng + 3))) {
    const m = l.match(servingsRe);
    if (m) {
      if (m[1] && m[2]) {
        const a = parseInt(m[1], 10);
        const b = parseInt(m[2], 10);
        inferredServings = Math.max(a, b);
      } else if (m[3]) {
        inferredServings = parseInt(m[3], 10);
      }
      break;
    }
  }

  // Extract table-based ingredients, if any
  let tableIngs: Array<{ name: string; amount?: string }> = [];
  if (ingredients.length) {
    tableIngs = parseMarkdownTable(ingredients.filter(l => l));
  }

  // Heuristics if headings are missing
  if (ingredients.length === 0 || instructions.length === 0) {
    const joined = lines.join('\n');
    const parsed = parseDescriptionToLists(joined);
    if (ingredients.length === 0) ingredients = parsed.ingredients;
    if (instructions.length === 0) instructions = parsed.instructions;
  }

  // Final normalization + ingredient structuring
  const unitList = ['cup','cups','tsp','tbsp','teaspoon','tablespoon','g','gram','grams','kg','ml','l','liter','liters','ounce','ounces','oz','lb','pound','pounds','clove','cloves','slice','slices','pinch','dash','stick','sticks','can','cans','package','packages','bunch','bunches','head','heads','piece','pieces','quart','pint','sprig','sprigs'];
  const unitRe = new RegExp(`^((?:\\d+(?:[\\s-]\\d/\\d)?|\\d+/\\d+|\\d+(?:\\.\\d+)?)(?:\\s*x)?)?\\s*(?:(${unitList.join('|')}))?\\s*(.*)$`, 'i');
  const cleanBullet = (s: string) => s.replace(/^[-*•]\s*/, '').trim();

  const lineIngs = ingredients
    .filter(l => !/^\|/.test(l)) // skip table rows, already parsed
    .map(cleanBullet)
    .filter(Boolean)
    .slice(0, 100)
    .map(raw => {
      const m = raw.match(unitRe);
      if (!m) return { name: raw };
      const amount = (m[1] || '').trim();
      const unit = (m[2] || '').trim();
      const name = (m[3] || raw).trim();
      return { name, amount: amount || undefined, unit: unit || undefined };
    });

  const ingOut = [
    ...tableIngs.map(t => ({ name: t.name, amount: t.amount })),
    ...lineIngs,
  ].slice(0, 100);

  const stepsOut = instructions
    .map(s => s.replace(/^\d+\.|^[-*•]\s*/, '').trim())
    .filter(Boolean)
    .slice(0, 50);

  // Basic time estimates
  const prepTime = Math.max(5, Math.min(30, ingOut.length * 2));
  const cookTime = Math.max(10, Math.min(60, stepsOut.length * 3));

  // Equipment tags + tips
  const equipTags = equipment
    .map(cleanBullet)
    .filter(Boolean)
    .slice(0, 30)
    .map(t => `equip:${t.toLowerCase()}`);
  const notes = tips.map(cleanBullet).join('\n');

  // Build description from the first paragraph before any heading or rule
  let description = '';
  {
    const firstParaLines: string[] = [];
    for (const r of rawLines) {
      if (/^\s*#/.test(r) || /^\s*---/.test(r)) break;
      if (r.trim().length === 0 && firstParaLines.length > 0) break;
      if (r.trim().length > 0) firstParaLines.push(r.trim());
    }
    description = firstParaLines.join(' ').trim();
  }

  return {
    name: title || (lines[0] || 'Pasted Recipe'),
    description,
    ingredients: ingOut,
    instructions: stepsOut,
    prepTime,
    cookTime,
    servings: inferredServings ?? 2,
    difficulty: 'medium',
    tags: ['pasted', ...equipTags],
    rating: undefined,
    notes: notes || undefined,
    image: undefined,
    isFavorite: false,
    calories: undefined,
    cuisine: 'other',
    dietaryRestrictions: [],
    nutritionInfo: undefined,
    flowChart: undefined,
    sourceType: 'manual',
    sourceUrl: undefined,
    authorName: undefined,
    videoThumbnail: undefined,
  };
}

/**
 * Draft Storage Service
 * Manages localStorage for meal planning drafts
 */

import { logger } from '../../../services/logger';

const DRAFT_PREFIX = 'meal-draft-';
const DRAFT_EXPIRY_DAYS = 7;

/**
 * Generate storage key for a meal draft
 */
export function getMealDraftKey(dateKey: string, mealType: string): string {
  return `${DRAFT_PREFIX}${dateKey}-${mealType}`;
}

/**
 * Save a meal draft to localStorage
 */
export function saveMealDraft(dateKey: string, mealType: string, value: string): void {
  try {
    const key = getMealDraftKey(dateKey, mealType);
    localStorage.setItem(key, value);
    logger.debug('DraftStorage', `Saved draft: ${key}`);
  } catch (error) {
    logger.error('DraftStorage', 'Failed to save draft:', { error });
  }
}

/**
 * Get a meal draft from localStorage
 */
export function getMealDraft(dateKey: string, mealType: string): string | null {
  try {
    const key = getMealDraftKey(dateKey, mealType);
    return localStorage.getItem(key);
  } catch (error) {
    logger.error('DraftStorage', 'Failed to get draft:', { error });
    return null;
  }
}

/**
 * Clear a specific meal draft
 */
export function clearMealDraft(dateKey: string, mealType: string): void {
  try {
    const key = getMealDraftKey(dateKey, mealType);
    localStorage.removeItem(key);
    logger.debug('DraftStorage', `Cleared draft: ${key}`);
  } catch (error) {
    logger.error('DraftStorage', 'Failed to clear draft:', { error });
  }
}

/**
 * Cleanup old meal drafts from localStorage (older than specified days)
 */
export function cleanupOldDrafts(daysOld: number = DRAFT_EXPIRY_DAYS): void {
  try {
    const today = new Date();
    const expiryDate = new Date(today);
    expiryDate.setDate(today.getDate() - daysOld);

    const keysToRemove: string[] = [];
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && key.startsWith(DRAFT_PREFIX)) {
        // Extract date from key: "meal-draft-2025-01-14-breakfast"
        const match = key.match(/meal-draft-(\d{4}-\d{2}-\d{2})/);
        if (match) {
          const draftDate = new Date(match[1]);
          if (draftDate < expiryDate) {
            keysToRemove.push(key);
          }
        }
      }
    }

    keysToRemove.forEach(key => localStorage.removeItem(key));
    if (keysToRemove.length > 0) {
      logger.debug('DraftStorage', `Cleaned up ${keysToRemove.length} old meal drafts`);
    }
  } catch (error) {
    logger.error('DraftStorage', 'Failed to cleanup old drafts:', { error });
  }
}

/**
 * Get all draft keys
 */
export function getAllDraftKeys(): string[] {
  try {
    const keys: string[] = [];
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && key.startsWith(DRAFT_PREFIX)) {
        keys.push(key);
      }
    }
    return keys;
  } catch (error) {
    logger.error('DraftStorage', 'Failed to get all draft keys:', { error });
    return [];
  }
}

/**
 * Clear all meal drafts
 */
export function clearAllDrafts(): void {
  try {
    const keys = getAllDraftKeys();
    keys.forEach(key => localStorage.removeItem(key));
    logger.debug('DraftStorage', `Cleared ${keys.length} drafts`);
  } catch (error) {
    logger.error('DraftStorage', 'Failed to clear all drafts:', { error });
  }
}

import { format } from 'date-fns';

export const toKey = (date: Date) => format(date, 'yyyy-MM-dd');

export const ensureDate = (value: Date | string): Date =>
  value instanceof Date ? value : new Date(value);

export function parseLocalDateKey(key: string): Date {
  const [y, m, d] = key.split('-').map((s) => Number(s));
  return new Date(y, (m || 1) - 1, d || 1, 0, 0, 0, 0);
}

import { useMemo } from 'react';
import { format } from 'date-fns';
import { CalendarDays, CheckCircle2 } from 'lucide-react';
import { useTasks } from '../hooks/useTasksQuery';
import type { TaskData } from '../services/types';

const Calendar: React.FC = () => {
  const { data: tasks = [] } = useTasks();

  const tasksByDate = useMemo(() => {
    const grouped = new Map<string, TaskData[]>();
    tasks.filter((task): task is TaskData => !!task.dueDate)
      .forEach((task: TaskData) => {
        const key = format(task.dueDate instanceof Date ? task.dueDate : new Date(task.dueDate), 'yyyy-MM-dd');
        const existing = grouped.get(key) ?? [];
        grouped.set(key, [...existing, task]);
      });

    return Array.from(grouped.entries())
      .sort(([a], [b]) => (a < b ? -1 : 1))
      .slice(0, 14);
  }, [tasks]);

  return (
    <div className="mx-auto flex max-w-4xl flex-col gap-6 p-6">
      <header className="flex flex-col gap-2">
        <h1 className="text-2xl font-semibold text-slate-900">Schedule</h1>
        <p className="text-sm text-slate-600">Upcoming tasks with due dates over the next two weeks.</p>
      </header>

      {tasksByDate.length === 0 ? (
        <div className="rounded-lg border border-dashed border-slate-300 bg-white p-12 text-center text-slate-500">
          Nothing scheduled yet. Add due dates from the tasks view to see items here.
        </div>
      ) : (
        <ul className="space-y-4">
          {tasksByDate.map(([key, items]) => (
            <li key={key} className="rounded-lg border border-slate-200 bg-white p-4 shadow-sm">
              <div className="flex items-center gap-2 text-sm text-slate-500">
                <CalendarDays className="h-4 w-4" />
                <span className="font-medium text-slate-900">{format(new Date(key), 'EEEE, MMM d')}</span>
              </div>
              <ul className="mt-3 space-y-2 text-sm">
                {items.map((task) => (
                  <li key={task.id} className="flex items-center justify-between rounded-md bg-slate-50 px-3 py-2">
                    <div>
                      <p className="font-medium text-slate-900">{task.title}</p>
                      {task.description && <p className="text-xs text-slate-500">{task.description}</p>}
                    </div>
                    {task.completed && <CheckCircle2 className="h-4 w-4 text-emerald-500" />}
                  </li>
                ))}
              </ul>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

