              </div>
              {captureMessage && (
                <p className="text-xs text-amber-700 bg-amber-50 border border-amber-200 rounded p-2 text-center">
                  {captureMessage}
                </p>
              )}
            </div>
          ) : (
            <div className="space-y-3">
              <p className="text-gray-600">Camera access is required to scan barcodes</p>
            </div>
          )}

          {barcodeResult && (
            <div className="bg-green-50 border border-green-200 rounded-lg p-3">
              <p className="text-sm text-green-800">
                <strong>Barcode found:</strong> {barcodeResult}
              </p>
            </div>
          )}

          <div className="text-xs text-gray-500">
            <p>Supports: UPC, EAN, Code 128, Code 39</p>
            <p>Or enter barcode manually in the add item form</p>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';

interface ReplenishModalProps {
  itemName: string;
  currentQuantity: number;
  suggestedTarget: number;
  onReplenish: (targetQuantity: number) => Promise<void>;
  onCancel: () => void;
}

export function ReplenishModal({
  itemName,
  _currentQuantity,
  suggestedTarget,
  onReplenish,
  onCancel
}: ReplenishModalProps) {
  const [targetQuantity, setTargetQuantity] = useState(String(suggestedTarget));

  const handleReplenish = async () => {
    await onReplenish(Number(targetQuantity) || 0);
  };

  return (
    <div className="mt-3 flex items-center gap-2 text-sm">
      <span className="text-gray-700">Replenish {itemName} to target quantity:</span>
      <input
        type="number"
        min={0}
        value={targetQuantity}
        onChange={(e) => setTargetQuantity(e.target.value)}
        className="w-28 rounded border border-gray-300 px-2 py-1"
      />
      <button
        className="px-3 py-1 rounded bg-blue-600 text-white hover:bg-blue-500"
        onClick={handleReplenish}
      >
        Go
      </button>
      <button
        className="px-3 py-1 rounded border border-gray-300 hover:bg-gray-50"
        onClick={onCancel}
      >
        Cancel
      </button>
    </div>
  );
}

import React from 'react';
