                { value: 'price', label: 'Best Price', icon: DollarSign, desc: 'Minimize cost' },
                { value: 'quality', label: 'Best Quality', icon: Award, desc: 'Premium items' },
                { value: 'convenience', label: 'Convenience', icon: Navigation, desc: 'Nearby stores' },
