/**
 * FilterPanel Component
 *
 * A dropdown panel for filtering tasks by priority, status, and due date.
 * Provides a clean interface for applying and clearing filters.
 */

import React from 'react';
import type { Filters } from '../types';

interface FilterPanelProps {
  /** Current filter values */
  filters: Filters;
  /** Called when any filter changes */
  onFilterChange: (filters: Filters) => void;
  /** Called when all filters should be cleared */
  onClearFilters: () => void;
  /** Whether the panel is visible */
  isVisible: boolean;
  /** Called when the panel should close */
  onClose: () => void;
}

/**
 * FilterPanel - Dropdown panel for filtering tasks
 */
export function FilterPanel({
  filters,
  onFilterChange,
  onClearFilters,
  isVisible,
  _onClose
}: FilterPanelProps) {
  if (!isVisible) {
    return null;
  }

  const handlePriorityChange = (priority: string) => {
    onFilterChange({ ...filters, priority });
  };

  const handleStatusChange = (status: string) => {
    onFilterChange({ ...filters, status });
  };

  const handleDueDateChange = (dueDate: string) => {
    onFilterChange({ ...filters, dueDate });
  };

  return (
    <div className="absolute right-0 top-12 w-64 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-lg shadow-lg z-10 p-4">
      <h3 className="font-semibold text-gray-900 dark:text-white mb-3">Filter Tasks</h3>

      <div className="space-y-3">
        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Priority
          </label>
          <select
            value={filters.priority}
            onChange={(e) => handlePriorityChange(e.target.value)}
            className="w-full px-3 py-1 text-sm border border-gray-300 dark:border-slate-600 rounded focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-slate-700 dark:text-white"
          >
            <option value="all">All Priorities</option>
            <option value="urgent">Urgent</option>
            <option value="high">High</option>
            <option value="medium">Medium</option>
            <option value="low">Low</option>
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Status
          </label>
          <select
            value={filters.status}
            onChange={(e) => handleStatusChange(e.target.value)}
            className="w-full px-3 py-1 text-sm border border-gray-300 dark:border-slate-600 rounded focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-slate-700 dark:text-white"
          >
            <option value="all">All Status</option>
            <option value="todo">To Do</option>
            <option value="done">Done</option>
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
            Due Date
          </label>
          <select
            value={filters.dueDate}
            onChange={(e) => handleDueDateChange(e.target.value)}
            className="w-full px-3 py-1 text-sm border border-gray-300 dark:border-slate-600 rounded focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-slate-700 dark:text-white"
          >
            <option value="all">All Dates</option>
            <option value="overdue">Overdue</option>
            <option value="today">Due Today</option>
            <option value="week">This Week</option>
            <option value="none">No Due Date</option>
          </select>
        </div>

        <button
          onClick={onClearFilters}
          className="w-full px-3 py-2 text-sm text-gray-600 dark:text-slate-300 hover:bg-gray-100 dark:hover:bg-slate-700 rounded transition-colors"
        >
          Clear Filters
        </button>
      </div>
    </div>
  );
}

/**
 * Kanban board view component
 */
import React from 'react';
import { format, isToday, isPast } from 'date-fns';
import { CheckCircle2, CalendarDays } from 'lucide-react';
import type { Task, Project } from '../types';

interface KanbanViewProps {
  tasks: Task[];
  projects: Project[];
  selectedProject: string;
  onToggleStatus: (taskId: string) => void;
  isUpdating: boolean;
}

export function KanbanView({
  tasks,
  projects,
  selectedProject,
  onToggleStatus,
  isUpdating
}: KanbanViewProps) {
  const kanbanColumns = [
    {
      id: 'todo',
      title: 'To Do',
      tasks: tasks.filter(
        t => t.status === 'todo' && (selectedProject === 'all' || t.projectId === selectedProject)
      )
    },
    {
      id: 'done',
      title: 'Done',
      tasks: tasks.filter(
        t => t.status === 'done' && (selectedProject === 'all' || t.projectId === selectedProject)
      )
    }
  ];

  const getPriorityStyles = (priority: string, status: string) => {
    if (status === 'done') {
      return 'bg-blue-500 border-blue-500 text-white';
    }
    switch (priority) {
      case 'urgent': return 'border-red-400 hover:border-red-500';
      case 'high': return 'border-orange-400 hover:border-orange-500';
      case 'medium': return 'border-blue-400 hover:border-blue-500';
      default: return 'border-gray-300 hover:border-gray-400';
    }
  };

  return (
    <div className="p-6">
      <div className="grid grid-cols-2 gap-6 h-full">
        {kanbanColumns.map((column) => (
          <div key={column.id} className="bg-gray-50 dark:bg-slate-800 rounded-lg p-4">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-semibold text-gray-900 dark:text-white">{column.title}</h3>
              <span className="bg-gray-200 dark:bg-slate-600 text-gray-700 dark:text-gray-300 px-2 py-1 rounded-full text-xs font-medium">
                {column.tasks.length}
              </span>
            </div>
            <div className="space-y-3 max-h-96 overflow-y-auto">
              {column.tasks.map((task) => {
                const project = projects.find(p => p.id === task.projectId);
                return (
                  <div
                    key={task.id}
                    className="bg-white dark:bg-slate-700 p-3 rounded-lg shadow-sm border border-gray-200 dark:border-slate-600 cursor-pointer hover:shadow-md transition-shadow"
                  >
                    <div className="flex items-start space-x-3">
                      <button
                        onClick={() => onToggleStatus(task.id)}
                        disabled={isUpdating}
                        className={`mt-0.5 w-4 h-4 rounded border-2 flex items-center justify-center transition-all disabled:opacity-50 ${getPriorityStyles(
                          task.priority,
                          task.status
                        )}`}
                      >
                        {task.status === 'done' && <CheckCircle2 size={10} />}
                      </button>
                      <div className="flex-1 min-w-0">
                        <div className="font-medium text-gray-900 dark:text-white text-sm mb-1">
                          {task.title}
                        </div>
                        {task.description && (
                          <div className="text-xs text-gray-600 dark:text-slate-400 mb-2">
                            {task.description}
                          </div>
                        )}
                        <div className="flex items-center space-x-2 text-xs">
                          {task.priority !== 'low' && (
                            <span
                              className={`px-2 py-0.5 rounded-full font-medium ${
                                task.priority === 'urgent'
                                  ? 'bg-red-100 text-red-800'
                                  : task.priority === 'high'
                                  ? 'bg-orange-100 text-orange-800'
                                  : 'bg-blue-100 text-blue-800'
                              }`}
                            >
                              {task.priority}
                            </span>
                          )}
                          {task.dueDate && (
                            <span
                              className={`flex items-center space-x-1 px-2 py-0.5 rounded ${
                                isPast(task.dueDate)
                                  ? 'bg-red-100 text-red-800'
                                  : isToday(task.dueDate)
                                  ? 'bg-orange-100 text-orange-800'
                                  : 'bg-gray-100 text-gray-600'
                              }`}
                            >
                              <CalendarDays size={10} />
                              <span>
                                {isPast(task.dueDate)
                                  ? 'Overdue'
                                  : isToday(task.dueDate)
                                  ? 'Today'
                                  : format(task.dueDate, 'MMM d')}
                              </span>
                            </span>
                          )}
                          {project && (
                            <span className="flex items-center space-x-1 px-2 py-0.5 bg-gray-100 dark:bg-slate-600 rounded">
                              <div
                                className="w-2 h-2 rounded-full"
                                style={{ backgroundColor: project.color }}
                              ></div>
                              <span className="text-gray-700 dark:text-gray-300">{project.name}</span>
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
              {column.tasks.length === 0 && (
                <div className="text-center py-6 text-gray-400 dark:text-slate-500">
                  <div className="text-2xl mb-2">📋</div>
                  <p className="text-sm">No {column.title.toLowerCase()} tasks</p>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * QuickAddForm Component
 *
 * A reusable quick add form component for creating new tasks.
 * Used in both the sidebar and at the bottom of task lists.
 * Supports natural language input parsing and keyboard shortcuts.
 */

import React from 'react';

interface QuickAddFormProps {
  /** Current input value */
  value: string;
  /** Called when the input value changes */
  onChange: (value: string) => void;
  /** Called when the form is submitted */
  onSubmit: () => void;
  /** Called when the form is cancelled */
  onCancel: () => void;
  /** Whether a submission is in progress */
  isLoading: boolean;
  /** Error message to display */
  error?: string;
  /** Placeholder text for the input */
  placeholder?: string;
  /** Whether to auto-focus the input */
  autoFocus?: boolean;
}

/**
 * QuickAddForm - Reusable task creation form with natural language support
 */
export function QuickAddForm({
  value,
  onChange,
  onSubmit,
  onCancel,
  isLoading,
  error,
  placeholder = "What needs to be done?",
  autoFocus = false
}: QuickAddFormProps) {
  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      onSubmit();
    }
    if (e.key === 'Escape') {
      onCancel();
    }
  };

  return (
    <div className="space-y-3">
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        className="w-full px-3 py-2 border border-gray-300 dark:border-slate-600 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 dark:bg-slate-700 dark:text-white disabled:opacity-50"
        disabled={isLoading}
        autoFocus={autoFocus}
      />
      <div className="flex space-x-2">
        <button
          onClick={onSubmit}
          disabled={isLoading}
          className="px-4 py-1.5 bg-blue-500 hover:bg-blue-600 text-white rounded-md text-sm transition-colors font-medium disabled:opacity-50"
        >
          {isLoading ? 'Adding...' : 'Add'}
        </button>
        <button
          onClick={onCancel}
          disabled={isLoading}
          className="px-4 py-1.5 text-gray-600 dark:text-slate-300 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-md text-sm transition-colors disabled:opacity-50"
        >
          Cancel
        </button>
      </div>
      {error && (
        <p className="text-xs text-red-600">{error}</p>
      )}
    </div>
  );
}

