                onProjectSelect('all');
              }}
              className={`w-full flex items-center space-x-3 px-3 py-2 rounded-md text-sm transition-colors ${
                currentView === 'kanban'
                  ? 'bg-blue-50 dark:bg-slate-700 text-blue-700 dark:text-blue-400'
                  : 'text-gray-700 dark:text-slate-300 hover:bg-gray-50 dark:hover:bg-slate-700'
              }`}
            >
              <Grid className="w-4 h-4" />
              <span>Kanban</span>
            </button>

            {/* Matrix */}
            <button
              onClick={() => {
                onViewChange('matrix');
                onProjectSelect('all');
              }}
              className={`w-full flex items-center space-x-3 px-3 py-2 rounded-md text-sm transition-colors ${
                currentView === 'matrix'
                  ? 'bg-blue-50 dark:bg-slate-700 text-blue-700 dark:text-blue-400'
                  : 'text-gray-700 dark:text-slate-300 hover:bg-gray-50 dark:hover:bg-slate-700'
              }`}
            >
              <Layers className="w-4 h-4" />
              <span>Matrix</span>
            </button>
          </nav>
        </div>

        {/* Projects Section */}
        <div className="mt-6">
          <div className="flex items-center justify-between mb-3 px-3">
            <h3 className="text-xs font-medium text-gray-500 dark:text-slate-400 uppercase tracking-wider">
              Lists
            </h3>
          </div>
          <div className="space-y-1">
            {projects.map((project) => (
              <button
                key={project.id}
                onClick={() => {
                  onProjectSelect(project.id);
                  onViewChange('inbox'); // Switch to inbox view when selecting a project
                }}
                className={`w-full flex items-center space-x-3 px-3 py-2 rounded-md text-sm transition-colors ${
                  selectedProject === project.id
                    ? 'bg-blue-50 dark:bg-slate-700 text-blue-700 dark:text-blue-400'
                    : 'text-gray-700 dark:text-slate-300 hover:bg-gray-50 dark:hover:bg-slate-700'
                }`}
              >
                <div className="w-3 h-3 rounded-full" style={{ backgroundColor: project.color }}></div>
                <span className="truncate">{project.name}</span>
                <span className="ml-auto text-xs bg-gray-200 dark:bg-slate-600 px-2 py-0.5 rounded-full">
                  {tasks.filter(t => t.projectId === project.id && t.status !== 'done').length}
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* Theme Customization */}
        <div className="mt-6">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-xs font-medium text-gray-500 dark:text-slate-400 uppercase tracking-wider">
              Themes
            </h3>
          </div>
          <div className="grid grid-cols-5 gap-2">
            {Object.entries(THEMES).map(([themeName, themeColors]) => (
              <button
                key={themeName}
                onClick={() => onThemeChange(themeName)}
                className={`w-8 h-8 rounded-lg ${themeColors.primary} hover:scale-110 transition-transform ${
                  currentTheme === themeName ? 'ring-2 ring-gray-400' : ''
                }`}
                title={`${themeName.charAt(0).toUpperCase() + themeName.slice(1)} theme`}
              />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * SubtaskForm Component
 *
 * An inline form for creating subtasks under a parent task.
 * Provides a simple input with add/cancel actions.
 */

import React from 'react';

interface SubtaskFormProps {
  /** ID of the parent task */
  parentId: string;
  /** Current input value */
  value: string;
  /** Called when the input value changes */
  onChange: (value: string) => void;
  /** Called when the form is submitted */
  onSubmit: () => void;
  /** Called when the form is cancelled */
  onCancel: () => void;
  /** Whether a submission is in progress */
  isLoading: boolean;
}

/**
 * SubtaskForm - Inline form for creating subtasks
 */
export function SubtaskForm({
  _parentId,
  value,
  onChange,
  onSubmit,
  onCancel,
  isLoading
}: SubtaskFormProps) {
  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      onSubmit();
    }
    if (e.key === 'Escape') {
      onCancel();
    }
  };

  return (
    <div className="px-6 pb-3">
      <div className="ml-10 flex items-center space-x-2">
        <input
          type="text"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Subtask name"
          disabled={isLoading}
          className="flex-1 px-3 py-2 text-sm border border-gray-300 dark:border-slate-600 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-slate-700 dark:text-white disabled:opacity-50"
          autoFocus
        />
        <button
          onClick={onSubmit}
          disabled={isLoading}
          className="px-3 py-2 bg-blue-500 hover:bg-blue-600 text-white rounded-md text-sm transition-colors disabled:opacity-50"
        >
          {isLoading ? 'Adding...' : 'Add'}
        </button>
        <button
          onClick={onCancel}
          disabled={isLoading}
          className="px-3 py-2 text-gray-600 dark:text-slate-300 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-md text-sm transition-colors disabled:opacity-50"
        >
          Cancel
        </button>
      </div>
    </div>
  );
}

/**
 * SubtaskRow Component
 *
 * Displays an individual subtask with a smaller checkbox and edit button.
 * Used within expanded parent tasks to show subtask hierarchies.
 */

import React from 'react';
import { CheckCircle2, Edit } from 'lucide-react';
import type { Task } from '../types';

interface SubtaskRowProps {
  /** The subtask to display */
  subtask: Task;
  /** Called when the subtask status is toggled */
  onToggleStatus: (id: string) => void;
  /** Called when the edit button is clicked */
  onStartEdit: (task: Task) => void;
  /** Whether an update is in progress */
  isUpdating: boolean;
}

/**
 * SubtaskRow - Individual subtask display with smaller styling
 */
export function SubtaskRow({
  subtask,
  onToggleStatus,
  onStartEdit,
  isUpdating
}: SubtaskRowProps) {
  const getPriorityBorderClass = (priority: Task['priority'], status: Task['status']) => {
    if (status === 'done') {
      return 'bg-blue-500 border-blue-500 text-white';
    }

    switch (priority) {
      case 'urgent':
        return 'border-red-400 hover:border-red-500';
      case 'high':
        return 'border-orange-400 hover:border-orange-500';
      case 'medium':
        return 'border-blue-400 hover:border-blue-500';
      default:
        return 'border-gray-300 hover:border-gray-400';
    }
  };

  return (
    <div className="group flex items-start py-2 hover:bg-gray-50 dark:hover:bg-slate-800 transition-colors rounded-md px-2">
      {/* Smaller checkbox for subtasks */}
      <button
        onClick={() => onToggleStatus(subtask.id)}
        disabled={isUpdating}
        className={`mt-1 mr-3 w-4 h-4 rounded border-2 flex items-center justify-center transition-all disabled:opacity-50 ${getPriorityBorderClass(subtask.priority, subtask.status)}`}
      >
        {subtask.status === 'done' && <CheckCircle2 size={8} />}
      </button>

      {/* Subtask title */}
      <div className="flex-1 min-w-0">
        <span className={`text-sm ${subtask.status === 'done' ? 'line-through text-gray-400' : 'text-gray-700 dark:text-gray-300'}`}>
          {subtask.title}
        </span>
      </div>

      {/* Edit button */}
      <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
        <button
          onClick={() => onStartEdit(subtask)}
          className="p-1 hover:bg-gray-200 dark:hover:bg-slate-700 rounded text-gray-400 hover:text-gray-600 transition-colors"
        >
          <Edit size={12} />
        </button>
      </div>
    </div>
  );
}

/**
 * Individual task item component with inline editing and actions
 */
import React from 'react';
import { format, isToday } from 'date-fns';
import {
  CheckCircle2,
  ChevronDown,
  ChevronRight,
  CalendarDays,
  IndentIncrease,
  Timer,
  Edit,
  MoreHorizontal
} from 'lucide-react';
import type { Task, Project } from '../types';
import { PRIORITY_FLAGS } from '../constants';
import { isOverdue } from '../services/taskHelpers';

interface TaskItemProps {
  task: Task;
  project?: Project;
  subtasks: Task[];
  isExpanded: boolean;
  isEditing: boolean;
  editText: string;
  pomodoroActive: boolean;
  onToggleStatus: () => void;
  onToggleExpansion: () => void;
  onStartEdit: () => void;
  onSaveEdit: () => void;
  onCancelEdit: () => void;
  onEditTextChange: (text: string) => void;
  onAddSubtask: () => void;
  onStartPomodoro: () => void;
  isUpdating: boolean;
}

export function TaskItem({
  task,
  project,
  subtasks,
  isExpanded,
  isEditing,
  editText,
  pomodoroActive,
  onToggleStatus,
  onToggleExpansion,
  onStartEdit,
  onSaveEdit,
  onCancelEdit,
  onEditTextChange,
  onAddSubtask,
  onStartPomodoro,
  isUpdating
}: TaskItemProps) {
  const taskIsOverdue = task.dueDate && isOverdue(task.dueDate, task.status);

  const getPriorityStyles = (priority: string): string => {
    switch (priority) {
      case 'urgent': return 'border-red-400 hover:border-red-500 hover:bg-red-50 dark:hover:bg-red-900/20';
      case 'high': return 'border-orange-400 hover:border-orange-500 hover:bg-orange-50 dark:hover:bg-orange-900/20';
      case 'medium': return 'border-blue-400 hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20';
      default: return 'border-gray-300 hover:border-gray-400 hover:bg-gray-50 dark:border-slate-600 dark:hover:bg-slate-700';
    }
  };

  return (
    <div className="mb-2">
      <div className="group flex items-start px-6 py-3 hover:bg-gray-50 dark:hover:bg-slate-800 transition-colors">
        {/* Expand/Collapse button for tasks with subtasks */}
        {subtasks.length > 0 && (
          <button
            onClick={onToggleExpansion}
            className="p-1 mr-2 hover:bg-gray-200 dark:hover:bg-slate-600 rounded transition-colors"
          >
            {isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
          </button>
        )}
        {subtasks.length === 0 && <div className="w-6"></div>}

        {/* Checkbox */}
        <button
          onClick={onToggleStatus}
          disabled={isUpdating}
          className={`mt-1 mr-4 w-5 h-5 rounded border-2 flex items-center justify-center transition-all disabled:opacity-50 ${
            task.status === 'done'
              ? 'bg-blue-500 border-blue-500 text-white'
              : getPriorityStyles(task.priority)
          }`}
        >
          {task.status === 'done' && <CheckCircle2 size={12} />}
        </button>

        {/* Task Content */}
        <div className="flex-1 min-w-0">
          <div className="flex items-center space-x-2 mb-2">
            {isEditing ? (
              <input
                type="text"
                value={editText}
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => onEditTextChange(e.target.value)}
                onKeyDown={(e: React.KeyboardEvent<HTMLInputElement>) => {
                  if (e.key === 'Enter') onSaveEdit();
                  if (e.key === 'Escape') onCancelEdit();
                }}
                onBlur={onSaveEdit}
                disabled={isUpdating}
                className="flex-1 text-sm bg-transparent border-none outline-none focus:bg-white dark:focus:bg-slate-700 rounded px-2 py-1 disabled:opacity-50"
                autoFocus
              />
            ) : (
              <span
                className={`text-base cursor-pointer font-normal ${
                  task.status === 'done'
                    ? 'line-through text-gray-400'
                    : 'text-gray-800 dark:text-white'
                } hover:bg-gray-100 dark:hover:bg-slate-700 rounded px-2 py-1 -mx-2`}
                onClick={onStartEdit}
              >
                {task.title}
              </span>
            )}

            {/* Priority flag */}
            {task.priority !== 'low' && PRIORITY_FLAGS[task.priority]}
          </div>

          {/* Task metadata */}
          {(task.description || task.dueDate || project || task.tags.length > 0) && (
            <div className="flex items-center space-x-4 text-xs text-gray-500 dark:text-slate-400 ml-2">
              {task.description && (
                <span className="truncate max-w-xs text-gray-600 dark:text-slate-400">
                  {task.description}
                </span>
              )}

              {task.dueDate && (
                <span
                  className={`flex items-center space-x-1.5 px-2 py-1 rounded ${
                    taskIsOverdue
                      ? 'text-red-600 bg-red-50'
                      : 'text-green-600 bg-green-50'
                  }`}
                >
                  <CalendarDays size={12} />
                  <span className="font-medium">
                    {isToday(task.dueDate) ? 'Today' : format(task.dueDate, 'MMM d')}
                  </span>
                </span>
              )}

              {project && (
                <span className="flex items-center space-x-1.5 px-2 py-1 bg-gray-100 dark:bg-slate-700 rounded">
                  <div
                    className="w-2.5 h-2.5 rounded-full"
                    style={{ backgroundColor: project.color }}
                  ></div>
                  <span className="text-gray-700 dark:text-gray-300 font-medium">
                    {project.name}
                  </span>
                </span>
              )}

              {task.tags.map((tag) => (
                <span
                  key={`tag-${tag}`}
                  className="inline-flex items-center px-2 py-1 rounded bg-blue-50 dark:bg-slate-700 text-blue-700 dark:text-blue-300 hover:bg-blue-100 dark:hover:bg-slate-600 transition-colors"
                >
                  <span className="text-blue-500 mr-1 text-xs">#</span>
                  <span className="font-medium">{tag}</span>
                </span>
              ))}
            </div>
          )}
        </div>

        {/* Actions */}
        <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity ml-3">
          <button
            onClick={onAddSubtask}
            className="p-1.5 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-md text-gray-400 hover:text-gray-600 dark:text-slate-400 transition-colors"
            title="Add Subtask"
          >
            <IndentIncrease size={14} />
          </button>
          <button
            onClick={onStartPomodoro}
            className={`p-1.5 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-md transition-colors ${
              pomodoroActive
                ? 'text-red-600 bg-red-100'
                : 'text-gray-400 hover:text-gray-600'
            } dark:text-slate-400`}
            title="Start Pomodoro"
          >
            <Timer size={14} />
          </button>
          <button
            onClick={onStartEdit}
            className="p-1.5 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-md text-gray-400 hover:text-gray-600 dark:text-slate-400 transition-colors"
            title="Edit"
          >
            <Edit size={14} />
          </button>
          <button className="p-1.5 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-md text-gray-400 hover:text-gray-600 dark:text-slate-400 transition-colors">
            <MoreHorizontal size={14} />
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * TaskListView Component
 *
 * Main task list rendering orchestration.
 * Handles displaying tasks, subtasks, forms, and empty states.
 */

import React from 'react';
import { Plus } from 'lucide-react';
import type { Task, Project, PomodoroTimer } from '../types';
import { TaskRow } from './TaskRow';
import { SubtaskRow } from './SubtaskRow';
import { SubtaskForm } from './SubtaskForm';
import { EmptyState } from './EmptyState';
import { getMainTasks, getSubtasks } from '../services/taskHelpers';

interface TaskListViewProps {
  /** Filtered tasks to display */
  tasks: Task[];
  /** List of all projects */
  projects: Project[];
  /** ID of task being edited */
  editingTask: string | null;
  /** Current edit text value */
  editTaskText: string;
  /** Called when edit text changes */
  onEditChange: (text: string) => void;
  /** Called when task status is toggled */
  onToggleStatus: (taskId: string) => void;
  /** Called when edit mode is started */
  onStartEdit: (task: Task) => void;
  /** Called when edit is saved */
  onSaveEdit: (taskId: string) => void;
  /** Called when edit is cancelled */
  onCancelEdit: () => void;
  /** Set of expanded task IDs */
  expandedTasks: Set<string>;
  /** Called when task expansion is toggled */
  onToggleExpansion: (taskId: string) => void;
  /** All tasks (including subtasks) for computing subtasks */
  allTasks: Task[];
  /** ID of task with active subtask form */
  activeSubtaskForm: string | null;
  /** Draft text for subtask forms */
  subtaskDrafts: Record<string, string>;
  /** Called when subtask draft text changes */
  onSubtaskDraftChange: (parentId: string, text: string) => void;
  /** Called when subtask form is submitted */
  onAddSubtask: (parentId: string) => void;
  /** Called when subtask form is opened */
  onStartSubtaskForm: (parentId: string) => void;
  /** Called when subtask form is cancelled */
  onCancelSubtaskForm: () => void;
  /** Current pomodoro timer state */
  pomodoroTimer: PomodoroTimer;
  /** Called when pomodoro is started */
  onStartPomodoro: (taskId: string) => void;
  /** Create task mutation object */
  createTaskMutation: {
    isPending: boolean;
    isError: boolean;
  };
  /** Update task mutation object */
  updateTaskMutation: {
    isPending: boolean;
  };
  /** Whether quick add form is visible */
  showQuickAdd: boolean;
  /** Current quick add input text */
  quickAddText: string;
  /** Called when quick add text changes */
  onQuickAddChange: (text: string) => void;
  /** Called when quick add form is submitted */
  onQuickAddSubmit: () => void;
  /** Called when quick add form is cancelled */
  onQuickAddCancel: () => void;
  /** Current view type for empty state */
  currentView: 'today' | 'inbox' | 'upcoming' | 'kanban' | 'matrix';
}

/**
 * TaskListView - Orchestrates rendering of task list with all interactions
 */
export function TaskListView({
  tasks,
  projects,
  editingTask,
  editTaskText,
  onEditChange,
  onToggleStatus,
  onStartEdit,
  onSaveEdit,
  onCancelEdit,
  expandedTasks,
  onToggleExpansion,
  allTasks,
  activeSubtaskForm,
  subtaskDrafts,
  onSubtaskDraftChange,
  onAddSubtask,
  onStartSubtaskForm,
  onCancelSubtaskForm,
  pomodoroTimer,
  onStartPomodoro,
  createTaskMutation,
  updateTaskMutation,
  showQuickAdd,
  quickAddText,
  onQuickAddChange,
  onQuickAddSubmit,
  onQuickAddCancel,
  currentView
}: TaskListViewProps) {
  const mainTasks = getMainTasks(tasks);

  return (
    <div className="py-4">
      {/* Task List */}
      {mainTasks.map((task) => {
        const project = projects.find(p => p.id === task.projectId);
        const subtasks = getSubtasks(allTasks, task.id);
        const isExpanded = expandedTasks.has(task.id);

        return (
          <div key={task.id} className="mb-2">
            {/* Main Task Row */}
            <TaskRow
              task={task}
              project={project}
              isEditing={editingTask === task.id}
              editText={editTaskText}
              onEditChange={onEditChange}
              onToggleStatus={onToggleStatus}
              onStartEdit={onStartEdit}
              onSaveEdit={onSaveEdit}
              onCancelEdit={onCancelEdit}
              onStartPomodoro={onStartPomodoro}
              onAddSubtask={onStartSubtaskForm}
              onToggleExpansion={onToggleExpansion}
              pomodoroTimer={pomodoroTimer}
              isUpdating={updateTaskMutation.isPending}
              isExpanded={isExpanded}
              hasSubtasks={subtasks.length > 0}
            />

            {/* Subtask Form */}
            {activeSubtaskForm === task.id && (
              <SubtaskForm
                parentId={task.id}
                value={subtaskDrafts[task.id] || ''}
                onChange={(text) => onSubtaskDraftChange(task.id, text)}
                onSubmit={() => onAddSubtask(task.id)}
                onCancel={onCancelSubtaskForm}
                isLoading={createTaskMutation.isPending}
              />
            )}

            {/* Subtasks */}
            {isExpanded && subtasks.length > 0 && (
              <div className="ml-10 border-l-2 border-gray-200 dark:border-slate-600 pl-4">
                {subtasks.map((subtask) => (
                  <SubtaskRow
                    key={subtask.id}
                    subtask={subtask}
                    onToggleStatus={onToggleStatus}
                    onStartEdit={onStartEdit}
                    isUpdating={updateTaskMutation.isPending}
                  />
                ))}
              </div>
            )}
          </div>
        );
      })}

      {/* Empty State */}
      {mainTasks.length === 0 && (
        <EmptyState currentView={currentView} />
      )}

      {/* Quick Add at Bottom */}
      <div className="px-6 py-4 border-t border-gray-100 dark:border-slate-700 bg-gray-50 dark:bg-slate-800">
        {!showQuickAdd ? (
          <button
            onClick={onQuickAddSubmit}
            className="flex items-center space-x-2 text-blue-600 hover:text-blue-700 dark:text-blue-400 transition-colors text-sm font-medium"
          >
            <Plus size={16} />
            <span>Add task</span>
          </button>
        ) : (
          <div className="space-y-3">
            <input
              type="text"
              value={quickAddText}
              onChange={(e) => onQuickAddChange(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') onQuickAddSubmit();
                if (e.key === 'Escape') onQuickAddCancel();
              }}
              placeholder="What needs to be done?"
              disabled={createTaskMutation.isPending}
              className="w-full px-4 py-3 text-sm border border-gray-300 dark:border-slate-600 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 dark:bg-slate-700 dark:text-white disabled:opacity-50"
              autoFocus
            />
            <div className="flex items-center space-x-3">
              <button
                onClick={onQuickAddSubmit}
                disabled={createTaskMutation.isPending}
                className="px-4 py-2 bg-blue-500 hover:bg-blue-600 text-white rounded-md transition-colors font-medium disabled:opacity-50"
              >
                {createTaskMutation.isPending ? 'Adding...' : 'Add task'}
              </button>
              <button
                onClick={onQuickAddCancel}
                disabled={createTaskMutation.isPending}
                className="px-4 py-2 text-gray-600 dark:text-slate-300 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-md transition-colors disabled:opacity-50"
              >
                Cancel
              </button>
              <span className="text-gray-500 dark:text-slate-400 text-xs">
                Try natural language like "Call mom today"
              </span>
            </div>
            {createTaskMutation.isError && (
              <p className="text-xs text-red-600">Failed to create task. Please try again.</p>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * TaskRow Component
 *
 * Displays an individual task row with all interactions.
 * Handles checkbox, priority, editing, metadata display, and action buttons.
 */

import React from 'react';
import {
  CheckCircle2,
  Edit,
  Timer,
  MoreHorizontal,
  IndentIncrease,
  ChevronDown,
  ChevronRight,
  CalendarDays
} from 'lucide-react';
import { format, isToday } from 'date-fns';
import type { Task, Project, PomodoroTimer } from '../types';
import { PRIORITY_FLAGS } from '../constants';
import { isOverdue } from '../services/taskHelpers';

interface TaskRowProps {
  /** The task to display */
  task: Task;
  /** The project this task belongs to */
  project?: Project;
  /** Whether this task is being edited */
  isEditing: boolean;
  /** Current edit text value */
  editText: string;
  /** Called when edit text changes */
  onEditChange: (text: string) => void;
  /** Called when task status is toggled */
  onToggleStatus: (taskId: string) => void;
  /** Called when edit mode is started */
  onStartEdit: (task: Task) => void;
  /** Called when edit is saved */
  onSaveEdit: (taskId: string) => void;
  /** Called when edit is cancelled */
  onCancelEdit: () => void;
  /** Called when pomodoro is started for this task */
  onStartPomodoro: (taskId: string) => void;
  /** Called when add subtask button is clicked */
  onAddSubtask: (taskId: string) => void;
  /** Called when expand/collapse button is clicked */
  onToggleExpansion: (taskId: string) => void;
  /** Current pomodoro timer state */
  pomodoroTimer: PomodoroTimer;
  /** Whether an update is in progress */
  isUpdating: boolean;
  /** Whether this task is expanded (showing subtasks) */
  isExpanded: boolean;
  /** Whether this task has subtasks */
  hasSubtasks: boolean;
}

/**
 * TaskRow - Individual task display with full interaction support
 */
export function TaskRow({
  task,
  project,
  isEditing,
  editText,
  onEditChange,
  onToggleStatus,
  onStartEdit,
  onSaveEdit,
  onCancelEdit,
  onStartPomodoro,
  onAddSubtask,
  onToggleExpansion,
  pomodoroTimer,
  isUpdating,
  isExpanded,
  hasSubtasks
}: TaskRowProps): React.ReactElement {
  const taskIsOverdue = task.dueDate && isOverdue(task.dueDate, task.status);

  const getPriorityBorderClass = (): string => {
    if (task.status === 'done') {
      return 'bg-blue-500 border-blue-500 text-white';
    }

    switch (task.priority) {
      case 'urgent':
        return 'border-red-400 hover:border-red-500 hover:bg-red-50 dark:hover:bg-red-900/20';
      case 'high':
        return 'border-orange-400 hover:border-orange-500 hover:bg-orange-50 dark:hover:bg-orange-900/20';
      case 'medium':
        return 'border-blue-400 hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20';
      default:
        return 'border-gray-300 hover:border-gray-400 hover:bg-gray-50 dark:border-slate-600 dark:hover:bg-slate-700';
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>): void => {
    if (e.key === 'Enter') {
      onSaveEdit(task.id);
    }
    if (e.key === 'Escape') {
      onCancelEdit();
    }
  };

  return (
    <div className="group flex items-start px-6 py-3 hover:bg-gray-50 dark:hover:bg-slate-800 transition-colors">
      {/* Expand/Collapse button for tasks with subtasks */}
      {hasSubtasks ? (
        <button
          onClick={() => onToggleExpansion(task.id)}
          className="p-1 mr-2 hover:bg-gray-200 dark:hover:bg-slate-600 rounded transition-colors"
        >
          {isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
        </button>
      ) : (
        <div className="w-6"></div>
      )}

      {/* Checkbox */}
      <button
        onClick={() => onToggleStatus(task.id)}
        disabled={isUpdating}
        className={`mt-1 mr-4 w-5 h-5 rounded border-2 flex items-center justify-center transition-all disabled:opacity-50 ${getPriorityBorderClass()}`}
      >
        {task.status === 'done' && <CheckCircle2 size={12} />}
      </button>

      {/* Task Content */}
      <div className="flex-1 min-w-0">
        {/* Title and Priority */}
        <div className="flex items-center space-x-2 mb-2">
          {isEditing ? (
            <input
              type="text"
              value={editText}
              onChange={(e) => onEditChange(e.target.value)}
              onKeyDown={handleKeyDown}
              onBlur={() => onSaveEdit(task.id)}
              disabled={isUpdating}
              className="flex-1 text-sm bg-transparent border-none outline-none focus:bg-white dark:focus:bg-slate-700 rounded px-2 py-1 disabled:opacity-50"
              autoFocus
            />
          ) : (
            <span
              className={`text-base cursor-pointer font-normal ${
                task.status === 'done'
                  ? 'line-through text-gray-400'
                  : 'text-gray-800 dark:text-white'
              } hover:bg-gray-100 dark:hover:bg-slate-700 rounded px-2 py-1 -mx-2`}
              onClick={() => onStartEdit(task)}
            >
              {task.title}
            </span>
          )}

          {/* Priority flag */}
          {task.priority !== 'low' && PRIORITY_FLAGS[task.priority]}
        </div>

        {/* Task metadata */}
        {(task.description ?? false) || (task.dueDate ?? false) || (project ?? false) || (task.tags.length > 0) && (
          <div className="flex items-center space-x-4 text-xs text-gray-500 dark:text-slate-400 ml-2">
            {task.description && (
              <span className="truncate max-w-xs text-gray-600 dark:text-slate-400">
                {task.description}
              </span>
            )}

            {task.dueDate && (
              <span
                className={`flex items-center space-x-1.5 px-2 py-1 rounded ${
                  taskIsOverdue ? 'text-red-600 bg-red-50' : 'text-green-600 bg-green-50'
                }`}
              >
                <CalendarDays size={12} />
                <span className="font-medium">
                  {isToday(task.dueDate) ? 'Today' : format(task.dueDate, 'MMM d')}
                </span>
              </span>
            )}

            {project && (
              <span className="flex items-center space-x-1.5 px-2 py-1 bg-gray-100 dark:bg-slate-700 rounded">
                <div
                  className="w-2.5 h-2.5 rounded-full"
                  style={{ backgroundColor: project.color ?? 'defaultColor' }}
                ></div>
                <span className="text-gray-700 dark:text-gray-300 font-medium">{project.name}</span>
              </span>
            )}

            {task.tags.map((tag, index) => (
              <span
                key={index}
                className="inline-flex items-center px-2 py-1 rounded bg-blue-50 dark:bg-slate-700 text-blue-700 dark:text-blue-300 hover:bg-blue-100 dark:hover:bg-slate-600 transition-colors"
              >
                <span className="text-blue-500 mr-1 text-xs">#</span>
                <span className="font-medium">{tag}</span>
              </span>
            ))}
          </div>
        )}
      </div>

      {/* Actions */}
      <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity ml-3">
        <button
          onClick={() => onAddSubtask(task.id)}
          className="p-1.5 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-md text-gray-400 hover:text-gray-600 dark:text-slate-400 transition-colors"
          title="Add Subtask"
        >
          <IndentIncrease size={14} />
        </button>
        <button
          onClick={() => onStartPomodoro(task.id)}
          className={`p-1.5 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-md transition-colors ${
            pomodoroTimer.taskId === task.id ? 'text-red-600 bg-red-100' : 'text-gray-400 hover:text-gray-600'
          } dark:text-slate-400`}
          title="Start Pomodoro"
        >
          <Timer size={14} />
        </button>
        <button
          onClick={() => onStartEdit(task)}
          className="p-1.5 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-md text-gray-400 hover:text-gray-600 dark:text-slate-400 transition-colors"
          title="Edit"
        >
          <Edit size={14} />
        </button>
        <button className="p-1.5 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-md text-gray-400 hover:text-gray-600 dark:text-slate-400 transition-colors">
          <MoreHorizontal size={14} />
        </button>
      </div>
    </div>
  );
}

import type { TaskData } from '../../services/types';
import type { Project, Task } from '../types';
import { parseQuickAdd } from '../services/taskHelpers';

/**
 * Mutation hooks interface expected by useTaskEditing
 */
export interface TaskMutations {
  createTaskMutation: {
    mutate: (data: Partial<TaskData>, options?: { onSuccess?: () => void }) => void;
    isPending: boolean;
  };
  updateTaskMutation: {
    mutate: (data: { id: string; updates: Partial<TaskData> }) => void;
    isPending: boolean;
  };
}

/**
 * Interface for task editing state (from useTaskModals)
 */
export interface TaskEditingState {
  quickAddText: string;
  setQuickAddText: (text: string) => void;
  closeQuickAdd: () => void;
  editTaskText: string;
  setEditTaskText: (text: string) => void;
  editingTask: string | null;
  setEditingTask: (id: string | null) => void;
  openTaskEdit: (taskId: string, taskTitle: string) => void;
  closeTaskEdit: () => void;
}

/**
 * Interface for subtask management state (from useTaskExpansion)
 */
export interface SubtaskState {
  subtaskDrafts: Record<string, string>;
  setSubtaskDraft: (taskId: string, text: string) => void;
  clearSubtaskDraft: (taskId: string) => void;
  getSubtaskDraft: (taskId: string) => string;
  setActiveSubtaskForm: (taskId: string | null) => void;
}

/**
 * Custom hook to manage task editing business logic
 * Provides functions for creating, updating, and managing tasks and subtasks
 */
export function useTaskEditing(
  mutations: TaskMutations,
  editingState: TaskEditingState,
  subtaskState: SubtaskState,
  apiTasks: TaskData[],
  projects: Project[]
): {
  quickAddTask: () => Promise<void>;
  startEditingTask: (task: Task) => void;
  saveTaskEdit: (taskId: string) => Promise<void>;
  cancelTaskEdit: () => void;
  addSubtask: (parentId: string) => Promise<void>;
  toggleTaskStatus: (taskId: string) => Promise<void>;
} {
  const { createTaskMutation, updateTaskMutation } = mutations;

  /**
   * Quick add a new task with natural language parsing
   * Parses priority, due date, project, and tags from text
   */
  const quickAddTask = async (): Promise<void> => {
    if (!editingState.quickAddText.trim()) return;

    const parsed = parseQuickAdd(editingState.quickAddText, projects);

    createTaskMutation.mutate(
      {
        title: parsed.title,
        description: '',
        priority: parsed.priority,
        status: 'todo',
        estimated_time: 25,
        actual_time: 0,
        due_date: parsed.dueDate ? parsed.dueDate.toISOString() : null,
        project_id: parsed.projectId ?? null,
        tags: parsed.tags,
        category: 'work',
      },
      {
        onSuccess: () => {
          editingState.setQuickAddText('');
          editingState.closeQuickAdd();
        },
      }
    );
  };

  /**
   * Start editing a task
   * Opens edit mode with the task's current title
   */
  const startEditingTask = (task: Task): void => {
    editingState.openTaskEdit(task.id, task.title);
  };

  /**
   * Save changes to an edited task
   * Parses updated text and merges with existing task data
   */
  const saveTaskEdit = async (taskId: string): Promise<void> => {
    if (editingState.editTaskText.trim()) {
      const parsed = parseQuickAdd(editingState.editTaskText, projects);
      const currentTask = apiTasks.find(t => t.id === taskId);

      if (currentTask) {
        updateTaskMutation.mutate({
          id: taskId,
          updates: {
            title: parsed.title,
            priority: parsed.priority,
            due_date: parsed.dueDate
              ? parsed.dueDate.toISOString()
              : currentTask.due_date,
            project_id: parsed.projectId ?? currentTask.project_id,
            tags: parsed.tags.length > 0 ? parsed.tags : currentTask.tags,
          },
        });
      }
    }
    editingState.closeTaskEdit();
  };

  /**
   * Cancel task editing without saving
   */
  const cancelTaskEdit = (): void => {
    editingState.closeTaskEdit();
  };

  /**
   * Add a subtask to a parent task
   * Creates a new task with the parent_id set
   */
  const addSubtask = async (parentId: string): Promise<void> => {
    const draft = subtaskState.getSubtaskDraft(parentId).trim();
    if (!draft) return;

    createTaskMutation.mutate(
      {
        title: draft,
        description: '',
        priority: 'medium',
        status: 'todo',
        estimated_time: 25,
        actual_time: 0,
        tags: [],
        category: 'work',
        parent_id: parentId,
        due_date: null,
        project_id: null,
      },
      {
        onSuccess: () => {
          subtaskState.clearSubtaskDraft(parentId);
          subtaskState.setActiveSubtaskForm(null);
        },
      }
    );
  };

  /**
   * Toggle task completion status
   * Marks task as done/todo and updates completed_at timestamp
   */
  const toggleTaskStatus = async (taskId: string): Promise<void> => {
    const task = apiTasks.find(t => t.id === taskId);
    if (task) {
      updateTaskMutation.mutate({
        id: taskId,
        updates: {
          status: task.status === 'done' ? 'todo' : 'done',
          completed_at: task.status === 'done' ? null : new Date().toISOString(),
        },
      });
    }
  };

  return {
    quickAddTask,
    startEditingTask,
    saveTaskEdit,
    cancelTaskEdit,
    addSubtask,
    toggleTaskStatus,
  };
}

import { useState } from 'react';

/**
 * Custom hook to manage task expansion and subtask draft states
 * Handles which tasks are expanded and temporary subtask input text
 */
export function useTaskExpansion() {
  // Track which tasks are expanded
  const [expandedTasks, setExpandedTasks] = useState<Set<string>>(new Set());

  // Track subtask draft text for each parent task
  const [subtaskDrafts, setSubtaskDrafts] = useState<Record<string, string>>({});

  /**
   * Toggle expansion state for a task
   */
  const toggleTaskExpansion = (taskId: string) => {
    setExpandedTasks(prev => {
      const newSet = new Set(prev);
      if (newSet.has(taskId)) {
        newSet.delete(taskId);
      } else {
        newSet.add(taskId);
      }
      return newSet;
    });
  };

  /**
   * Set the draft text for a subtask
   */
  const setSubtaskDraft = (taskId: string, text: string) => {
    setSubtaskDrafts(prev => ({ ...prev, [taskId]: text }));
  };

  /**
   * Clear the draft text for a subtask
   */
  const clearSubtaskDraft = (taskId: string) => {
    setSubtaskDrafts(prev => {
      const newDrafts = { ...prev };
      delete newDrafts[taskId];
      return newDrafts;
    });
  };

  /**
   * Get the draft text for a specific task
   */
  const getSubtaskDraft = (taskId: string): string => {
    return subtaskDrafts[taskId] || '';
  };

  return {
    // Expansion state
    expandedTasks,
    toggleTaskExpansion,

    // Subtask drafts
    subtaskDrafts,
    setSubtaskDraft,
    clearSubtaskDraft,
    getSubtaskDraft,
  };
}

/**
 * Task filtering and search logic
 */
import { isToday, isPast } from 'date-fns';
import type { Task, Filters } from '../types';

export function applyFilters(taskList: Task[], filters: Filters, searchQuery: string): Task[] {
  let filtered = taskList;

  // Search filter
  if (searchQuery.trim()) {
    filtered = filtered.filter(task =>
      task.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      task.description?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      task.tags.some(tag => tag.toLowerCase().includes(searchQuery.toLowerCase()))
    );
  }

  // Priority filter
  if (filters.priority !== 'all') {
    filtered = filtered.filter(task => task.priority === filters.priority);
  }

  // Status filter
  if (filters.status !== 'all') {
    filtered = filtered.filter(task => task.status === filters.status);
  }

  // Due date filter
  if (filters.dueDate !== 'all') {
    const now = new Date();
    const startOfWeekDate = new Date(now.setDate(now.getDate() - now.getDay()));
    const endOfWeekDate = new Date(now.setDate(startOfWeekDate.getDate() + 6));

    filtered = filtered.filter(task => {
      if (!task.dueDate && filters.dueDate === 'none') return true;
      if (!task.dueDate) return false;

      switch (filters.dueDate) {
        case 'overdue': return isPast(task.dueDate) && task.status !== 'done';
        case 'today': return isToday(task.dueDate);
        case 'week': return task.dueDate >= startOfWeekDate && task.dueDate <= endOfWeekDate;
        default: return true;
      }
    });
  }

  return filtered;
}

/**
 * EnhancedGeographicMap - Map with mountains, rivers, terrain, and administrative boundaries
 * Includes toggleable layers for enhanced geographic visualization
 */

import React from 'react';
import { geoPath, geoNaturalEarth1 } from 'd3-geo';
import { Mountain, Waves, MapPin, Layers, Droplets, ZoomIn, ZoomOut, Maximize2 } from 'lucide-react';
import type { VisitStatus } from '../types';
import { worldRivers, worldMountains, worldLakes, worldDeserts } from '../data/comprehensiveGeography';
import { logger } from '../../services/logger';

type EnhancedGeographicMapProps = {
  visitedCountries: Record<string, VisitStatus>;
  onCountryClick: (countryCode: string) => void;
};

interface CountryProperties {
  name: string;
  iso_a2: string;
  iso_a3: string;
}

interface CountryFeature {
  type: 'Feature';
  id: string;
  properties: CountryProperties;
  geometry: {
    type: string;
    coordinates: unknown;
  };
}

interface LayerToggles {
  showRivers: boolean;
  showMountains: boolean;
  showLakes: boolean;
  showDeserts: boolean;
  showTerrain: boolean;
  showStates: boolean;
  showLabels: boolean;
}

const EnhancedGeographicMap: React.FC<EnhancedGeographicMapProps> = ({
  visitedCountries,
  onCountryClick,
}) => {
  const [countries, setCountries] = React.useState<CountryFeature[]>([]);
  const [statesData, setStatesData] = React.useState<Array<{ geometry: unknown; properties?: Record<string, unknown> }>>([]);
  const [loading, setLoading] = React.useState(true);
  const [loadingStates, setLoadingStates] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const [hoveredCountry, setHoveredCountry] = React.useState<string | null>(null);
  const [showList, setShowList] = React.useState(false);
  const [showLayerPanel, setShowLayerPanel] = React.useState(true);
  const [zoom, setZoom] = React.useState(1);
  const [pan, setPan] = React.useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = React.useState(false);
  const [dragStart, setDragStart] = React.useState({ x: 0, y: 0 });
  const [layers, setLayers] = React.useState<LayerToggles>({
    showRivers: true,
    showMountains: true,
    showLakes: true,
    showDeserts: true,
    showTerrain: false,
    showStates: false,
    showLabels: true,
  });
  const svgRef = React.useRef<SVGSVGElement>(null);

  const width = 960;
  const height = 500;

  // Natural Earth projection with zoom and pan
  const projection = geoNaturalEarth1()
    .scale((width / 6.5) * zoom)
    .translate([width / 2 + pan.x, height / 2 + pan.y]);

  const pathGenerator = geoPath().projection(projection);

  // Load countries data
  React.useEffect(() => {
    const loadMapData = async (): Promise<void> => {
      try {
        setLoading(true);
        const response = await fetch('https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_110m_admin_0_countries.geojson');

        if (!response.ok) {
          throw new Error(`Failed to fetch map data: ${response.status}`);
        }

        const geoJsonData: { features?: Array<{ id?: string; properties?: Record<string, unknown>; geometry?: unknown }> } = await response.json() as { features?: Array<{ id?: string; properties?: Record<string, unknown>; geometry?: unknown }> };

        if (!geoJsonData?.features) {
          throw new Error('Invalid GeoJSON data');
        }

        const countryFeatures = geoJsonData.features
          .map((f: { id?: string; properties?: Record<string, unknown>; geometry?: unknown }) => {
            const iso_a2 = (f.properties?.ISO_A2 ?? f.properties?.iso_a2 ?? '') as string;
            const iso_a3 = (f.properties?.ISO_A3 ?? f.properties?.iso_a3 ?? '') as string;
            const name = (f.properties?.NAME ?? f.properties?.name ?? f.properties?.ADMIN ?? 'Unknown') as string;

            return {
              type: 'Feature' as const,
              id: f.id ?? iso_a2 ?? `country-${Math.random()}`,
              properties: {
                name: name,
                iso_a2: iso_a2,
                iso_a3: iso_a3,
              },
              geometry: f.geometry,
            };
          })
          .filter((f: { properties: { iso_a2: string }; geometry?: unknown }) => {
            const hasValidCode = f.properties.iso_a2 &&
                                 f.properties.iso_a2.length === 2 &&
                                 f.properties.iso_a2 !== '-99';
            const geometryObj = f.geometry as { type?: string } | undefined;
            const hasValidGeometry = geometryObj &&
                                    (geometryObj.type === 'Polygon' || geometryObj.type === 'MultiPolygon');
            return hasValidCode && hasValidGeometry;
          }) as CountryFeature[];

        setCountries(countryFeatures.sort((a, b) =>
          a.properties.name.localeCompare(b.properties.name)
        ));
        setError(null);
        setLoading(false);
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Failed to load map data';
        logger.error('Error loading map data:', { err });
        setError(errorMessage);
        setLoading(false);
      }
    };

    void loadMapData();
  }, []);

  // Load US states and province boundaries
  React.useEffect(() => {
    const loadStateBoundaries = async (): Promise<void> => {
      if (!layers.showStates || statesData.length > 0 || loadingStates) return;

      try {
        setLoadingStates(true);
        // Load US states GeoJSON from Natural Earth
        const response = await fetch('https://raw.githubusercontent.com/nvkelso/natural-earth-vector/master/geojson/ne_110m_admin_1_states_provinces.geojson');

        if (response.ok) {
          const data = await response.json() as { features?: Array<{ geometry: unknown; properties?: Record<string, unknown> }> };
          setStatesData(data.features ?? []);
          logger.debug('EnhancedGeographicMap', `Loaded ${data.features?.length ?? 0} state/province boundaries`);
        }
      } catch (err) {
        logger.error('Error loading state boundaries:', { err });
      } finally {
        setLoadingStates(false);
      }
    };

    void loadStateBoundaries();
  }, [layers.showStates, statesData.length, loadingStates]);

  const toggleLayer = (layer: keyof LayerToggles): void => {
    setLayers(prev => ({ ...prev, [layer]: !prev[layer] }));
  };

  // Zoom controls
  const handleZoomIn = React.useCallback((): void => setZoom(prev => Math.min(prev * 1.5, 8)), []);
  const handleZoomOut = React.useCallback((): void => setZoom(prev => Math.max(prev / 1.5, 1)), []);
  const handleReset = React.useCallback((): void => {
    setZoom(1);
    setPan({ x: 0, y: 0 });
  }, []);

  // Pan controls
  const handleMouseDown = (e: React.MouseEvent): void => {
    if (e.button === 0 && (e.target as HTMLElement).tagName === 'rect') {
      setIsDragging(true);
      setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent): void => {
    if (isDragging) {
      setPan({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y,
      });
    }
  };

  const handleMouseUp = (): void => setIsDragging(false);

  // Keyboard shortcuts for zoom
  React.useEffect(() => {
    const handleKeyPress = (e: KeyboardEvent): void => {
      if (e.key === '=' || e.key === '+') {
        handleZoomIn();
      } else if (e.key === '-' || e.key === '_') {
        handleZoomOut();
      } else if (e.key === '0') {
        handleReset();
      }
    };

    window.addEventListener('keydown', handleKeyPress);
    return (): void => window.removeEventListener('keydown', handleKeyPress);
  }, [handleZoomIn, handleZoomOut, handleReset]);

  // Mouse wheel zoom handler with zoom to cursor position
  const handleWheel = (e: React.WheelEvent<SVGSVGElement>): void => {
    e.preventDefault();
    e.stopPropagation();

    const svg = svgRef.current;
    if (!svg) return;

    // Get mouse position relative to SVG
    const rect = svg.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    // Calculate the point in the map coordinates (before zoom)
    const pointX = (mouseX - width / 2 - pan.x) / zoom;
    const pointY = (mouseY - height / 2 - pan.y) / zoom;

    // Calculate new zoom level
    const zoomFactor = e.deltaY < 0 ? 1.5 : 1 / 1.5;
    const newZoom = e.deltaY < 0
      ? Math.min(zoom * zoomFactor, 8)
      : Math.max(zoom * zoomFactor, 1);

    // Calculate new pan to keep the point under the mouse
    const newPanX = mouseX - width / 2 - pointX * newZoom;
    const newPanY = mouseY - height / 2 - pointY * newZoom;

    setZoom(newZoom);
    setPan({ x: newPanX, y: newPanY });
  };

  const getCountryFill = (countryCode: string, isHovered: boolean): string => {
    const hasVisited = visitedCountries[countryCode];

    if (isHovered) {
      // Highlighted state: darker green for visited, light gray for unvisited
      return hasVisited ? '#16A34A' : '#9CA3AF';
    }

    // Google Maps style: soft green for visited, very light beige/tan for unvisited
    return hasVisited ? '#86EFAC' : '#F3F1E8';
  };

  // Project lat/lon to screen coordinates
  const project = (lat: number, lon: number): [number, number] | null => {
    const coords = projection([lon, lat]);
    return coords ?? null;
  };

  const visitedCount = Object.keys(visitedCountries).length;

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[500px] bg-white">
        <div className="text-center">
          <div className="h-12 w-12 animate-spin rounded-full border-4 border-blue-500 border-t-transparent mx-auto mb-4" />
          <p className="text-gray-600">Loading enhanced map...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center min-h-[500px] bg-white">
        <div className="text-center max-w-md">
          <div className="text-red-500 text-4xl mb-4">⚠️</div>
          <h3 className="text-lg font-semibold text-gray-900 mb-2">Failed to Load Map</h3>
          <p className="text-gray-600 mb-4">{error}</p>
          <button
            onClick={() => window.location.reload()}
            className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
          >
            Reload Page
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white min-h-screen">
      {/* Header */}
      <div className="bg-white border-b border-gray-200 py-4 px-6">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <h1 className="text-2xl font-bold text-gray-900">Travel Map - Enhanced</h1>
          <div className="flex items-center gap-3">
            <div className="text-lg font-semibold text-blue-600">
              {visitedCount} {visitedCount === 1 ? 'country' : 'countries'} visited
            </div>

            {/* Zoom Controls */}
            <div className="flex items-center gap-1 border border-gray-300 rounded-lg p-1">
              <button
                onClick={handleZoomOut}
                className="p-1.5 hover:bg-gray-100 rounded transition-colors"
                title="Zoom Out (-)"
              >
                <ZoomOut className="h-4 w-4 text-gray-700" />
              </button>
              <div className="px-2 py-1 text-xs font-medium text-gray-700 min-w-[50px] text-center">
                {Math.round(zoom * 100)}%
              </div>
              <button
                onClick={handleZoomIn}
                className="p-1.5 hover:bg-gray-100 rounded transition-colors"
                title="Zoom In (+)"
              >
                <ZoomIn className="h-4 w-4 text-gray-700" />
              </button>
              <button
                onClick={handleReset}
                className="p-1.5 hover:bg-gray-100 rounded transition-colors border-l border-gray-300"
                title="Reset View (0)"
              >
                <Maximize2 className="h-4 w-4 text-gray-700" />
              </button>
            </div>

            <button
              onClick={() => setShowLayerPanel(!showLayerPanel)}
              className="px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 transition-colors flex items-center gap-2"
            >
              <Layers className="h-4 w-4" />
              Layers
            </button>
            <button
              onClick={() => setShowList(!showList)}
              className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
            >
              {showList ? 'Hide List' : 'Show List'}
            </button>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto p-6">
        <div className="flex gap-6">
          {/* Map Container */}
          <div className={`${showList ? 'w-4/5' : 'w-full'} transition-all duration-300`}>
            <div className="bg-white rounded-lg border border-gray-200 p-4 relative">
              {/* Layer Panel */}
              {showLayerPanel && (
                <div className="absolute top-4 right-4 bg-white border border-gray-200 rounded-lg shadow-lg p-4 z-10 w-72">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="font-semibold text-gray-900">Geographic Layers</h3>
                    <button
                      onClick={() => setShowLayerPanel(false)}
                      className="text-gray-400 hover:text-gray-600"
                    >
                      ×
                    </button>
                  </div>
                  <div className="space-y-2.5">
                    <label className="flex items-center gap-2 cursor-pointer hover:bg-gray-50 p-1.5 rounded">
                      <input
                        type="checkbox"
                        checked={layers.showRivers}
                        onChange={() => toggleLayer('showRivers')}
                        className="w-4 h-4 text-blue-600 rounded"
                      />
                      <Waves className="h-4 w-4 text-blue-500" />
                      <span className="text-sm font-medium">Rivers ({worldRivers.length})</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer hover:bg-gray-50 p-1.5 rounded">
                      <input
                        type="checkbox"
                        checked={layers.showMountains}
                        onChange={() => toggleLayer('showMountains')}
                        className="w-4 h-4 text-blue-600 rounded"
                      />
                      <Mountain className="h-4 w-4 text-amber-800" />
                      <span className="text-sm font-medium">Mountains ({worldMountains.reduce((sum, r) => sum + (r.peaks?.length ?? 0), 0)} peaks)</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer hover:bg-gray-50 p-1.5 rounded">
                      <input
                        type="checkbox"
                        checked={layers.showLakes}
                        onChange={() => toggleLayer('showLakes')}
                        className="w-4 h-4 text-blue-600 rounded"
                      />
                      <Droplets className="h-4 w-4 text-cyan-500" />
                      <span className="text-sm font-medium">Lakes ({worldLakes.length})</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer hover:bg-gray-50 p-1.5 rounded">
                      <input
                        type="checkbox"
                        checked={layers.showDeserts}
                        onChange={() => toggleLayer('showDeserts')}
                        className="w-4 h-4 text-blue-600 rounded"
                      />
                      <div className="h-4 w-4 bg-yellow-200 rounded"></div>
                      <span className="text-sm font-medium">Deserts ({worldDeserts.length})</span>
                    </label>
                    <div className="border-t border-gray-200 my-2"></div>
                    <label className="flex items-center gap-2 cursor-pointer hover:bg-gray-50 p-1.5 rounded">
                      <input
                        type="checkbox"
                        checked={layers.showStates}
                        onChange={() => toggleLayer('showStates')}
                        className="w-4 h-4 text-blue-600 rounded"
                      />
                      <MapPin className="h-4 w-4 text-gray-500" />
                      <span className="text-sm font-medium">States/Provinces</span>
                      {loadingStates && <span className="text-xs text-gray-400">(loading...)</span>}
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer hover:bg-gray-50 p-1.5 rounded">
                      <input
                        type="checkbox"
                        checked={layers.showTerrain}
                        onChange={() => toggleLayer('showTerrain')}
                        className="w-4 h-4 text-blue-600 rounded"
                      />
                      <div className="h-4 w-4 bg-gradient-to-b from-green-200 to-amber-200 rounded"></div>
                      <span className="text-sm font-medium">Terrain Relief</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer hover:bg-gray-50 p-1.5 rounded">
                      <input
                        type="checkbox"
                        checked={layers.showLabels}
                        onChange={() => toggleLayer('showLabels')}
                        className="w-4 h-4 text-blue-600 rounded"
                      />
                      <span className="text-sm font-medium">Feature Labels</span>
                    </label>
                  </div>
                </div>
              )}

              <svg
                ref={svgRef}
                viewBox={`0 0 ${width} ${height}`}
                className={`w-full h-auto ${isDragging ? 'cursor-grabbing' : 'cursor-grab'}`}
                style={{ maxHeight: '600px' }}
                onMouseDown={handleMouseDown}
                onMouseMove={handleMouseMove}
                onMouseUp={handleMouseUp}
                onMouseLeave={handleMouseUp}
                onWheel={handleWheel}
              >
                {/* Ocean - Google Maps style */}
                <rect
                  width={width}
                  height={height}
                  fill="#A8C5DD"
                  className="pointer-events-all"
                />

                {/* Ocean gradient for depth effect */}
                <defs>
                  <radialGradient id="oceanGradient" cx="50%" cy="50%">
                    <stop offset="0%" stopColor="#B8D4E8" />
                    <stop offset="100%" stopColor="#A8C5DD" />
                  </radialGradient>
                </defs>

                {/* Terrain Relief (if enabled) */}
                {layers.showTerrain && (
                  <g opacity="0.3">
                    {/* Add terrain shading here - would use DEM data in production */}
                  </g>
                )}

                {/* Countries with Google Maps styling */}
                <g>
                  {countries.map((country, idx) => {
                    const countryCode = country.properties.iso_a2;
                    const isHovered = hoveredCountry === countryCode;

                    try {
                      const path = pathGenerator(country.geometry as Parameters<typeof pathGenerator>[0]);
                      if (!path) return null;

                      return (
                        <g key={`${country.id}-${idx}`}>
                          {/* Country fill */}
                          <path
                            d={path}
                            fill={getCountryFill(countryCode, isHovered)}
                            stroke="#E5E3D8"
                            strokeWidth={0.5}
                            className="cursor-pointer transition-colors duration-200"
                            onClick={(): void => onCountryClick(countryCode)}
                            onMouseEnter={(): void => setHoveredCountry(countryCode)}
                            onMouseLeave={(): void => setHoveredCountry(null)}
                          />
                          {/* Country border - thicker for visual clarity */}
                          <path
                            d={path}
                            fill="none"
                            stroke="#D4D2C5"
                            strokeWidth={0.8}
                            opacity={0.7}
                            className="pointer-events-none"
                          />
                        </g>
                      );
                    } catch (_err) {
                      return null;
                    }
                  })}
                </g>

                {/* Country Labels */}
                {layers.showLabels && (
                  <g className="country-labels">
                    {countries.map((country, idx) => {
                      try {
                        // Calculate centroid of the country for label placement
                        const bounds = pathGenerator.bounds(country.geometry as Parameters<typeof pathGenerator.bounds>[0]);
                        if (!bounds || bounds[0][0] === Infinity) return null;

                        const centerX = (bounds[0][0] + bounds[1][0]) / 2;
                        const centerY = (bounds[0][1] + bounds[1][1]) / 2;

                        // Calculate area to determine font size
                        const area = pathGenerator.area(country.geometry as Parameters<typeof pathGenerator.area>[0]);
                        const isLarge = area > 5000;
                        const isMedium = area > 1000;
                        const isSmall = area > 200;

                        // Only show labels for countries with reasonable size
                        if (area < 100) return null;

                        const fontSize = isLarge ? 11 : isMedium ? 9 : isSmall ? 7 : 6;
                        const fontWeight = isLarge ? '700' : '600';

                        return (
                          <text
                            key={`label-${country.id}-${idx}`}
                            x={centerX}
                            y={centerY}
                            fontSize={fontSize}
                            fontWeight={fontWeight}
                            fill="#5A5A5A"
                            textAnchor="middle"
                            dominantBaseline="middle"
                            className="pointer-events-none select-none"
                            stroke="#FFFFFF"
                            strokeWidth="0.5"
                            paintOrder="stroke"
                            style={{ textTransform: 'uppercase', letterSpacing: '0.5px' }}
                          >
                            {country.properties.name}
                          </text>
                        );
                      } catch (_err) {
                        return null;
                      }
                    })}
                  </g>
                )}

                {/* State/Province Boundaries (if enabled) - Google Maps style */}
                {layers.showStates && statesData.length > 0 && (
                  <g className="states">
                    {statesData.map((state, idx) => {
                      try {
                        const path = pathGenerator(state.geometry as Parameters<typeof pathGenerator>[0]);
                        if (!path) return null;

                        return (
                          <path
                            key={`state-${idx}`}
                            d={path}
                            fill="none"
                            stroke="#C4C2B8"
                            strokeWidth="0.4"
                            strokeDasharray="3,2"
                            opacity="0.6"
                          />
                        );
                      } catch (_err) {
                        return null;
                      }
                    })}
                  </g>
                )}

                {/* Deserts (if enabled) - Google Maps terrain style */}
                {layers.showDeserts && (
                  <g className="deserts" opacity="0.35">
                    {worldDeserts.map((desert, idx) => {
                      const coords = project(desert.lat, desert.lon);
                      if (!coords) return null;

                      // Draw desert as a shaded circle with terrain colors
                      const radius = Math.sqrt(desert.area) / 1500; // Scale based on area

                      return (
                        <g key={`desert-${idx}`}>
                          <circle
                            cx={coords[0]}
                            cy={coords[1]}
                            r={radius}
                            fill="#F5E6D3"
                            stroke="#E8D4B8"
                            strokeWidth="0.8"
                            opacity="0.6"
                          />
                          {layers.showLabels && desert.area > 500000 && (
                            <text
                              x={coords[0]}
                              y={coords[1]}
                              fontSize="7"
                              fill="#A67C52"
                              fontWeight="600"
                              textAnchor="middle"
                              stroke="#FFFFFF"
                              strokeWidth="0.3"
                              paintOrder="stroke"
                            >
                              {desert.name}
                            </text>
                          )}
                        </g>
                      );
                    })}
                  </g>
                )}

                {/* Lakes (if enabled) - Google Maps style */}
                {layers.showLakes && (
                  <g className="lakes">
                    {worldLakes.map((lake, idx) => {
                      const coords = project(lake.lat, lake.lon);
                      if (!coords) return null;

                      // Scale lake size based on area
                      const radius = Math.sqrt(lake.area) / 200;

                      return (
                        <g key={`lake-${idx}`}>
                          {/* Lake water with realistic blue */}
                          <circle
                            cx={coords[0]}
                            cy={coords[1]}
                            r={radius}
                            fill="#A8C5DD"
                            stroke="#8FA9C4"
                            strokeWidth="0.5"
                            opacity="0.9"
                          />
                          {/* Water shimmer effect */}
                          <circle
                            cx={coords[0] - radius * 0.2}
                            cy={coords[1] - radius * 0.2}
                            r={radius * 0.3}
                            fill="#B8D4E8"
                            opacity="0.3"
                          />
                          {layers.showLabels && lake.area > 30000 && (
                            <text
                              x={coords[0]}
                              y={coords[1] + radius + 8}
                              fontSize="7"
                              fill="#4A6A86"
                              fontWeight="600"
                              textAnchor="middle"
                              stroke="#FFFFFF"
                              strokeWidth="0.3"
                              paintOrder="stroke"
                            >
                              {lake.name}
                            </text>
                          )}
                        </g>
                      );
                    })}
                  </g>
                )}

                {/* Rivers (if enabled) - Google Maps style */}
                {layers.showRivers && (
                  <g className="rivers">
                    {worldRivers.map((river, idx) => {
                      const pathPoints = river.path
                        .map(point => project(point.lat, point.lon))
                        .filter((p): p is [number, number] => p !== null);

                      if (pathPoints.length < 2) return null;

                      const riverPath = `M ${pathPoints.map(p => `${p[0]},${p[1]}`).join(' L ')}`;

                      // Scale river width based on length (major rivers are wider)
                      const riverWidth = river.length > 5000 ? 2.8 : river.length > 3000 ? 2.0 : 1.4;

                      return (
                        <g key={`river-${idx}`}>
                          {/* River border/outline */}
                          <path
                            d={riverPath}
                            stroke="#8FA9C4"
                            strokeWidth={riverWidth + 0.6}
                            fill="none"
                            opacity="0.4"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                          />
                          {/* Main river body - realistic water blue */}
                          <path
                            d={riverPath}
                            stroke="#A8C5DD"
                            strokeWidth={riverWidth}
                            fill="none"
                            opacity="0.85"
                            strokeLinecap="round"
                            strokeLinejoin="round"
                          />
                          {layers.showLabels && river.length > 3000 && pathPoints.length > 0 && (
                            <text
                              x={pathPoints[Math.floor(pathPoints.length / 2)][0]}
                              y={pathPoints[Math.floor(pathPoints.length / 2)][1] - 5}
                              fontSize="7"
                              fill="#4A6A86"
                              fontWeight="600"
                              textAnchor="middle"
                              stroke="#FFFFFF"
                              strokeWidth="0.4"
                              paintOrder="stroke"
                            >
                              {river.name}
                            </text>
                          )}
                        </g>
                      );
                    })}
                  </g>
                )}

                {/* Mountains (if enabled) - Enhanced with 3D relief */}
                {layers.showMountains && (
                  <g className="mountains">
                    {worldMountains.flatMap((range, rangeIdx) =>
                      range.peaks?.map((peak: { lat: number; lon: number; elevation: number; name: string }, peakIdx: number) => {
                        const coords = project(peak.lat, peak.lon);
                        if (!coords) return null;

                        // Scale mountain size based on elevation
                        const baseSize = peak.elevation > 8000 ? 8 :
                                        peak.elevation > 7000 ? 6.5 :
                                        peak.elevation > 5000 ? 5 :
                                        peak.elevation > 3000 ? 4 : 3;

                        const size = baseSize * (zoom > 1 ? Math.min(zoom * 0.8, 1.5) : 1);

                        // Color gradients for realistic terrain
                        const isSnowCapped = peak.elevation > 7000;
                        const isMajor = peak.elevation > 5000;

                        return (
                          <g key={`peak-${rangeIdx}-${peakIdx}`}>
                            {/* Mountain shadow base */}
                            <path
                              d={`M ${coords[0]},${coords[1] - size} L ${coords[0] - size * 1.2},${coords[1] + size} L ${coords[0] + size * 1.2},${coords[1] + size} Z`}
                              fill="#4A3F35"
                              opacity="0.3"
                            />

                            {/* Mountain body - dark side (left) */}
                            <path
                              d={`M ${coords[0]},${coords[1] - size} L ${coords[0] - size},${coords[1] + size} L ${coords[0]},${coords[1] + size * 0.5} Z`}
                              fill={isSnowCapped ? '#E0E7EF' : isMajor ? '#6B5D52' : '#8B7355'}
                              stroke="#3D342D"
                              strokeWidth="0.3"
                            />

                            {/* Mountain body - light side (right) */}
                            <path
                              d={`M ${coords[0]},${coords[1] - size} L ${coords[0]},${coords[1] + size * 0.5} L ${coords[0] + size},${coords[1] + size} Z`}
                              fill={isSnowCapped ? '#F8FAFC' : isMajor ? '#9B8B7E' : '#B5A088'}
                              stroke="#3D342D"
                              strokeWidth="0.3"
                            />

                            {/* Snow cap for high peaks */}
                            {isSnowCapped && (
                              <path
                                d={`M ${coords[0]},${coords[1] - size} L ${coords[0] - size * 0.4},${coords[1] - size * 0.3} L ${coords[0]},${coords[1]} L ${coords[0] + size * 0.4},${coords[1] - size * 0.3} Z`}
                                fill="#FFFFFF"
                                opacity="0.9"
                              />
                            )}

                            {/* Highlight edge */}
                            <line
                              x1={coords[0]}
                              y1={coords[1] - size}
                              x2={coords[0] + size * 0.7}
                              y2={coords[1] + size * 0.3}
                              stroke={isSnowCapped ? '#FFFFFF' : '#D4C4B0'}
                              strokeWidth="0.5"
                              opacity="0.6"
                            />

                            {layers.showLabels && peak.elevation > 6000 && (
                              <text
                                x={coords[0]}
                                y={coords[1] - size - 4}
                                fontSize="7"
                                fill="#3D342D"
                                fontWeight="700"
                                textAnchor="middle"
                                stroke="#FFFFFF"
                                strokeWidth="0.4"
                                paintOrder="stroke"
                              >
                                {peak.name}
                              </text>
                            )}
                          </g>
                        );
                      })
                    )}
                  </g>
                )}
              </svg>

              {/* Hover info */}
              {hoveredCountry && (
                <div className="mt-4 text-center">
                  <div className="inline-block bg-gray-100 rounded px-4 py-2">
                    <p className="text-lg font-medium text-gray-900">
                      {countries.find(c => c.properties.iso_a2 === hoveredCountry)?.properties.name}
                    </p>
                    <p className="text-sm text-gray-600">
                      {visitedCountries[hoveredCountry] !== undefined && visitedCountries[hoveredCountry] !== null
                        ? `✓ ${visitedCountries[hoveredCountry].charAt(0).toUpperCase() + visitedCountries[hoveredCountry].slice(1)}`
                        : 'Click to mark as visited'
                      }
                    </p>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Country List Sidebar */}
          {showList && (
            <div className="w-1/5 min-w-[250px]">
              <div className="bg-white rounded-lg border border-gray-200 p-4 sticky top-6 max-h-[calc(100vh-8rem)] overflow-y-auto">
                <h3 className="text-lg font-semibold text-gray-900 mb-4">Countries</h3>
                <div className="space-y-1">
                  {countries.map((country, idx) => {
                    const countryCode = country.properties.iso_a2;
                    const isVisited = !!visitedCountries[countryCode];

                    return (
                      <label
                        key={`${country.id}-${idx}`}
                        className="flex items-center gap-2 px-2 py-1.5 rounded hover:bg-gray-50 cursor-pointer transition-colors"
                        onMouseEnter={(): void => setHoveredCountry(countryCode)}
                        onMouseLeave={(): void => setHoveredCountry(null)}
                      >
                        <input
                          type="checkbox"
                          checked={isVisited}
                          onChange={(): void => onCountryClick(countryCode)}
                          className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
                        />
                        <span className="text-sm text-gray-700">
                          {country.properties.name}
                        </span>
                        {isVisited && (
                          <span className="ml-auto text-xs text-blue-600 font-medium">
                            {visitedCountries[countryCode]}
                          </span>
                        )}
                      </label>
                    );
                  })}
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Legend */}
        <div className="mt-6 bg-white rounded-lg border border-gray-200 p-4">
          <h4 className="text-sm font-semibold text-gray-700 mb-3 text-center">Map Legend</h4>
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
            <div className="flex items-center gap-2">
              <div className="w-6 h-6 rounded border border-gray-300" style={{ backgroundColor: '#86EFAC' }}></div>
              <span className="text-xs text-gray-700 font-medium">Visited</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-6 h-6 rounded border border-gray-300" style={{ backgroundColor: '#F3F1E8' }}></div>
              <span className="text-xs text-gray-700 font-medium">Not Visited</span>
            </div>
            {layers.showRivers && (
              <div className="flex items-center gap-2">
                <Waves className="h-5 w-5 text-blue-600" />
                <span className="text-xs text-gray-700 font-medium">{worldRivers.length} Rivers</span>
              </div>
            )}
            {layers.showMountains && (
              <div className="flex items-center gap-2">
                <Mountain className="h-5 w-5 text-amber-800" />
                <span className="text-xs text-gray-700 font-medium">{worldMountains.reduce((s, r) => s + (r.peaks?.length ?? 0), 0)} Peaks</span>
              </div>
            )}
            {layers.showLakes && (
              <div className="flex items-center gap-2">
                <Droplets className="h-5 w-5 text-cyan-500" />
                <span className="text-xs text-gray-700 font-medium">{worldLakes.length} Lakes</span>
              </div>
            )}
            {layers.showDeserts && (
              <div className="flex items-center gap-2">
                <div className="w-5 h-5 rounded-full bg-yellow-100 border border-yellow-400"></div>
                <span className="text-xs text-gray-700 font-medium">{worldDeserts.length} Deserts</span>
              </div>
            )}
            {layers.showStates && statesData.length > 0 && (
              <div className="flex items-center gap-2">
                <MapPin className="h-5 w-5 text-gray-500" />
