/**
 * Comprehensive financial data types for the Finance Hub
 * Provides type safety for all financial operations
 */

// Base types
export type Currency = 'USD' | 'EUR' | 'GBP' | 'CAD' | 'AUD';
export type AccountType = 'checking' | 'savings' | 'credit' | 'investment' | 'loan' | 'other';
export type TransactionType = 'income' | 'expense' | 'transfer';
export type TransactionStatus = 'pending' | 'completed' | 'failed' | 'cancelled';
export type CategoryType = 'income' | 'expense';
export type BudgetPeriod = 'weekly' | 'monthly' | 'quarterly' | 'yearly';
export type BudgetStatus = 'on_track' | 'warning' | 'over_budget';
export type GoalStatus = 'active' | 'completed' | 'paused' | 'cancelled';

// Account Management
export interface Account {
  id: string;
  name: string;
  type: AccountType;
  balance: number;
  currency: Currency;
  institution: string;
  accountNumber: string;
  routingNumber?: string;
  isActive: boolean;
  lastSynced: Date;
  syncEnabled?: boolean;
  notes?: string;
  createdAt: Date;
  updatedAt: Date;

  // Credit card specific fields
  creditLimit?: number;
  apr?: number;
  paymentDueDay?: number;
  minimumPayment?: number;
  statementBalance?: number;
  statementDate?: Date;

  // Rewards tracking
  annualFee?: number;
  annualFeeDueDate?: Date;
  rewardsBalance?: number;
  rewardsType?: 'points' | 'miles' | 'cashback';
  baseRewardsRate?: number;
}

// Transaction Management
export interface RecurringPattern {
  frequency: 'daily' | 'weekly' | 'monthly' | 'quarterly' | 'yearly';
  interval: number; // e.g., every 2 weeks = frequency: 'weekly', interval: 2
  endDate?: Date;
  nextDue?: Date;
}

export interface Transaction {
  id: string;
  accountId: string;
  description: string;
  amount: number; // Positive for income, negative for expenses
  category: string;
  subcategory?: string;
  date: Date;
  status: TransactionStatus;
  type: TransactionType;
  merchant?: string;
  location?: string;
  notes?: string;
  tags?: string[];
  receiptUrl?: string;
  isRecurring: boolean;
  recurringPattern?: RecurringPattern;
  parentTransactionId?: string; // For split transactions
  splits?: TransactionSplit[];
  createdAt: Date;
  updatedAt: Date;
}

export interface TransactionSplit {
  id: string;
  amount: number;
  category: string;
  description?: string;
}

// Category Management
export interface TransactionCategory {
  id: string;
  name: string;
  type: CategoryType;
  icon: string;
  color: string;
  parentId?: string; // For subcategories
  isActive: boolean;
  monthlyBudget?: number;
  description?: string;
  createdAt: Date;
  updatedAt: Date;
}

// Budget Management
export interface Budget {
  id: string;
  name: string;
  categoryIds: string[];
  limit: number;
  spent: number;
  remaining: number;
  period: BudgetPeriod;
  startDate: Date;
  endDate: Date;
  alertThreshold: number; // Percentage (0-100)
  status: BudgetStatus;
  rollover: boolean; // Carry over unused budget to next period
  notes?: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface BudgetAlert {
  id: string;
  budgetId: string;
  type: 'approaching_limit' | 'over_limit' | 'monthly_summary';
  message: string;
  threshold: number;
  isRead: boolean;
  createdAt: Date;
}

// Financial Goals
export interface FinancialGoal {
  id: string;
