// Utility Types
export type Dateish = Date | string | number;
export type Optional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
export type CreateType<T> = Omit<T, 'id' | 'createdAt' | 'updatedAt'>;
export type UpdateType<T> = Partial<Omit<T, 'id' | 'createdAt'>> & { updatedAt: Date };

// Export grouped types for convenience
export type TransactionTypes = Transaction | TransactionSplit | TransactionCategory | RecurringPattern;
export type BudgetTypes = Budget | BudgetAlert;
export type GoalTypes = FinancialGoal | GoalMilestone;
export type InvestmentTypes = Investment | PortfolioAllocation;
export type AnalyticsTypes = FinancialInsight | SpendingTrend | FinancialHealth | FinancialReport;
export type AlertTypes = FinancialAlert | BudgetAlert;

/**
 * Enhanced Focus Mode Types
 * 
 * Comprehensive type definitions for all advanced focus features including
 * analytics, gamification, integrations, wellness tracking, and more.
 */

// ==================== Core Focus Types ====================

export interface FocusSession {
  id: string;
  userId?: string;
  type: 'focus' | 'break' | 'long-break';
  preset: FocusPreset;
  startTime: Date;
  endTime?: Date;
  plannedDuration: number; // in seconds
  actualDuration?: number; // in seconds
  status: 'planned' | 'active' | 'paused' | 'completed' | 'cancelled';
  pausedTime?: number; // total time paused
  distractions: DistractionEvent[];
  taskId?: string;
  projectId?: string;
  notes?: string;
  mood?: 'great' | 'good' | 'okay' | 'tired' | 'stressed';
  energy?: 1 | 2 | 3 | 4 | 5;
  productivity?: 1 | 2 | 3 | 4 | 5;
  tags?: string[];
  location?: string;
  weather?: string;
  backgroundMusic?: string;
  completionReward?: number; // XP points
}

export interface FocusPreset {
  id: string;
  name: string;
  description: string;
  icon: string;
  color: string;
  duration: number; // in minutes
  breakDuration?: number;
  longBreakAfter?: number; // sessions
  longBreakDuration?: number;
  musicType?: string;
  distractionLevel: 'minimal' | 'moderate' | 'strict';
  notifications: NotificationSettings;
  blockedSites?: string[];
  allowedSites?: string[];
  isCustom: boolean;
  isDefault: boolean;
  usageCount: number;
  createdBy: string;
  createdAt: Date;
  category: 'work' | 'study' | 'creative' | 'personal' | 'health';
}

export interface DistractionEvent {
  id: string;
  sessionId: string;
  timestamp: Date;
  type: 'pause' | 'website' | 'app' | 'notification' | 'manual';
  source?: string; // website/app that caused distraction
  duration?: number; // how long the distraction lasted
  handled: boolean; // was it blocked or allowed
  severity: 'low' | 'medium' | 'high';
}

