// Quick Add parsing utilities for tasks and subtasks
// Pure functions so they are easy to test with Vitest

export type Priority = 'urgent' | 'high' | 'medium' | 'low'

export interface ProjectRef { id: string; name: string }

export interface TaskQuickAddResult {
  title: string
  priority: Priority
  dueDate: Date | null
  projectId: string
  tags: string[]
}

export interface SubtaskQuickAddResult {
  title: string
  priority?: Priority
  dueDate: Date | null
  tags: string[]
}

const normalizeWhitespace = (s: string) => s.replace(/\s{2,}/g, ' ').trim()

// Parse main Quick Add text
export function parseQuickAdd(text: string, projects: ProjectRef[]): TaskQuickAddResult {
  let title = text
  let priority: Priority = 'medium'
  let dueDate: Date | null = null
  let projectId = ''
  const tagSet = new Set<string>()

  // Dates first: @today, @tomorrow, @YYYY-MM-DD
  if (/@today\b/i.test(text)) {
    dueDate = new Date()
    title = title.replace(/@today\b/ig, '').trim()
  } else if (/@tomorrow\b/i.test(text)) {
    const d = new Date(); d.setDate(d.getDate() + 1)
    dueDate = d
    title = title.replace(/@tomorrow\b/ig, '').trim()
  } else {
    const dm = text.match(/@(\d{4}-\d{2}-\d{2})/)
    if (dm) {
      const d = new Date(dm[1])
      if (!isNaN(d.getTime())) dueDate = d
      title = title.replace(/@(\d{4}-\d{2}-\d{2})/, '').trim()
    }
  }

  // Priority: !urgent|!high|!medium|!low or !1..4; fallback p1..p4
  const prio = text.match(/!(urgent|high|medium|low|[1-4])/i)
  if (prio) {
    const p = prio[1].toLowerCase()
    if (p === 'urgent' || p === 'high' || p === 'medium' || p === 'low') {
      priority = p as Priority
    } else {
      const n = parseInt(p, 10)
      priority = n === 1 ? 'urgent' : n === 2 ? 'high' : n === 3 ? 'medium' : 'low'
    }
    title = title.replace(/!(urgent|high|medium|low|[1-4])/i, '').trim()
  } else {
    const pm = text.match(/\bp([1-4])\b/i)
    if (pm) {
      const n = parseInt(pm[1], 10)
      priority = n === 1 ? 'urgent' : n === 2 ? 'high' : n === 3 ? 'medium' : 'low'
      title = title.replace(/\bp[1-4]\b/i, '').trim()
    }
  }

  // Explicit project: #project:Name or #project:"Name With Spaces"
  const projectTokenMatch = text.match(/#project:("([^"]+)"|[^\s#@!]+)/i)
  if (projectTokenMatch) {
    const rawName = (projectTokenMatch[2] || projectTokenMatch[1] || '').replace(/^"|"$/g, '')
    const project = projects.find(p => p.name.toLowerCase().includes(rawName.toLowerCase()))
    if (project) projectId = project.id
    title = title.replace(projectTokenMatch[0], '').trim()
  }

  // Remaining #tokens become tags (skip #project:...)
  const hashTokens = title.match(/#([\w-:"']+)/g) || []
  for (const token of hashTokens) {
    if (/^#project:/i.test(token)) {
      title = title.replace(new RegExp(token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')), '').trim()
      continue
    }
    const name = token.slice(1)
    tagSet.add(name)
    title = title.replace(new RegExp(token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')), '').trim()
  }

  // @tags (non-date) also become tags
  const atTokens = title.match(/@([\w-]+)/g) || []
  for (const token of atTokens) {
    const t = token.slice(1)
    if (t.toLowerCase() !== 'today' && t.toLowerCase() !== 'tomorrow') tagSet.add(t)
    title = title.replace(new RegExp(token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')), '').trim()
  }

  title = normalizeWhitespace(title)
  return { title, priority, dueDate, projectId, tags: Array.from(tagSet) }
}

// Parse subtask Quick Add text
export function parseSubtaskQuickAdd(text: string): SubtaskQuickAddResult {
  let title = text
  const tags: string[] = []
  let dueDate: Date | null = null
  let priority: Priority | undefined

  // Tags #word or #word-with-dash
  const tagMatches = text.match(/#([\w-]+)/g)
  if (tagMatches) {
    for (const m of tagMatches) {
      const t = m.slice(1)
      if (t) tags.push(t)
    }
    title = title.replace(/#([\w-]+)/g, '').trim()
  }

  // Dates: @today, @tomorrow, @YYYY-MM-DD
  if (/@today\b/i.test(text)) {
    dueDate = new Date()
    title = title.replace(/@today\b/ig, '').trim()
  } else if (/@tomorrow\b/i.test(text)) {
    const d = new Date(); d.setDate(d.getDate() + 1)
    dueDate = d
    title = title.replace(/@tomorrow\b/ig, '').trim()
  } else {
    const dateMatch = text.match(/@(\d{4}-\d{2}-\d{2})/)
    if (dateMatch) {
      const d = new Date(dateMatch[1])
      if (!isNaN(d.getTime())) dueDate = d
      title = title.replace(/@(\d{4}-\d{2}-\d{2})/, '').trim()
    }
  }

  // Priority: !urgent|!high|!medium|!low or !1..4
  const prioMatch = text.match(/!(urgent|high|medium|low|[1-4])/i)
  if (prioMatch) {
    const p = prioMatch[1].toLowerCase()
    if (p === 'urgent' || p === 'high' || p === 'medium' || p === 'low') {
      priority = p as Priority
    } else {
      const n = parseInt(p, 10)
      priority = n === 1 ? 'urgent' : n === 2 ? 'high' : n === 3 ? 'medium' : 'low'
    }
    title = title.replace(/!(urgent|high|medium|low|[1-4])/i, '').trim()
  } else {
    const pm = text.match(/\bp([1-4])\b/i)
    if (pm) {
      const n = parseInt(pm[1], 10)
      priority = n === 1 ? 'urgent' : n === 2 ? 'high' : n === 3 ? 'medium' : 'low'
      title = title.replace(/\bp[1-4]\b/i, '').trim()
    }
  }

  title = normalizeWhitespace(title)
  return { title, tags, dueDate, priority }
}

// Parse simple natural time windows like: today, yesterday, this week, last week,
// this month, last month, last N days
export function parseTimeWindow(text: string): { fromISO?: string; toISO?: string } | undefined {
  const t = text.toLowerCase()
  const now = new Date()
  const end = new Date(now)
  const start = new Date(now)

  const toISO = (d: Date) => d.toISOString()

  const setToStartOfDay = (d: Date) => { d.setUTCHours(0,0,0,0); return d }
  const setToEndOfDay = (d: Date) => { d.setUTCHours(23,59,59,999); return d }

  if (t.includes('today')) {
    return { fromISO: toISO(setToStartOfDay(start)), toISO: toISO(setToEndOfDay(end)) }
  }
  if (t.includes('yesterday')) {
    start.setUTCDate(start.getUTCDate() - 1)
    end.setUTCDate(end.getUTCDate() - 1)
    return { fromISO: toISO(setToStartOfDay(start)), toISO: toISO(setToEndOfDay(end)) }
  }
  if (t.includes('this week')) {
    const day = start.getUTCDay() || 7
    start.setUTCDate(start.getUTCDate() - (day - 1))
    return { fromISO: toISO(setToStartOfDay(start)), toISO: toISO(setToEndOfDay(end)) }
  }
  if (t.includes('last week')) {
    const day = start.getUTCDay() || 7
    start.setUTCDate(start.getUTCDate() - (day - 1) - 7)
    end.setUTCDate(start.getUTCDate() + 6)
    return { fromISO: toISO(setToStartOfDay(start)), toISO: toISO(setToEndOfDay(end)) }
  }
  if (t.includes('this month')) {
    start.setUTCDate(1)
    return { fromISO: toISO(setToStartOfDay(start)), toISO: toISO(setToEndOfDay(end)) }
  }
  if (t.includes('last month')) {
    start.setUTCMonth(start.getUTCMonth() - 1, 1)
    end.setUTCMonth(start.getUTCMonth() + 1, 0)
    return { fromISO: toISO(setToStartOfDay(start)), toISO: toISO(setToEndOfDay(end)) }
  }
  const m = t.match(/last (\d+) days/)
  if (m) {
    const days = parseInt(m[1], 10)
    start.setUTCDate(start.getUTCDate() - days)
    return { fromISO: toISO(setToStartOfDay(start)), toISO: toISO(setToEndOfDay(end)) }
  }
  return undefined
}

import { serve } from "https://deno.land/std@0.224.0/http/server.ts";

type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue };

type ApiResponseBody = {
  error?: string;
  status?: number;
  details?: JsonValue;
  data?: JsonValue;
};

const baseCorsHeaders = {
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
};

function resolveAllowedOrigin(requestOrigin: string | null): string {
  const configured = Deno.env.get("ALLOWED_ORIGINS")?.split(",").map((origin) => origin.trim()).filter(Boolean);
  if (!configured || configured.length === 0 || configured.includes("*")) {
    return "*";
  }
  if (requestOrigin && configured.includes(requestOrigin)) {
    return requestOrigin;
  }
  return configured[0];
}

function buildCorsHeaders(requestOrigin: string | null) {
  return {
    ...baseCorsHeaders,
    "Access-Control-Allow-Origin": resolveAllowedOrigin(requestOrigin),
  } as Record<string, string>;
}

function jsonResponse(body: ApiResponseBody | JsonValue, status: number, headers: Record<string, string>) {
  const payload = typeof body === "object" ? JSON.stringify(body) : String(body);
  return new Response(payload, {
    status,
    headers: {
      "Content-Type": "application/json",
      ...headers,
    },
  });
}

async function handleRequest(req: Request): Promise<Response> {
  const origin = req.headers.get("origin");
  const corsHeaders = buildCorsHeaders(origin);

  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "GET" && req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed" }, 405, corsHeaders);
  }

  const apiKey = Deno.env.get("YOUTUBE_API_KEY");
  const apiBaseUrl = Deno.env.get("YOUTUBE_API_BASE_URL") ?? "https://www.googleapis.com/youtube/v3/videos";

  if (!apiBaseUrl) {
    return jsonResponse({ error: "Server misconfiguration: missing API base URL" }, 500, corsHeaders);
  }

  let videoId: string | undefined;

  try {
    if (req.method === "GET") {
      const url = new URL(req.url);
      videoId = url.searchParams.get("videoId") ?? undefined;
    } else {
      const body = await req.json().catch(() => null) as { videoId?: string } | null;
      videoId = body?.videoId;
    }
  } catch (error) {
    return jsonResponse({ error: "Invalid request payload", details: String(error) }, 400, corsHeaders);
  }

  if (!videoId) {
    return jsonResponse({ error: "Missing videoId" }, 400, corsHeaders);
  }

  const upstreamUrl = new URL(apiBaseUrl);
  if (!upstreamUrl.searchParams.has("part")) {
    upstreamUrl.searchParams.set("part", "snippet");
  }
  upstreamUrl.searchParams.set("id", videoId);

  const isYoutubeDataApi = upstreamUrl.host.endsWith("googleapis.com");
  if (isYoutubeDataApi) {
    if (!apiKey) {
      return jsonResponse({ error: "Server misconfiguration: missing YOUTUBE_API_KEY" }, 500, corsHeaders);
    }
    upstreamUrl.searchParams.set("key", apiKey);
  }

  let upstreamResponse: Response;
  try {
    upstreamResponse = await fetch(upstreamUrl.toString(), {
      headers: {
        Accept: "application/json",
      },
    });
  } catch (error) {
    return jsonResponse({
      error: "Upstream request failed",
      details: String(error),
    }, 502, corsHeaders);
  }

  const textPayload = await upstreamResponse.text();

  if (!upstreamResponse.ok) {
    return new Response(textPayload, {
      status: upstreamResponse.status,
      headers: {
        "Content-Type": upstreamResponse.headers.get("content-type") ?? "application/json",
        ...corsHeaders,
      },
    });
  }

  return new Response(textPayload, {
    status: 200,
    headers: {
      "Content-Type": upstreamResponse.headers.get("content-type") ?? "application/json",
      ...corsHeaders,
    },
  });
}

serve(handleRequest);

// Supabase Edge Function to send connection invitation emails
// Deploy with: supabase functions deploy send-invitation-email

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const RESEND_API_KEY = Deno.env.get('RESEND_API_KEY') // Free tier: 3,000 emails/month

interface InvitationEmailRequest {
  to: string
  fromEmail: string
  fromName?: string
  relationship: string
  message?: string
  invitationUrl: string
}

serve(async (req) => {
  try {
    // CORS headers
    if (req.method === 'OPTIONS') {
      return new Response('ok', {
        headers: {
          'Access-Control-Allow-Origin': '*',
          'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
        },
      })
    }

    // Verify authentication
    const authHeader = req.headers.get('Authorization')
    if (!authHeader) {
      return new Response(JSON.stringify({ error: 'No authorization header' }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    const supabaseClient = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
      { global: { headers: { Authorization: authHeader } } }
    )

    const {
      data: { user },
    } = await supabaseClient.auth.getUser()

    if (!user) {
      return new Response(JSON.stringify({ error: 'Invalid user' }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    // Parse request body
    const { to, fromEmail, fromName, relationship, message, invitationUrl }: InvitationEmailRequest =
      await req.json()

    // Send email using Resend (free tier available)
    const emailResponse = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${RESEND_API_KEY}`,
      },
      body: JSON.stringify({
        from: 'LifeSync <noreply@lifesync.app>', // Replace with your domain
        to: [to],
        subject: `${fromName || fromEmail} wants to connect with you on LifeSync`,
        html: `
          <!DOCTYPE html>
          <html>
            <head>
              <meta charset="utf-8">
              <meta name="viewport" content="width=device-width, initial-scale=1.0">
              <title>Connection Invitation</title>
            </head>
            <body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; line-height: 1.6; color: #334155; max-width: 600px; margin: 0 auto; padding: 20px;">
              <div style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); padding: 30px; border-radius: 12px 12px 0 0; text-align: center;">
                <h1 style="color: white; margin: 0; font-size: 28px;">LifeSync</h1>
                <p style="color: rgba(255,255,255,0.9); margin: 10px 0 0 0; font-size: 16px;">Connection Invitation</p>
              </div>

              <div style="background: #ffffff; padding: 30px; border: 1px solid #e2e8f0; border-top: none; border-radius: 0 0 12px 12px;">
                <p style="font-size: 18px; margin-top: 0;">Hi there! 👋</p>

                <p style="font-size: 16px; line-height: 1.8;">
                  <strong>${fromName || fromEmail}</strong> has invited you to connect on LifeSync as their <strong>${relationship}</strong>.
                </p>

                ${
                  message
                    ? `
                <div style="background: #f8fafc; border-left: 4px solid #667eea; padding: 15px; margin: 20px 0; border-radius: 4px;">
                  <p style="margin: 0; font-style: italic; color: #475569;">"${message}"</p>
                </div>
                `
                    : ''
                }

                <p style="font-size: 16px; line-height: 1.8;">
                  By connecting, you'll be able to share data across different modules with granular permission controls. You decide what to share!
                </p>

                <div style="text-align: center; margin: 30px 0;">
                  <a href="${invitationUrl}" style="display: inline-block; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 14px 32px; text-decoration: none; border-radius: 8px; font-weight: 600; font-size: 16px; box-shadow: 0 4px 6px rgba(102, 126, 234, 0.25);">
                    View Invitation
                  </a>
                </div>

                <div style="background: #fef3c7; border: 1px solid #fcd34d; border-radius: 8px; padding: 15px; margin-top: 25px;">
                  <p style="margin: 0; font-size: 14px; color: #92400e;">
                    <strong>🔒 Privacy First:</strong> You have complete control over what data you share. Configure permissions for each module independently.
                  </p>
                </div>

                <hr style="border: none; border-top: 1px solid #e2e8f0; margin: 30px 0;">

                <p style="font-size: 13px; color: #94a3b8; margin: 0;">
                  If you don't have a LifeSync account, you'll need to sign up first. This invitation will be waiting for you!
                </p>
              </div>

              <div style="text-align: center; padding: 20px; font-size: 12px; color: #94a3b8;">
                <p style="margin: 5px 0;">LifeSync - Your Personal Life Management Platform</p>
                <p style="margin: 5px 0;">
                  <a href="https://lifesync.app" style="color: #667eea; text-decoration: none;">Visit Website</a> •
